// 2. Application Reactive State
const state = {
    screenMode: (function() {
        try {
            const saved = localStorage.getItem("hsong_screen_mode");
            if (saved) return saved;
            return (typeof window !== "undefined" && window.innerWidth >= 1024) ? "pc" : "mobile";
        } catch (e) {
            return "pc";
        }
    })(),
    currentRole: "customer",
    currentScreen: "market",
    currentCategoryFilter: "all", // 'all' or main category name (Tier 1)
    currentSubCategoryFilter: null, // null | 'all_sub' | subcategory name (Tier 2)
    currentMicroCategoryFilter: null, // null | 'all_micro' | microcategory name (Tier 3)
    subCategoryPage: 1, // page counter for 15 items per page
    subCategorySearchQuery: "", // in-subcategory search
    subCategoryLoadedItems: [], // cache of loaded subcategory items
    currentSingleStall: null,     // null or stallId
    currentDirectoryZone: "all",
    searchQuery: "",
    favorites: loadSavedFavorites(),     // Persistent favorite stalls list
    customer: loadSavedCustomer(),       // Logged in customer session
    activeMerchant: loadSavedMerchant(), // Logged in merchant session
    activeCoupon: { code: "FRESH20", discount: 20, desc: "ส่วนลด ฿20 สั่งของสดรอบถัดไป" }, // ✅ เริ่มต้นตรงกับ radio FRESH20 ในหน้า checkout
    deliveryLocation: loadSavedLocation(), // Active delivery location
    isSearchingGPS: false, // Flag when searching GPS to clear and prevent showing old distance
    cart: loadSavedCart(),               // ✅ โหลดตะกร้าจาก localStorage
    activeOrder: loadSavedActiveOrder(),  // ✅ โหลด active order จาก localStorage
    stallRotation: {
        intervalSeconds: 30,
        remainingSeconds: 30,
        isPaused: false,
        timer: null,
        displayedStallIds: []
    }
};
window.state = state;

// ✅ อัปเดตแถบติดตามออเดอร์สดบนหน้าหลัก (Home Screen) และปุ่มเมนูด้านล่าง
function updateHomeActiveOrderBanner() {
    const banner = document.getElementById("home-active-order-banner");
    const navBadge = document.getElementById("nav-tracking-badge");
    const order = state.activeOrder;
    const isCustomerLoggedIn = state.customer && state.customer.isLoggedIn;

    // ถ้าไม่มีออเดอร์ หรือออเดอร์ส่งเสร็จแล้ว หรือลูกค้าไม่ได้เข้าสู่ระบบ ให้ซ่อนแถบทันที
    if (!order || !order.orderId || order.status === "delivered" || !isCustomerLoggedIn) {
        if (banner) banner.classList.add("hidden");
        if (navBadge) navBadge.classList.add("hidden");
        return;
    }

    // แสดง Badge สีแดง LIVE ที่ปุ่ม "ติดตามส่ง" เมนูด้านล่าง
    if (navBadge) {
        navBadge.classList.remove("hidden");
        navBadge.textContent = "LIVE";
    }

    // แสดง Floating Banner บนหน้าตลาดสด
    if (banner) {
        banner.classList.remove("hidden");
        const idEl = document.getElementById("home-active-order-id");
        const statusEl = document.getElementById("home-active-order-status");

        if (idEl) idEl.textContent = order.orderId;

        const refund = order.refundCashTotal || 0;
        let statusText = "📋 กำลังจัดเตรียมของสดในตลาด";
        if (order.status === "delivering") statusText = "🛵 ไรเดอร์กำลังเดินทางนำส่ง";

        let refundTag = "";
        if (refund > 0) {
            refundTag = ` • <strong class="text-amber-300 font-black">✉️ มีซองเงินทอน ฿${refund}</strong>`;
        }

        if (statusEl) {
            statusEl.innerHTML = `${statusText}${refundTag}`;
        }
    }
}

// ✅ จัดการ Deep Link สำหรับการติดตามสถานะออเดอร์สด (เช่น ลิงก์ที่ส่งไปใน LINE)
async function handleTrackingDeepLink() {
    try {
        const urlParams = new URLSearchParams(window.location.search);
        let trackId = urlParams.get("track") || urlParams.get("order");
        if (!trackId && window.location.hash.startsWith("#track")) {
            const parts = window.location.hash.split("=");
            if (parts.length > 1) trackId = parts[1];
        }

        if (trackId) {
            trackId = decodeURIComponent(trackId).trim();
            const cleanKey = trackId.replace(/^#/, '');

            // 1. ถ้ามีใน state.activeOrder อยู่แล้ว
            if (state.activeOrder && state.activeOrder.orderId && 
                (state.activeOrder.orderId === trackId || state.activeOrder.orderId.replace(/^#/, '') === cleanKey)) {
                // ข้อมูลพร้อมแล้ว
            } else {
                // ค้นหาจาก Express Orders ของร้านค้าในเครื่อง
                try {
                    const expOrders = JSON.parse(localStorage.getItem("hsong_merchant_express_orders") || "[]");
                    const foundExp = expOrders.find(o => o.orderId === trackId || o.orderId.replace(/^#/, '') === cleanKey);
                    if (foundExp) {
                        state.activeOrder = foundExp;
                        try { localStorage.setItem("talathub_active_order", JSON.stringify(foundExp)); } catch(e) {}
                    }
                } catch(e) {}
            }
            
            if ((!state.activeOrder || state.activeOrder.orderId !== trackId) && isFirebaseReady()) {
                // 2. ดึงจาก Firebase Cloud
                try {
                    const snap = await db.ref(`orders/${toFirebaseKey(trackId)}`).once("value");
                    let orderData = snap.val();
                    if (!orderData) {
                        const snap2 = await db.ref(`orders/${toFirebaseKey("#" + cleanKey)}`).once("value");
                        orderData = snap2.val();
                    }
                    if (orderData && orderData.orderId) {
                        state.activeOrder = orderData;
                        try { localStorage.setItem("talathub_active_order", JSON.stringify(orderData)); } catch(e) {}
                    }
                } catch(e) {
                    console.warn("Firebase deep link load error:", e);
                }
            }

            // นำลูกค้าไปที่หน้า Tracking ทันที (รองรับ Guest เปิดดูจากลิงก์ LINE)
            if (!state.customer) {
                state.customer = { isLoggedIn: true, name: state.activeOrder?.customerName || "ลูกค้า", phone: state.activeOrder?.customerPhone || "" };
            } else {
                state.customer.isLoggedIn = true;
            }
            switchRole("customer");
            goToTrackingScreen();
            
            // เลื่อนหน้าจอไปที่แบนเนอร์เงินทอนหรือสถานะ
            setTimeout(() => {
                const refundBanner = document.getElementById("tracking-refund-banner");
                if (refundBanner && !refundBanner.classList.contains("hidden")) {
                    refundBanner.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            }, 300);

            showToast(`📦 เปิดหน้าติดตามออเดอร์ ${trackId} ให้เรียบร้อยแล้ว`);
            return;
        }
    } catch (e) {
        console.warn("handleTrackingDeepLink failed", e);
    }

    // ถ้าไม่มี trackId แต่มี active order ค้างอยู่ ให้อัปเดตแถบติดตามหน้าแรก
    updateHomeActiveOrderBanner();
}

// 3. Initialization
document.addEventListener("DOMContentLoaded", () => {
    updateDeliveryLocationUI();
    renderAuthHeaderButtons();
    renderFavoriteStallsBar();
    renderCatalog();
    updateCartUI();
    renderTrackingScreen();
    renderDirectoryList();
    updateHomeActiveOrderBanner();
    handleTrackingDeepLink();

    // ✅ Cross-tab sync (same browser): ฟัง storage event
    window.addEventListener("storage", (event) => {
        if (event.key === "talathub_cart" && event.newValue !== null) {
            try {
                const newCart = JSON.parse(event.newValue);
                if (Array.isArray(newCart)) {
                    state.cart = newCart;
                    updateCartUI();
                    renderCatalog();
                    if (state.currentScreen === "checkout") renderCheckoutPage();
                }
            } catch (e) { }
        }
        if (event.key === "talathub_logged_in_customer" && event.newValue !== null) {
            try {
                const newCust = JSON.parse(event.newValue);
                if (newCust) { state.customer = newCust; renderAuthHeaderButtons(); }
            } catch (e) { }
        }
    });

    // ✅ Firebase Real-time Listeners — sync ข้ามเครือข่ายและอุปกรณ์
    if (isFirebaseReady()) {

        // 1. ฟังออเดอร์ใหม่ทั้งหมด (Hub/PC จะเห็นทันทีที่มือถือสั่งซื้อ)
        db.ref("orders").on("child_added", (snapshot) => {
            const newOrder = snapshot.val();
            if (!newOrder || !newOrder.orderId) return;

            // รับเฉพาะออเดอร์ใหม่ (ภายใน 30 วินาที) เพื่อไม่ให้ trigger ตอน page load
            const isRecent = newOrder.savedAt && (Date.now() - newOrder.savedAt) < 30000;
            if (!isRecent) return;

            // อัปเดต state
            state.activeOrder = newOrder;
            try { localStorage.setItem("talathub_active_order", JSON.stringify(newOrder)); } catch(e) {}

            // อัปเดต UI (Hub badge + เสียง + picking list)
            const hubBadge = document.getElementById("hub-badge-count");
            if (hubBadge) { hubBadge.classList.remove("hidden"); hubBadge.textContent = "NEW"; }
            if (typeof renderHubPickingList === "function") renderHubPickingList();
            if (typeof renderHubDeliveryView === "function") renderHubDeliveryView();
            renderTrackingScreen();
            updateHomeActiveOrderBanner();
            playOrderAlertSound();
            showToast(`🔔 ออเดอร์ใหม่ ${newOrder.orderId} เข้ามา! ฿${newOrder.grandTotal || newOrder.total}`);
        });

        // 2. ฟัง order status update (มือถือลูกค้าจะเห็นสถานะ picking→delivering→delivered ทันที)
        db.ref("orders").on("child_changed", (snapshot) => {
            const updatedOrder = snapshot.val();
            if (!updatedOrder || !updatedOrder.orderId) return;

            // ถ้า order นี้คือ order ที่กำลัง active อยู่
            if (state.activeOrder && state.activeOrder.orderId === updatedOrder.orderId) {
                const oldStatus = state.activeOrder.status;
                const oldRefund = state.activeOrder.refundCashTotal || 0;
                state.activeOrder = { ...state.activeOrder, ...updatedOrder };
                try { localStorage.setItem("talathub_active_order", JSON.stringify(state.activeOrder)); } catch(e) {}

                // แสดงสถานะใหม่บน tracking screen และหน้าหลัก
                if (state.currentScreen === "tracking") renderTrackingScreen();
                updateHomeActiveOrderBanner();

                if ((updatedOrder.refundCashTotal || 0) > oldRefund) {
                    showToast(`✉️ แจ้งเตือน: มีการคืนเงินสดใส่ซอง ฿${updatedOrder.refundCashTotal}! แตะดูสถานะจัดส่งได้เลย`);
                } else if (updatedOrder.status === "delivering" && oldStatus !== "delivering") {
                    showToast("🛵 ไรเดอร์ออกเดินทางแล้ว! กำลังมาส่งของที่บ้านคุณ");
                } else if (updatedOrder.status === "delivered" && oldStatus !== "delivered") {
                    showToast("✅ จัดส่งสำเร็จแล้ว! ขอบคุณที่ใช้บริการเฮียส่ง 🙏");
                }
            }
        });

        console.log("🔥 Firebase real-time listeners active");
    } else {
        console.warn("⚠️ Firebase not ready, using localStorage only");
    }
});




function goToHomePage() {
    switchRole("customer");
    goToMarketScreen();
    filterByCategory("all");
    clearSearchInput();
    state.currentSingleStall = null;
    const singleBanner = document.getElementById("single-stall-banner");
    if (singleBanner) singleBanner.classList.add("hidden");
    renderFavoriteStallsBar();
    renderCatalog();
    window.scrollTo({ top: 0, behavior: 'smooth' });
    showToast("🏠 ยินดีต้อนรับสู่ เฮียส่ง (หน้าหลัก)");
}

function goToMarketScreen() {
    state.currentScreen = "market";
    document.getElementById("screen-market-home").classList.remove("hidden");
    document.getElementById("screen-checkout").classList.add("hidden");
    document.getElementById("screen-tracking").classList.add("hidden");
    if (typeof stopRiderJourneySimulation === "function") stopRiderJourneySimulation();
    updateHomeActiveOrderBanner();
}

function goToCheckoutScreen() {
    state.currentScreen = "checkout";
    document.getElementById("screen-market-home").classList.add("hidden");
    document.getElementById("screen-checkout").classList.remove("hidden");
    document.getElementById("screen-tracking").classList.add("hidden");
    if (typeof stopRiderJourneySimulation === "function") stopRiderJourneySimulation();
    renderCheckoutPage();
}

function goToTrackingScreen() {
    state.currentScreen = "tracking";
    document.getElementById("screen-market-home").classList.add("hidden");
    document.getElementById("screen-checkout").classList.add("hidden");
    document.getElementById("screen-tracking").classList.remove("hidden");
    renderTrackingScreen();
    setTimeout(() => {
        if (customerLiveTrackingMap) {
            customerLiveTrackingMap.invalidateSize();
            if (typeof recenterCustomerLiveMap === "function") recenterCustomerLiveMap();
        }
    }, 150);
}

function switchHubTab(tabName) {
    const tabs = ["picking", "settlement", "monitor"];
    tabs.forEach(t => {
        const btn = document.getElementById(`hub-tab-${t}`);
        const content = document.getElementById(`hub-content-${t}`);
        const isActive = t === tabName;
        if (btn) {
            btn.className = isActive
                ? "font-bold text-emerald-700 border-b-2 border-emerald-600 pb-1 whitespace-nowrap px-1 flex items-center gap-1"
                : "font-medium text-slate-500 pb-1 hover:text-slate-800 whitespace-nowrap px-1 flex items-center gap-1";
        }
        if (content) {
            if (isActive) content.classList.remove("hidden");
            else content.classList.add("hidden");
        }
    });

    if (tabName === "picking") {
        renderHubPickingList();
    }

    if (tabName === "settlement") {
        renderHubSettlement();
    }

    if (tabName === "monitor") {
        renderHubMonitorBoard();
        startMonitorAutoRefresh();
    } else {
        stopMonitorAutoRefresh();
    }
}

// ==========================================
// HUB ORDER STATUS MONITOR BOARD
// ==========================================

// Status config: สี / ไอคอน / label / ลำดับความสำคัญ
const ORDER_STATUS_CONFIG = {
    picking:    { label: "รอจัดของ",      icon: "📋", color: "bg-amber-100 text-amber-800 border-amber-300",   dot: "bg-amber-400",   priority: 1 },
    delivering: { label: "กำลัง dispatch", icon: "📦", color: "bg-blue-100 text-blue-800 border-blue-300",     dot: "bg-blue-500",    priority: 2 },
    dispatched: { label: "รอไรเดอร์รับ",   icon: "⚠️", color: "bg-rose-100 text-rose-800 border-rose-300",    dot: "bg-rose-500",    priority: 3 },
    on_the_way: { label: "กำลังนำส่ง",    icon: "🛵", color: "bg-sky-100 text-sky-800 border-sky-300",        dot: "bg-sky-500",     priority: 4 },
    delivered:  { label: "ส่งสำเร็จ",     icon: "✅", color: "bg-emerald-100 text-emerald-800 border-emerald-300", dot: "bg-emerald-500", priority: 5 },
};

const DISPATCH_TIMEOUT_MS = 5 * 60 * 1000; // ⚠️ alert ถ้า dispatched นานเกิน 5 นาที
let _monitorRefreshTimer = null;
let _monitorLastRefresh = null;

function renderHubMonitorBoard() {
    const container = document.getElementById("hub-content-monitor");
    if (!container) return;

    // รวบรวม orders จากทุกแหล่ง (localStorage + state)
    const allOrders = _collectAllOrders();
    const now = Date.now();

    // ── KPI Summary ───────────────────────────────────────────────────────────
    const counts = { picking: 0, delivering: 0, dispatched: 0, on_the_way: 0, delivered: 0 };
    allOrders.forEach(o => {
        const s = o.status || "picking";
        if (counts[s] !== undefined) counts[s]++;
    });

    const stuckOrders = allOrders.filter(o =>
        o.status === "dispatched" &&
        o.dispatchedAt &&
        (now - o.dispatchedAt) > DISPATCH_TIMEOUT_MS
    );

    // อัปเดต alert badge บนแท็บ
    updateMonitorAlertBadge(stuckOrders.length);

    // ── Render HTML ───────────────────────────────────────────────────────────
    const lastRefreshStr = _monitorLastRefresh
        ? new Date(_monitorLastRefresh).toLocaleTimeString("th-TH", { hour: "2-digit", minute: "2-digit" })
        : "--:--";

    let html = `
    <div class="p-3 space-y-3 text-xs">

        <!-- Header -->
        <div class="flex items-center justify-between">
            <div>
                <h3 class="font-extrabold text-slate-800 text-sm">📊 ติดตามออเดอร์วันนี้</h3>
                <p class="text-slate-400 text-[10px]">อัปเดตล่าสุด: ${lastRefreshStr} น.</p>
            </div>
            <button onclick="renderHubMonitorBoard()" class="flex items-center gap-1 bg-emerald-600 hover:bg-emerald-700 text-white font-bold px-2.5 py-1.5 rounded-xl active:scale-95 transition-all shadow-sm">
                <span class="material-symbols-outlined text-sm">refresh</span>
                <span>Refresh</span>
            </button>
        </div>

        <!-- KPI Bar -->
        <div class="grid grid-cols-5 gap-1.5">
            ${_renderKpiCard("รอจัดของ", counts.picking, "bg-amber-50 border-amber-200 text-amber-700", "📋")}
            ${_renderKpiCard("กำลังส่ง", counts.delivering, "bg-blue-50 border-blue-200 text-blue-700", "📦")}
            ${_renderKpiCard("รอไรเดอร์", counts.dispatched, counts.dispatched > 0 ? "bg-rose-50 border-rose-300 text-rose-700 animate-pulse" : "bg-slate-50 border-slate-200 text-slate-500", "⚠️")}
            ${_renderKpiCard("นำส่ง", counts.on_the_way, "bg-sky-50 border-sky-200 text-sky-700", "🛵")}
            ${_renderKpiCard("สำเร็จ", counts.delivered, "bg-emerald-50 border-emerald-200 text-emerald-700", "✅")}
        </div>`;

    // ── Stuck Orders Warning ──────────────────────────────────────────────────
    if (stuckOrders.length > 0) {
        html += `
        <div class="bg-rose-50 border border-rose-300 rounded-2xl p-3 space-y-2">
            <div class="flex items-center gap-2 text-rose-800 font-extrabold">
                <span class="text-base animate-bounce">🚨</span>
                <span>ไรเดอร์ยังไม่รับงาน! (${stuckOrders.length} ออเดอร์)</span>
            </div>
            ${stuckOrders.map(o => _renderStuckOrderCard(o, now)).join("")}
        </div>`;
    }

    // ── Active Orders ─────────────────────────────────────────────────────────
    const activeOrders = allOrders.filter(o => o.status !== "delivered").sort((a, b) => {
        const pa = ORDER_STATUS_CONFIG[a.status]?.priority || 9;
        const pb = ORDER_STATUS_CONFIG[b.status]?.priority || 9;
        return pa - pb;
    });

    if (activeOrders.length > 0) {
        html += `<div class="space-y-2">
            <p class="font-bold text-slate-700 text-[11px] uppercase tracking-wider">🔄 ออเดอร์ที่กำลังดำเนินการ</p>
            ${activeOrders.map(o => _renderOrderCard(o, now)).join("")}
        </div>`;
    } else {
        html += `
        <div class="flex flex-col items-center justify-center py-10 text-slate-400 gap-2">
            <span class="text-4xl">🎉</span>
            <p class="font-bold text-slate-600">ไม่มีออเดอร์ค้างอยู่!</p>
            <p class="text-[11px]">ทุกออเดอร์ส่งสำเร็จแล้ว</p>
        </div>`;
    }

    // ── Completed Orders Today ────────────────────────────────────────────────
    const completedOrders = allOrders.filter(o => o.status === "delivered");
    if (completedOrders.length > 0) {
        html += `
        <div class="space-y-1.5">
            <p class="font-bold text-slate-500 text-[11px] uppercase tracking-wider">✅ ส่งสำเร็จวันนี้ (${completedOrders.length} ออเดอร์)</p>
            ${completedOrders.map(o => `
            <div class="bg-white border border-slate-100 rounded-xl p-2.5 flex items-center justify-between opacity-70">
                <div class="flex items-center gap-2">
                    <span class="text-emerald-500 font-black text-sm">✅</span>
                    <div>
                        <span class="font-bold text-slate-700">${escapeHtml(o.orderId)}</span>
                        <span class="text-slate-400 ml-1">${escapeHtml(o.customerName) || escapeHtml(o.customerPhone) || "ลูกค้า"}</span>
                    </div>
                </div>
                <span class="text-emerald-600 font-black">฿${o.grandTotal || o.total || 0}</span>
            </div>`).join("")}
        </div>`;
    }

    html += `</div>`; // end p-3
    container.innerHTML = html;
    _monitorLastRefresh = now;
}

// ── Helper: รวบรวม orders จากทุกแหล่ง ────────────────────────────────────────
function _collectAllOrders() {
    const orders = [];
    const seen = new Set();

    // 1. state.activeOrder
    if (state.activeOrder && state.activeOrder.orderId && !isMockOrder(state.activeOrder)) {
        orders.push(state.activeOrder);
        seen.add(state.activeOrder.orderId);
    }

    // 2. localStorage: talathub_order_history
    try {
        const hist = JSON.parse(localStorage.getItem("talathub_order_history") || "[]");
        hist.forEach(o => {
            if (o && o.orderId && !seen.has(o.orderId) && !isMockOrder(o)) {
                orders.push(o);
                seen.add(o.orderId);
            }
        });
    } catch (e) {}

    // 3. localStorage: talathub_active_order (backup)
    try {
        const saved = JSON.parse(localStorage.getItem("talathub_active_order") || "null");
        if (saved && saved.orderId && !seen.has(saved.orderId) && !isMockOrder(saved)) {
            orders.push(saved);
            seen.add(saved.orderId);
        }
    } catch (e) {}

    // 4. Memory cache from Firebase Realtime DB
    if (window._cachedFirebaseOrders && Array.isArray(window._cachedFirebaseOrders)) {
        window._cachedFirebaseOrders.forEach(o => {
            if (o && o.orderId && !seen.has(o.orderId) && !isMockOrder(o)) {
                orders.push(o);
                seen.add(o.orderId);
            }
        });
    }

    // 5. Merchant Express Orders (งานด่วนจากแผงค้า)
    if (state.merchantExpressOrders && Array.isArray(state.merchantExpressOrders)) {
        state.merchantExpressOrders.forEach(o => {
            if (o && o.orderId && !seen.has(o.orderId) && !isMockOrder(o)) {
                orders.push(o);
                seen.add(o.orderId);
            }
        });
    }
    try {
        const expHist = JSON.parse(localStorage.getItem("hsong_merchant_express_orders") || "[]");
        expHist.forEach(o => {
            if (o && o.orderId && !seen.has(o.orderId) && !isMockOrder(o)) {
                orders.push(o);
                seen.add(o.orderId);
            }
        });
    } catch(e) {}

    return orders;
}

// ── Helper: KPI Card ──────────────────────────────────────────────────────────
function _renderKpiCard(label, count, colorClass, icon) {
    return `
    <div class="border rounded-xl p-2 text-center ${colorClass}">
        <div class="text-base leading-none">${icon}</div>
        <div class="font-black text-lg leading-tight">${count}</div>
        <div class="text-[9px] font-bold leading-tight mt-0.5">${label}</div>
    </div>`;
}

// ── Helper: Order Card ────────────────────────────────────────────────────────
function _renderOrderCard(order, now) {
    const cfg = ORDER_STATUS_CONFIG[order.status] || ORDER_STATUS_CONFIG.picking;
    const isDispatched = order.status === "dispatched";
    const dispatchedMs = isDispatched && order.dispatchedAt ? now - order.dispatchedAt : 0;
    const isStuck = isDispatched && dispatchedMs > DISPATCH_TIMEOUT_MS;
    const minutesAgo = Math.floor(dispatchedMs / 60000);

    const cardBorder = isStuck ? "border-rose-300 bg-rose-50" : "border-slate-200 bg-white";

    return `
    <div class="border rounded-2xl p-3 space-y-2 shadow-xs ${cardBorder}">
        <div class="flex items-center justify-between">
            <div class="flex items-center gap-2">
                <span class="w-2 h-2 rounded-full ${cfg.dot} shrink-0"></span>
                <span class="font-extrabold text-slate-800">${escapeHtml(order.orderId)}</span>
                <span class="text-slate-500">${escapeHtml(order.customerName) || escapeHtml(order.customerPhone) || "ลูกค้า"}</span>
            </div>
            <span class="border px-2 py-0.5 rounded-full text-[10px] font-bold ${cfg.color}">${cfg.icon} ${escapeHtml(cfg.label)}</span>
        </div>

        <div class="flex items-center justify-between text-slate-500">
            <span>฿${order.grandTotal || order.total || 0} • ${escapeHtml(order.address) || "ที่อยู่ยังไม่ระบุ"}</span>
            ${order.riderName ? `<span class="text-sky-600 font-bold">🛵 ${escapeHtml(order.riderName)}</span>` : ""}
        </div>

        ${isDispatched ? `
        <div class="flex items-center justify-between bg-rose-50 border border-rose-200 rounded-xl px-3 py-2">
            <span class="${isStuck ? "text-rose-700 font-extrabold animate-pulse" : "text-amber-600 font-bold"}">
                ${isStuck ? `🚨 ไม่มีไรเดอร์รับงาน! (${minutesAgo} นาทีแล้ว)` : `⏳ รอไรเดอร์รับงาน (${minutesAgo} นาที)`}
            </span>
            <div class="flex gap-1.5">
                <button onclick="callRiderPhone(event, ${jsArg(order.riderPhone || '')})"
                    class="bg-sky-600 hover:bg-sky-700 text-white font-bold px-2 py-1 rounded-lg active:scale-95 transition-all flex items-center gap-1">
                    <span class="material-symbols-outlined text-xs">call</span>
                    <span>โทร</span>
                </button>
                <button onclick="reassignRiderForOrder(${jsArg(order.orderId)})"
                    class="bg-amber-500 hover:bg-amber-600 text-white font-bold px-2 py-1 rounded-lg active:scale-95 transition-all flex items-center gap-1">
                    <span class="material-symbols-outlined text-xs">swap_horiz</span>
                    <span>Assign</span>
                </button>
            </div>
        </div>` : ""}

        ${order.status === "on_the_way" ? `
        <div class="flex items-center gap-1.5 text-sky-600 font-bold bg-sky-50 border border-sky-200 rounded-xl px-3 py-2">
            <span class="material-symbols-outlined text-sm animate-bounce">near_me</span>
            <span>ไรเดอร์กำลังเดินทางไปส่ง</span>
            ${order.riderPhone ? `<button onclick="callRiderPhone(event, ${jsArg(order.riderPhone)})" class="ml-auto bg-sky-600 text-white font-bold px-2 py-1 rounded-lg active:scale-95 transition-all text-[10px]">📞 โทรสอบถาม</button>` : ""}
        </div>` : ""}
    </div>`;
}

// ── Helper: Stuck Order Card (ใน warning box) ─────────────────────────────────
function _renderStuckOrderCard(order, now) {
    const minutesAgo = Math.floor((now - order.dispatchedAt) / 60000);
    return `
    <div class="flex items-center justify-between bg-white border border-rose-200 rounded-xl px-3 py-2">
        <div>
            <span class="font-extrabold text-rose-800">${escapeHtml(order.orderId)}</span>
            <span class="text-rose-600 ml-1">(${minutesAgo} นาทีที่แล้ว)</span>
        </div>
        <div class="flex gap-1.5">
            <button onclick="callRiderPhone(event, ${jsArg(order.riderPhone || '')})"
                class="bg-sky-600 text-white font-bold px-2 py-1 rounded-lg text-[10px] active:scale-95 transition-all">
                📞 โทร
            </button>
            <button onclick="reassignRiderForOrder(${jsArg(order.orderId)})"
                class="bg-amber-500 text-white font-bold px-2 py-1 rounded-lg text-[10px] active:scale-95 transition-all">
                🔁 Assign
            </button>
        </div>
    </div>`;
}

// ── Alert Badge บน Tab ────────────────────────────────────────────────────────
function updateMonitorAlertBadge(stuckCount) {
    const badge = document.getElementById("hub-monitor-alert-badge");
    if (!badge) return;
    if (stuckCount > 0) {
        badge.textContent = stuckCount;
        badge.classList.remove("hidden");
    } else {
        badge.classList.add("hidden");
    }
}

// ── Auto Refresh ──────────────────────────────────────────────────────────────
function startMonitorAutoRefresh() {
    stopMonitorAutoRefresh();
    _monitorRefreshTimer = setInterval(() => {
        if (!document.getElementById("hub-content-monitor")?.classList.contains("hidden")) {
            renderHubMonitorBoard();
        }
    }, 30000); // refresh ทุก 30 วินาที
}

function stopMonitorAutoRefresh() {
    if (_monitorRefreshTimer) {
        clearInterval(_monitorRefreshTimer);
        _monitorRefreshTimer = null;
    }
}

// ── Reassign Rider ────────────────────────────────────────────────────────────
function reassignRiderForOrder(orderId) {
    if (!state.activeOrder || state.activeOrder.orderId !== orderId) {
        showToast("⚠️ ไม่พบออเดอร์นี้ในระบบปัจจุบัน");
        return;
    }
    // Reset status กลับไป delivering เพื่อให้ฮับ assign ไรเดอร์ใหม่ได้
    state.activeOrder.status = "delivering";
    state.activeOrder.riderName = null;
    state.activeOrder.riderPhone = null;
    state.activeOrder.dispatchedAt = null;
    saveActiveOrderToStorage(state.activeOrder);
    renderHubMonitorBoard();
    showToast(`🔁 รีเซ็ตออเดอร์ ${orderId} — พร้อม assign ไรเดอร์ใหม่`);
}

// ==========================================
// WISIT CHAI HUB: DAILY OPERATIONS & SETTLEMENTS DATABASE REPORT
// ระบบฐานข้อมูลรายงานสรุปยอดขาย เคลียร์เงินไรเดอร์ และเคลียร์แผงค้าประจำวัน
// ==========================================

let _activeReportDateKey = null;
let _currentPayoutStall = null;

// ── Helper: ดึง YYYY-MM-DD จาก timestamp (ใช้วันที่ตามเวลาท้องถิ่น)
function getReportDateKey(timestamp) {
    if (!timestamp) timestamp = Date.now();
    const d = new Date(timestamp);
    if (isNaN(d.getTime())) {
        const now = new Date();
        return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
    }
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, "0");
    const day = String(d.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
}

// ── Helper: แปลง Date Key (YYYY-MM-DD) เป็นรูปแบบภาษาไทย
function formatThaiDateDisplay(dateKey) {
    if (!dateKey) return "";
    const parts = dateKey.split("-");
    if (parts.length !== 3) return dateKey;
    const year = parseInt(parts[0], 10);
    const monthIdx = parseInt(parts[1], 10) - 1;
    const day = parseInt(parts[2], 10);
    const thaiMonths = ["ม.ค.", "ก.พ.", "มี.ค.", "เม.ย.", "พ.ค.", "มิ.ย.", "ก.ค.", "ส.ค.", "ก.ย.", "ต.ค.", "พ.ย.", "ธ.ค."];
    const thaiYear = year > 2500 ? year : year + 543;
    return `${day} ${thaiMonths[monthIdx] || ""} ${thaiYear}`;
}

// ── Helper: ค้นหาข้อมูลร้านค้า / แผงค้า
function findStallInfo(stallId, stallName) {
    let stall = ALL_100_STALLS.find(s => s.stallId === stallId || s.stallName === stallName);
    if (!stall) {
        stall = MARKET_DATA.find(s => s.stallId === stallId || s.stallName === stallName);
    }
    if (!stall && stallName) {
        stall = ALL_100_STALLS.find(s => s.stallName && s.stallName.includes(stallName));
    }
    return stall || {
        stallId: stallId || "stall_general",
        stallName: stallName || "แผงค้าทั่วไป",
        stallNumber: stallName && stallName.includes("(") ? stallName.split("(")[1].replace(")", "") : "แผงทั่วไป",
        zone: "ตลาดสด",
        ownerName: "แม่ค้าประจำแผง",
        phone: "089-123-4567"
    };
}

// ── Persistence Helpers for Rider & Vendor Settlements
function _loadRiderSettlementState(dateKey) {
    try {
        return JSON.parse(localStorage.getItem(`talathub_settled_riders_${dateKey}`) || "{}");
    } catch (e) {
        return {};
    }
}

function _saveRiderSettlementState(dateKey, stateObj) {
    try {
        localStorage.setItem(`talathub_settled_riders_${dateKey}`, JSON.stringify(stateObj));
        if (isFirebaseReady()) {
            db.ref(`daily_reports/${dateKey}/riderSettlement/settledRiders`).set(stateObj).catch(() => {});
        }
    } catch (e) {}
}

function _loadVendorSettlementState(dateKey) {
    try {
        return JSON.parse(localStorage.getItem(`talathub_settled_vendors_${dateKey}`) || "{}");
    } catch (e) {
        return {};
    }
}

function _saveVendorSettlementState(dateKey, stateObj) {
    try {
        localStorage.setItem(`talathub_settled_vendors_${dateKey}`, JSON.stringify(stateObj));
        if (isFirebaseReady()) {
            db.ref(`daily_reports/${dateKey}/vendorSettlement/settledVendors`).set(stateObj).catch(() => {});
        }
    } catch (e) {}
}

// ── Aggregation Engine: รวบรวมข้อมูลออเดอร์ ไรเดอร์ และร้านค้า ประจำวัน
// ออเดอร์ที่ยกเลิกไม่มีเงินเข้า-ออก จึงต้องไม่ถูกนับเป็นยอดขาย ค่าส่ง หรือยอดโอนแผงค้า
function isCancelledOrder(o) {
    const s = String((o && o.status) || "").toLowerCase();
    return s === "cancelled" || s === "canceled";
}
window.isCancelledOrder = isCancelledOrder;

function aggregateDailyOperations(targetDateKey) {
    if (!targetDateKey) targetDateKey = getReportDateKey(Date.now());

    // 1. ดึงออเดอร์ทั้งหมด (แยกออเดอร์ที่ยกเลิกออกจากยอดเงิน)
    const allOrders = _collectAllOrders();
    const allDateOrders = allOrders.filter(o => {
        const orderDate = getReportDateKey(o.savedAt || o.createdAt || o.orderTime || Date.now());
        return orderDate === targetDateKey;
    });
    const dateOrders = allDateOrders.filter(o => !isCancelledOrder(o));

    // 2. โหลดสถานะการเคลียร์เงินที่เคยบันทึกไว้
    const settledRiders = _loadRiderSettlementState(targetDateKey);
    const settledVendors = _loadVendorSettlementState(targetDateKey);

    // 3. ยอดรวมลูกค้า & สรุปสถานะออเดอร์
    const summary = {
        dateKey: targetDateKey,
        totalOrders: dateOrders.length,
        cancelledOrders: allDateOrders.length - dateOrders.length,
        completedOrders: 0,
        pendingOrders: 0,
        totalCustomerGMV: 0,
        totalDeliveryFees: 0,
        totalDiscounts: 0,
        totalExpressFees: 0,
        netCustomerPaid: 0,
        totalRefundCash: 0,
        paymentBreakdown: {
            promptpay: { count: 0, amount: 0, label: "พร้อมเพย์" },
            bank_transfer: { count: 0, amount: 0, label: "โอนผ่าน SCB" },
            cod: { count: 0, amount: 0, label: "เงินสดปลายทาง (COD)" }
        }
    };

    const ridersMap = {};
    const stallsMap = {};

    dateOrders.forEach(o => {
        const isDelivered = o.status === "delivered";
        if (isDelivered) summary.completedOrders++;
        else summary.pendingOrders++;

        const isExpOrder = o.orderType === "MERCHANT_EXPRESS" || (o.orderId && o.orderId.startsWith("EXP-"));
        const orderTotal = Number(o.grandTotal || o.total || o.netTotal || o.deliveryFee || 0);
        const delFee = Number(o.deliveryFee || (isExpOrder ? orderTotal : 20));
        const discount = Number(o.discount || 0);
        const refundAmt = Number(o.refundCashTotal || o.cashRefund || 0);
        const expFee = Number(o.expressFee || (isExpOrder ? delFee : ((o.isExpress || o.orderType === "CUSTOMER_EXPRESS") ? 20 : 0)));

        summary.totalCustomerGMV += orderTotal;
        // ค่าส่งของงานด่วนจากแผงบันทึกครั้งเดียวในช่อง Express (ไม่ซ้ำกับค่าส่ง เพื่อไม่ให้รายได้ฮับถูกนับสองเท่า)
        summary.totalDeliveryFees += isExpOrder ? 0 : delFee;
        summary.totalExpressFees += expFee;
        summary.totalDiscounts += discount;
        summary.totalRefundCash += refundAmt;

        // ช่องทางชำระเงิน
        const pType = (o.paymentType || "promptpay").toLowerCase();
        if (pType === "cod" || pType === "cash") {
            summary.paymentBreakdown.cod.count++;
            summary.paymentBreakdown.cod.amount += orderTotal;
        } else if (pType === "bank_transfer" || pType === "bank" || pType === "scb") {
            summary.paymentBreakdown.bank_transfer.count++;
            summary.paymentBreakdown.bank_transfer.amount += orderTotal;
        } else {
            summary.paymentBreakdown.promptpay.count++;
            summary.paymentBreakdown.promptpay.amount += orderTotal;
        }

        // จัดกลุ่มไรเดอร์
        const rName = o.riderName || (o.assignedRider && o.assignedRider.name) || (o.status === "delivered" || o.status === "dispatched" || o.status === "on_the_way" ? "ไรเดอร์ประจำชุมชน" : "รอไรเดอร์รับงาน");
        const rPhone = o.riderPhone || (o.assignedRider && o.assignedRider.phone) || "-";
        if (!ridersMap[rName]) {
            const rRec = settledRiders[rName] || (o.assignedRider && settledRiders[o.assignedRider.id]) || {};
            const isRiderSettled = Boolean(rRec.isSettled);
            ridersMap[rName] = {
                riderName: rName,
                riderPhone: rPhone,
                tripsCount: 0,
                riderFeeEarned: 0,
                codCollected: 0,
                refundHanded: 0,
                netCashToHub: 0,
                isSettled: isRiderSettled,
                settledAt: rRec.settledAt || null,
                settledBy: rRec.settledBy || null,
                slipImage: rRec.slipImage || null,
                slipNote: rRec.slipNote || ""
            };
        }
        if (o.status === "delivered" || o.status === "on_the_way" || o.status === "dispatched" || o.status === "assigned") {
            ridersMap[rName].tripsCount++;
            ridersMap[rName].riderFeeEarned += 40; // ค่ารอบ ฿40
            if (pType === "cod" || pType === "cash") {
                ridersMap[rName].codCollected += orderTotal;
            }
            ridersMap[rName].refundHanded += refundAmt;
        }

        // จัดกลุ่มแผงค้า (Vendor) — เฉพาะออเดอร์ของสดทั่วไป (งานด่วนร้านค้าไม่ใช่งานขายสินค้าของฮับ)
        if (!isExpOrder && o.stalls && Array.isArray(o.stalls)) {
            o.stalls.forEach(st => {
                const sKey = st.stallId || st.name;
                const meta = findStallInfo(st.stallId, st.name);
                if (!stallsMap[sKey]) {
                    const sRec = settledVendors[sKey] || (meta && settledVendors[meta.stallId]) || (meta && settledVendors[meta.stallName]) || {};
                    const isStallSettled = Boolean(sRec.isSettled);
                    stallsMap[sKey] = {
                        stallId: st.stallId || (meta && meta.stallId),
                        stallName: (meta && meta.stallName) || st.name,
                        stallNumber: (meta && meta.stallNumber) || "แผงตลาด",
                        zone: (meta && meta.zone) || "กลาง",
                        ownerName: (meta && meta.ownerName) || "เจ้าของแผง",
                        phone: (meta && meta.phone) || "089-123-4567",
                        promptPayPhone: ((meta && meta.phone) || "0891234567").replace(/[^0-9]/g, ""),
                        orderCount: 0,
                        itemsCount: 0,
                        totalAmount: 0,
                        isSettled: isStallSettled,
                        settledAt: sRec.settledAt || null,
                        settledBy: sRec.settledBy || null,
                        slipImage: sRec.slipImage || null,
                        slipNote: sRec.slipNote || ""
                    };
                }
                stallsMap[sKey].orderCount++;

                const activeItems = (st.items || []).filter(it => !it.outOfStock);
                activeItems.forEach(it => {
                    const itemQty = Number(it.qty || it.quantity || 1);
                    let itemTotal = 0;
                    if (it.subtotal !== undefined) {
                        itemTotal = Number(it.subtotal);
                    } else if (it.actualPrice !== undefined) {
                        itemTotal = Number(it.actualPrice) * itemQty;
                    } else if (it.unitPrice !== undefined) {
                        itemTotal = Number(it.unitPrice) * itemQty;
                    } else {
                        itemTotal = Number(it.price || 0) * itemQty;
                    }
                    stallsMap[sKey].totalAmount += itemTotal;
                    stallsMap[sKey].itemsCount += itemQty;
                });
            });
        }
    });

    summary.netCustomerPaid = summary.totalCustomerGMV;

    // คำนวณยอดเงินสุทธิที่ไรเดอร์ต้องส่งมอบฮับ
    const ridersList = Object.values(ridersMap);
    let totalTrips = 0;
    let totalRiderFees = 0;
    let totalCodCollected = 0;
    let totalRefundHanded = 0;
    let netCashToHub = 0;

    ridersList.forEach(r => {
        r.netCashToHub = r.codCollected - r.riderFeeEarned - r.refundHanded;
        totalTrips += r.tripsCount;
        totalRiderFees += r.riderFeeEarned;
        totalCodCollected += r.codCollected;
        totalRefundHanded += r.refundHanded;
        netCashToHub += r.netCashToHub;
    });

    const riderSettlement = {
        totalTrips,
        totalRiderFees,
        totalCodCollected,
        totalRefundHanded,
        netCashToHub,
        riders: ridersList,
        settledRiders
    };

    // โหลดการตั้งค่าระบบเพื่อหาอัตรา GP (มาตรฐานแพลตฟอร์ม 10%)
    const hubSettings = (typeof loadSavedHubSettings === "function") ? loadSavedHubSettings() : {};
    const gpRate = (hubSettings && typeof hubSettings.merchantGP === "number" && hubSettings.merchantGP > 0) ? hubSettings.merchantGP : 10;

    // คำนวณยอดรวมแผงค้า (แยกยอดขายรวม, GP ที่ระบบหัก 10%, และยอดโอนสุทธิ)
    const stallsList = Object.values(stallsMap);
    let totalVendorGross = 0;
    let totalVendorGP = 0;
    let totalVendorAmount = 0;
    let totalSettledAmount = 0;
    let settledCount = 0;
    let pendingCount = 0;

    stallsList.forEach(s => {
        s.gpRate = gpRate;
        s.gpAmount = Math.round(s.totalAmount * (gpRate / 100));
        s.payoutAmount = Math.max(0, s.totalAmount - s.gpAmount);

        totalVendorGross += s.totalAmount;
        totalVendorGP += s.gpAmount;
        totalVendorAmount += s.payoutAmount;

        if (s.isSettled) {
            totalSettledAmount += s.payoutAmount;
            settledCount++;
        } else {
            pendingCount++;
        }
    });

    const vendorSettlement = {
        totalVendorGross,
        totalVendorGP,
        totalVendorAmount, // ยอดโอนสุทธิให้แผงค้า
        totalSettledAmount,
        totalPendingAmount: totalVendorAmount - totalSettledAmount,
        settledCount,
        pendingCount,
        gpRate,
        stalls: stallsList,
        settledVendors
    };

    const report = {
        dateKey: targetDateKey,
        generatedAt: Date.now(),
        summary,
        riderSettlement,
        vendorSettlement,
        ordersList: dateOrders
    };

    // จัดเก็บใน LocalStorage
    try {
        localStorage.setItem(`talathub_daily_report_${targetDateKey}`, JSON.stringify(report));
    } catch (e) {}

    // จัดเก็บใน Firebase Realtime Database
    if (isFirebaseReady()) {
        db.ref(`daily_reports/${targetDateKey}`).set({
            dateKey: report.dateKey,
            generatedAt: report.generatedAt,
            summary: report.summary,
            riderSettlement: {
                totalTrips: report.riderSettlement.totalTrips,
                totalRiderFees: report.riderSettlement.totalRiderFees,
                totalCodCollected: report.riderSettlement.totalCodCollected,
                totalRefundHanded: report.riderSettlement.totalRefundHanded,
                netCashToHub: report.riderSettlement.netCashToHub,
                riders: report.riderSettlement.riders
            },
            vendorSettlement: {
                totalVendorAmount: report.vendorSettlement.totalVendorAmount,
                totalSettledAmount: report.vendorSettlement.totalSettledAmount,
                totalPendingAmount: report.vendorSettlement.totalPendingAmount,
                settledCount: report.vendorSettlement.settledCount,
                pendingCount: report.vendorSettlement.pendingCount,
                stalls: report.vendorSettlement.stalls
            },
            ordersCount: dateOrders.length
        }).catch(e => console.warn("Firebase daily report write failed:", e));
    }

    return report;
}

// ── เปลี่ยนวันที่รายงาน
function changeReportDate(newDate) {
    if (!newDate) return;
    _activeReportDateKey = newDate;
    renderHubDailyReport(newDate);
}

function setReportDateQuick(offsetDays) {
    const d = new Date();
    d.setDate(d.getDate() + offsetDays);
    const dateKey = getReportDateKey(d.getTime());
    changeReportDate(dateKey);
}

function navigateReportDay(direction) {
    const curDate = _activeReportDateKey || getReportDateKey(Date.now());
    const parts = curDate.split("-");
    if (parts.length !== 3) return;
    const d = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
    d.setDate(d.getDate() + direction);
    changeReportDate(getReportDateKey(d.getTime()));
}

// ── UI Renderer สำหรับแท็บรายงานประจำวัน (Widescreen PC View in Admin)
function renderHubDailyReport(targetDateKey) {
    const container = document.getElementById("admin-content-report");
    if (!container) return;

    if (!targetDateKey) {
        targetDateKey = _activeReportDateKey || getReportDateKey(Date.now());
    }
    _activeReportDateKey = targetDateKey;

    const report = aggregateDailyOperations(targetDateKey);
    const thaiDateText = formatThaiDateDisplay(targetDateKey);
    const isToday = targetDateKey === getReportDateKey(Date.now());

    // คำนวณรายได้ค่าบริการสุทธิของฮับ:
    // รายได้ฮับ = ค่าจัดส่งจากลูกค้า + ค่าธรรมเนียม GP จากแผงค้า + ค่าบริการส่งด่วน
    // กำไรสุทธิฮับ = รายได้ฮับ - ค่ารอบไรเดอร์
    const totalExpressFees = Number(report.summary.totalExpressFees || 0);
    const totalVendorGP = Number(report.vendorSettlement.totalVendorGP || 0);
    const totalDeliveryFees = Number(report.summary.totalDeliveryFees || 0);
    const hubGrossRevenue = totalDeliveryFees + totalVendorGP + totalExpressFees;
    const hubNetMargin = hubGrossRevenue - report.riderSettlement.totalRiderFees;

    // โครงสร้างต้นทุนคงที่ (Fixed Costs) & จุดคุ้มทุน (Break-even):
    const fc = (typeof loadPlatformFixedCosts === "function") ? loadPlatformFixedCosts() : {
        officeRent: 4000,
        staffSalary: 13000,
        utilitiesSupplies: 2000,
        daysInMonth: 30,
        breakEvenDailyOrders: 38,
        targetProfitDailyOrders: 45
    };
    const totalMonthlyFixedCost = fc.officeRent + fc.staffSalary + fc.utilitiesSupplies;
    const dailyFixedCost = Math.round(totalMonthlyFixedCost / (fc.daysInMonth || 30));
    const netDailyProfit = hubNetMargin - dailyFixedCost;

    const completedOrders = report.summary.completedOrders || 0;
    const progressPercent = Math.min(100, Math.round((completedOrders / (fc.breakEvenDailyOrders || 38)) * 100));

    let breakEvenStatusClass = "text-rose-400";
    let breakEvenBadgeText = `🔴 ยังไม่ถึงจุดคุ้มทุน (ขาดอีก ${Math.max(0, fc.breakEvenDailyOrders - completedOrders)} ออเดอร์)`;
    let progressColorClass = "bg-gradient-to-r from-rose-500 to-amber-500";

    if (completedOrders >= fc.targetProfitDailyOrders) {
        breakEvenStatusClass = "text-emerald-300 font-black";
        breakEvenBadgeText = `🏆 บรรลุเป้าหมายกำไร 5% แล้ว! (${completedOrders}/${fc.targetProfitDailyOrders} ออเดอร์)`;
        progressColorClass = "bg-gradient-to-r from-emerald-400 via-teal-400 to-cyan-400 shadow-md shadow-emerald-500/30";
    } else if (completedOrders >= fc.breakEvenDailyOrders) {
        breakEvenStatusClass = "text-teal-300 font-bold";
        breakEvenBadgeText = `🟢 ถึงจุดคุ้มทุนแล้ว! เริ่มมีกำไร (ขาดอีก ${fc.targetProfitDailyOrders - completedOrders} ออเดอร์สู่เป้ากำไร 5%)`;
        progressColorClass = "bg-gradient-to-r from-amber-400 to-emerald-500";
    } else if (completedOrders >= 20) {
        breakEvenStatusClass = "text-amber-300 font-bold";
        breakEvenBadgeText = `🟡 ใกล้ถึงจุดคุ้มทุน (ต้องการอีก ${fc.breakEvenDailyOrders - completedOrders} ออเดอร์)`;
        progressColorClass = "bg-gradient-to-r from-amber-500 to-emerald-400";
    }

    const profitMarginPct = report.summary.totalCustomerGMV > 0 
        ? ((netDailyProfit / report.summary.totalCustomerGMV) * 100).toFixed(1) 
        : 0;

    const riderApps = loadRiderApplications();
    const pendingRiderApps = riderApps.filter(a => a.status === 'pending');
    let pendingBannerHtml = '';
    if (pendingRiderApps.length > 0) {
        pendingBannerHtml = `
        <div class="bg-gradient-to-r from-amber-500 via-orange-500 to-amber-600 rounded-3xl p-3.5 sm:p-4 text-white shadow-lg flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 animate-pulse border border-amber-300">
            <div class="flex items-center gap-3">
                <span class="w-11 h-11 rounded-2xl bg-white/25 backdrop-blur-md text-white flex items-center justify-center font-bold text-2xl shrink-0 shadow-xs">
                    🛵
                </span>
                <div>
                    <div class="flex items-center gap-2 flex-wrap">
                        <span class="font-black text-sm sm:text-base">มีใบสมัครร่วมทีมไรเดอร์ใหม่ ${pendingRiderApps.length} รายการ</span>
                        <span class="bg-white text-orange-700 font-black text-[10px] px-2.5 py-0.5 rounded-full shadow-xs">รอแอดมินอนุมัติ</span>
                    </div>
                    <p class="text-xs text-white/90 mt-0.5 font-medium">ผู้สมัครล่าสุด: <strong class="text-white underline">${escapeHtml(pendingRiderApps[0].fullName)}</strong> (${escapeHtml(pendingRiderApps[0].phone)}) • สมัครเข้ามาแล้ว</p>
                </div>
            </div>
            <button onclick="goToAdminToApproveRider(${jsArg(pendingRiderApps[0].id)})" class="px-4 py-2.5 bg-white hover:bg-amber-50 text-orange-700 font-black rounded-2xl text-xs shadow-md active:scale-95 transition-all flex items-center gap-1.5 whitespace-nowrap shrink-0 cursor-pointer">
                <span class="material-symbols-outlined text-base font-bold">check_circle</span>
                <span>ดูใบสมัครและกดอนุมัติทันที 🚀</span>
            </button>
        </div>
        `;
    }

    const pendingVerifyOrders = (report.ordersList || []).filter(o => o.paymentVerified !== true && o.paymentType !== 'cod');

    let html = `
    ${pendingBannerHtml}
    <!-- Top Filter Bar & Controls -->
    <div class="bg-white rounded-3xl p-3 sm:p-4 border border-slate-200 shadow-sm space-y-3">
        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2.5 pb-2.5 border-b border-slate-100">
            <div class="flex items-center gap-2">
                <span class="w-8 h-8 rounded-2xl bg-amber-500 text-white flex items-center justify-center font-black text-sm shadow-xs">
                    📑
                </span>
                <div>
                    <h3 class="font-extrabold text-slate-800 text-sm sm:text-base flex items-center gap-1.5">
                        <span>รายงานสรุปรายวัน ตลาดฮับวิศิษฐ์ชัย</span>
                        <span class="bg-emerald-100 text-emerald-800 text-[10px] font-bold px-2 py-0.5 rounded-full">Cloud DB</span>
                    </h3>
                    <p class="text-[10px] text-slate-500">ประจำวันที่ ${thaiDateText} ${isToday ? '<strong class="text-emerald-600">(วันนี้)</strong>' : ''}</p>
                </div>
            </div>

            <!-- Action buttons -->
            <div class="flex items-center gap-1.5 flex-wrap">
                <button onclick="renderHubDailyReport(${jsArg(targetDateKey)})" class="px-2.5 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl active:scale-95 transition-all flex items-center gap-1 shadow-2xs">
                    <span class="material-symbols-outlined text-sm">refresh</span>
                    <span>รีเฟรช</span>
                </button>
                <button onclick="exportDailyReportCSV(${jsArg(targetDateKey)})" class="px-2.5 py-1.5 bg-emerald-50 hover:bg-emerald-100 text-emerald-800 border border-emerald-200 font-bold rounded-xl active:scale-95 transition-all flex items-center gap-1 shadow-2xs">
                    <span class="material-symbols-outlined text-sm">download</span>
                    <span>ส่งออก CSV</span>
                </button>
                <button onclick="printDailyReport()" class="px-2.5 py-1.5 bg-slate-800 hover:bg-slate-900 text-white font-bold rounded-xl active:scale-95 transition-all flex items-center gap-1 shadow-2xs">
                    <span class="material-symbols-outlined text-sm">print</span>
                    <span>พิมพ์รายงาน A4</span>
                </button>
                <button onclick="clearDailyOrdersAndReport(${jsArg(targetDateKey)})" class="px-2.5 py-1.5 bg-amber-50 hover:bg-amber-100 text-amber-900 border border-amber-300 font-bold rounded-xl active:scale-95 transition-all flex items-center gap-1 shadow-2xs cursor-pointer" title="เคลียร์เฉพาะข้อมูลออเดอร์และรายงานของวันที่ ${thaiDateText} (ต้องใช้รหัสผ่าน Admin)">
                    <span class="material-symbols-outlined text-sm text-amber-700">event_busy</span>
                    <span>${isToday ? 'เคลียร์เฉพาะวันนี้' : 'เคลียร์เฉพาะวันที่เลือก (' + thaiDateText + ')'}</span>
                </button>
                <button onclick="clearAllSystemOrdersAndReports()" class="px-2.5 py-1.5 bg-rose-50 hover:bg-rose-100 text-rose-700 border border-rose-200 font-bold rounded-xl active:scale-95 transition-all flex items-center gap-1 shadow-2xs cursor-pointer" title="รีเซ็ตล้างข้อมูลออเดอร์ทุกวันทั้งระบบเป็น 0 (ต้องใช้รหัสผ่าน Admin)">
                    <span class="material-symbols-outlined text-sm">delete_forever</span>
                    <span>รีเซ็ตระบบทั้งหมด (ทุกวัน)</span>
                </button>
            </div>
        </div>

        <!-- Date selector toolbar with Prev/Next buttons -->
        <div class="flex items-center justify-between gap-2 flex-wrap text-[11px]">
            <div class="flex items-center gap-1.5">
                <span class="font-bold text-slate-600 flex items-center gap-1">
                    <span class="material-symbols-outlined text-sm text-slate-400">calendar_today</span>
                    <span>เลือกวันที่:</span>
                </span>
                <button onclick="navigateReportDay(-1)" title="วันก่อนหน้า" class="w-7 h-7 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-700 flex items-center justify-center font-bold active:scale-95 transition-all">
                    <span class="material-symbols-outlined text-sm">chevron_left</span>
                </button>
                <input type="date" id="hub-report-date-input" value="${targetDateKey}" onchange="changeReportDate(this.value)" class="border border-slate-300 rounded-xl px-2.5 py-1 bg-slate-50 font-bold text-slate-800 text-xs focus:ring-2 focus:ring-emerald-500 outline-none">
                <button onclick="navigateReportDay(1)" title="วันถัดไป" class="w-7 h-7 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-700 flex items-center justify-center font-bold active:scale-95 transition-all">
                    <span class="material-symbols-outlined text-sm">chevron_right</span>
                </button>
            </div>
            <div class="flex items-center gap-1.5 flex-wrap">
                <button onclick="setReportDateQuick(0)" class="px-2.5 py-1 rounded-lg font-bold ${isToday ? 'bg-emerald-600 text-white shadow-2xs' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'} transition-all cursor-pointer">วันนี้</button>
                <button onclick="setReportDateQuick(-1)" class="px-2.5 py-1 rounded-lg font-bold bg-slate-100 text-slate-600 hover:bg-slate-200 transition-all cursor-pointer">เมื่อวาน</button>
                <button onclick="openWeeklyAnalysisModal()" class="px-2.5 py-1 rounded-lg font-bold bg-indigo-50 text-indigo-700 hover:bg-indigo-100 border border-indigo-200 active:scale-95 transition-all flex items-center gap-1 shadow-2xs cursor-pointer" title="วิเคราะห์สรุปยอดขาย กำไร และสถิติรายสัปดาห์">
                    <span class="material-symbols-outlined text-sm text-indigo-600">query_stats</span>
                    <span>วิเคราะห์รายสัปดาห์</span>
                </button>
                <button onclick="openMonthlyAnalysisModal()" class="px-2.5 py-1 rounded-lg font-bold bg-purple-50 text-purple-700 hover:bg-purple-100 border border-purple-200 active:scale-95 transition-all flex items-center gap-1 shadow-2xs cursor-pointer" title="วิเคราะห์สรุปยอดขาย กำไร และสถิติรายเดือน">
                    <span class="material-symbols-outlined text-sm text-purple-600">calendar_month</span>
                    <span>วิเคราะห์รายเดือน</span>
                </button>
            </div>
        </div>
    </div>

    <!-- 4 Primary KPI Cards (GMV, Vendor Cost, Rider Settlement & Hub Net Margin) -->
    <div class="grid grid-cols-2 lg:grid-cols-4 gap-2.5 sm:gap-3">
        <!-- Card 1: GMV ลูกค้า -->
        <div class="bg-gradient-to-br from-emerald-600 to-teal-800 text-white rounded-3xl p-3.5 sm:p-4 shadow-md space-y-1.5 relative overflow-hidden">
            <div class="flex items-center justify-between">
                <span class="text-[10px] sm:text-[11px] font-bold text-emerald-200 flex items-center gap-1">
                    <span class="material-symbols-outlined text-sm">shopping_bag</span>
                    <span>ยอดขายรวม (GMV)</span>
                </span>
                <span class="text-[9px] bg-white/20 font-bold px-1.5 py-0.2 rounded-full">${report.summary.totalOrders} ใบ</span>
            </div>
            <div class="text-xl sm:text-2xl font-black tracking-tight">฿${report.summary.totalCustomerGMV.toLocaleString()}</div>
            <div class="text-[9px] sm:text-[10px] text-emerald-100/90 pt-1 border-t border-white/15">
                <span>สำเร็จ ${report.summary.completedOrders} | ค่าส่ง ฿${report.summary.totalDeliveryFees.toLocaleString()}</span>
            </div>
        </div>

        <!-- Card 2: เคลียร์เงินร้านค้า/แผงค้า -->
        <div class="bg-gradient-to-br from-amber-600 to-orange-700 text-white rounded-3xl p-3.5 sm:p-4 shadow-md space-y-1.5 relative overflow-hidden">
            <div class="flex items-center justify-between">
                <span class="text-[10px] sm:text-[11px] font-bold text-amber-200 flex items-center gap-1">
                    <span class="material-symbols-outlined text-sm">storefront</span>
                    <span>ยอดโอนสุทธิแผงค้า</span>
                </span>
                <span class="text-[9px] bg-white/20 font-bold px-1.5 py-0.2 rounded-full">${report.vendorSettlement.stalls.length} แผง</span>
            </div>
            <div class="text-xl sm:text-2xl font-black tracking-tight">฿${report.vendorSettlement.totalVendorAmount.toLocaleString()}</div>
            <div class="text-[9px] sm:text-[10px] text-amber-100/90 pt-1 border-t border-white/15">
                <span>ยอดขาย ฿${report.vendorSettlement.totalVendorGross.toLocaleString()} | หัก GP -฿${report.vendorSettlement.totalVendorGP.toLocaleString()}</span>
            </div>
        </div>

        <!-- Card 3: เคลียร์เงินไรเดอร์ -->
        <div class="bg-gradient-to-br from-sky-600 to-blue-800 text-white rounded-3xl p-3.5 sm:p-4 shadow-md space-y-1.5 relative overflow-hidden">
            <div class="flex items-center justify-between">
                <span class="text-[10px] sm:text-[11px] font-bold text-sky-200 flex items-center gap-1">
                    <span class="material-symbols-outlined text-sm">two_wheeler</span>
                    <span>เงินสดสุทธิส่งฮับ</span>
                </span>
                <span class="text-[9px] bg-white/20 font-bold px-1.5 py-0.2 rounded-full">${report.riderSettlement.totalTrips} เที่ยว</span>
            </div>
            <div class="text-xl sm:text-2xl font-black tracking-tight">฿${report.riderSettlement.netCashToHub.toLocaleString()}</div>
            <div class="text-[9px] sm:text-[10px] text-sky-100/90 pt-1 border-t border-white/15">
                <span>COD ฿${report.riderSettlement.totalCodCollected.toLocaleString()} | ค่ารอบ -฿${report.riderSettlement.totalRiderFees.toLocaleString()}</span>
            </div>
        </div>

        <!-- Card 4: รายรับค่าบริการสุทธิของฮับ (Hub Net Margin) -->
        <div class="bg-gradient-to-br from-purple-700 to-indigo-900 text-white rounded-3xl p-3.5 sm:p-4 shadow-md space-y-1.5 relative overflow-hidden">
            <div class="flex items-center justify-between">
                <span class="text-[10px] sm:text-[11px] font-bold text-purple-200 flex items-center gap-1">
                    <span class="material-symbols-outlined text-sm">account_balance</span>
                    <span>กำไรค่าบริการสุทธิฮับ</span>
                </span>
                <span class="text-[9px] bg-white/20 font-bold px-1.5 py-0.2 rounded-full">Net Margin</span>
            </div>
            <div class="text-xl sm:text-2xl font-black tracking-tight ${hubNetMargin >= 0 ? 'text-emerald-300' : 'text-rose-300'}">
                ฿${hubNetMargin.toLocaleString()}
            </div>
            <div class="text-[9px] sm:text-[10px] text-purple-100/90 pt-1 border-t border-white/15">
                <span>(รายรับ ฿${hubGrossRevenue.toLocaleString()} - ค่ารอบ ฿${report.riderSettlement.totalRiderFees.toLocaleString()})</span>
            </div>
        </div>
    </div>

    <!-- 🌟 แถบวิเคราะห์จุดคุ้มทุน & งบกำไร-ขาดทุนรายวัน (P&L & Break-even Ledger) -->
    <div class="bg-gradient-to-br from-slate-900 via-indigo-950 to-slate-900 text-white rounded-3xl p-4 sm:p-5 shadow-xl border border-indigo-500/30 space-y-4">
        <!-- Header & Target Status -->
        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pb-3 border-b border-white/10">
            <div class="flex items-center gap-3">
                <span class="w-10 h-10 rounded-2xl bg-gradient-to-tr from-amber-400 to-orange-500 text-white flex items-center justify-center font-black text-lg shadow-sm">
                    📊
                </span>
                <div>
                    <h4 class="font-extrabold text-sm sm:text-base text-white flex items-center gap-2 flex-wrap">
                        <span>วิเคราะห์จุดคุ้มทุน & งบกำไร-ขาดทุนรายวัน (Daily P&L Ledger)</span>
                        <span class="text-[10px] bg-emerald-500/20 text-emerald-300 border border-emerald-500/30 px-2 py-0.5 rounded-full font-bold">เป้าหมายกำไร 5%</span>
                    </h4>
                    <p class="text-[11px] text-slate-400">หักต้นทุนคงที่เฉลี่ยรายวัน (ค่าเช่า ฿${fc.officeRent.toLocaleString()} + เงินเดือน ฿${fc.staffSalary.toLocaleString()} + สนง. ฿${fc.utilitiesSupplies.toLocaleString()})</p>
                </div>
            </div>
            <div class="flex items-center gap-2">
                <button onclick="openFixedCostsModal()" class="px-3 py-1.5 bg-white/10 hover:bg-white/20 text-indigo-200 border border-white/15 rounded-xl text-xs font-bold transition-all flex items-center gap-1.5 cursor-pointer shadow-xs active:scale-95">
                    <span class="material-symbols-outlined text-sm">tune</span>
                    <span>ปรับแต่งต้นทุนคงที่</span>
                </button>
            </div>
        </div>

        <!-- Break-even Progress Meter -->
        <div class="bg-white/5 rounded-2xl p-3.5 border border-white/10 space-y-2.5">
            <div class="flex items-center justify-between text-xs flex-wrap gap-1">
                <span class="font-bold text-slate-300 flex items-center gap-1.5">
                    <span class="material-symbols-outlined text-amber-400 text-sm">flag</span>
                    <span>ความคืบหน้าสู่จุดคุ้มทุนวันนี้ (Break-even Progress):</span>
                </span>
                <span class="font-extrabold ${breakEvenStatusClass}">
                    ${breakEvenBadgeText}
                </span>
            </div>

            <!-- Progress Bar with Markers -->
            <div class="space-y-1">
                <div class="w-full bg-slate-800 rounded-full h-3.5 p-0.5 border border-white/10 relative overflow-hidden">
                    <div class="h-full rounded-full transition-all duration-700 ${progressColorClass}" style="width: ${progressPercent}%"></div>
                </div>
                <div class="flex items-center justify-between text-[10px] text-slate-400 font-mono">
                    <span>0 ออเดอร์</span>
                    <span class="text-amber-300 font-bold">🎯 จุดคุ้มทุน: ${fc.breakEvenDailyOrders} ออเดอร์</span>
                    <span class="text-emerald-300 font-bold">🏆 เป้ากำไร 5%: ${fc.targetProfitDailyOrders} ออเดอร์</span>
                    <span class="text-white font-black">${completedOrders} สำเร็จ (${progressPercent}%)</span>
                </div>
            </div>
        </div>

        <!-- 3-Column Daily P&L Breakdown -->
        <div class="grid grid-cols-1 md:grid-cols-3 gap-3 text-xs">
            <!-- 1. รายรับรวมฮับ -->
            <div class="bg-white/5 rounded-2xl p-3.5 border border-white/10 space-y-2">
                <div class="text-[11px] font-bold text-emerald-400 flex items-center justify-between">
                    <span>1. รายรับรวมฮับ (Gross Revenue)</span>
                    <span class="material-symbols-outlined text-sm">arrow_circle_down</span>
                </div>
                <div class="text-xl font-black text-white">฿${hubGrossRevenue.toLocaleString()}</div>
                <div class="text-[10px] text-slate-300 space-y-1 pt-1 border-t border-white/10 font-mono">
                    <div class="flex justify-between"><span>• ค่าส่งลูกค้า:</span><strong>฿${totalDeliveryFees.toLocaleString()}</strong></div>
                    <div class="flex justify-between"><span>• GP แผงค้า (${report.vendorSettlement.gpRate || 10}%):</span><strong class="text-amber-300">฿${totalVendorGP.toLocaleString()}</strong></div>
                    <div class="flex justify-between"><span>• ค่าส่งด่วน Express:</span><strong>฿${totalExpressFees.toLocaleString()}</strong></div>
                </div>
            </div>

            <!-- 2. ต้นทุนรวม (ผันแปร + คงที่) -->
            <div class="bg-white/5 rounded-2xl p-3.5 border border-white/10 space-y-2">
                <div class="text-[11px] font-bold text-rose-400 flex items-center justify-between">
                    <span>2. ต้นทุนรวมฮับ (Total Costs)</span>
                    <span class="material-symbols-outlined text-sm">arrow_circle_up</span>
                </div>
                <div class="text-xl font-black text-white">฿${(report.riderSettlement.totalRiderFees + dailyFixedCost).toLocaleString()}</div>
                <div class="text-[10px] text-slate-300 space-y-1 pt-1 border-t border-white/10 font-mono">
                    <div class="flex justify-between"><span>• ค่ารอบไรเดอร์ (ผันแปร):</span><strong>฿${report.riderSettlement.totalRiderFees.toLocaleString()}</strong></div>
                    <div class="flex justify-between"><span>• ต้นทุนคงที่เฉลี่ยต่อวัน:</span><strong class="text-rose-300">฿${dailyFixedCost.toLocaleString()}</strong></div>
                    <div class="flex justify-between text-[9px] text-slate-400"><span>(ค่าเช่า ฿${Math.round(fc.officeRent/fc.daysInMonth)} + เงินเดือน ฿${Math.round(fc.staffSalary/fc.daysInMonth)})</span></div>
                </div>
            </div>

            <!-- 3. กำไรสุทธิหลังหักทุกอย่าง (Net Profit / Loss) -->
            <div class="bg-gradient-to-br ${netDailyProfit >= 0 ? 'from-emerald-950/80 to-teal-900/60 border-emerald-500/40' : 'from-rose-950/80 to-pink-900/60 border-rose-500/40'} rounded-2xl p-3.5 border space-y-2">
                <div class="text-[11px] font-bold ${netDailyProfit >= 0 ? 'text-emerald-300' : 'text-rose-300'} flex items-center justify-between">
                    <span>3. กำไร/ขาดทุนสุทธิ (Net Operating Profit)</span>
                    <span class="material-symbols-outlined text-sm">${netDailyProfit >= 0 ? 'trending_up' : 'trending_down'}</span>
                </div>
                <div class="text-2xl font-black ${netDailyProfit >= 0 ? 'text-emerald-300' : 'text-rose-400'}">
                    ${netDailyProfit >= 0 ? '+' : ''}฿${netDailyProfit.toLocaleString()}
                </div>
                <div class="text-[10px] ${netDailyProfit >= 0 ? 'text-emerald-200' : 'text-rose-200'} pt-1 border-t border-white/10 font-medium">
                    ${netDailyProfit >= 0 
                        ? `🎉 กำไรสุทธิคิดเป็น ${profitMarginPct}% ของยอดขาย (เกินจุดคุ้มทุนแล้ว)`
                        : `⚠️ ขาดทุนสุทธิประจำวัน (ต้องการอีก ${Math.max(0, fc.breakEvenDailyOrders - completedOrders)} ออเดอร์เพื่อเท่าทุน)`}
                </div>
            </div>
        </div>
    </div>

    <!-- Section 1: Customer Revenue & Payment Method Breakdown -->
    <div class="bg-white rounded-3xl p-4 border border-slate-200 shadow-sm space-y-3">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
            <h4 class="font-bold text-slate-800 text-xs sm:text-sm flex items-center gap-1.5">
                <span class="material-symbols-outlined text-emerald-600 text-base">payments</span>
                <span>1. รายรับลูกค้า & ช่องทางชำระเงิน (Customer Payment Breakdown)</span>
            </h4>
            <span class="text-[10px] text-slate-500 font-bold">รวม ${report.summary.totalOrders} ออเดอร์</span>
        </div>

        <div class="grid grid-cols-1 sm:grid-cols-3 gap-2.5">
            <!-- PromptPay -->
            <div class="p-3 bg-blue-50/70 border border-blue-200/80 rounded-2xl flex items-center justify-between">
                <div>
                    <div class="text-[11px] font-bold text-blue-900 flex items-center gap-1">
                        <span class="w-2 h-2 rounded-full bg-blue-600"></span>
                        <span>พร้อมเพย์ (QR PromptPay)</span>
                    </div>
                    <div class="text-[10px] text-blue-700 font-medium">${report.summary.paymentBreakdown.promptpay.count} ออเดอร์</div>
                </div>
                <div class="text-right">
                    <div class="font-extrabold text-blue-950 text-sm">฿${report.summary.paymentBreakdown.promptpay.amount.toLocaleString()}</div>
                    <span class="text-[9px] bg-blue-100 text-blue-800 font-bold px-1.5 py-0.2 rounded">เข้าบัญชีฮับ</span>
                </div>
            </div>

            <!-- SCB Bank Transfer -->
            <div class="p-3 bg-purple-50/70 border border-purple-200/80 rounded-2xl flex items-center justify-between">
                <div>
                    <div class="text-[11px] font-bold text-purple-900 flex items-center gap-1">
                        <span class="w-2 h-2 rounded-full bg-purple-600"></span>
                        <span>โอนธนาคาร SCB</span>
                    </div>
                    <div class="text-[10px] text-purple-700 font-medium">${report.summary.paymentBreakdown.bank_transfer.count} ออเดอร์</div>
                </div>
                <div class="text-right">
                    <div class="font-extrabold text-purple-950 text-sm">฿${report.summary.paymentBreakdown.bank_transfer.amount.toLocaleString()}</div>
                    <span class="text-[9px] bg-purple-100 text-purple-800 font-bold px-1.5 py-0.2 rounded">แนบสลิป</span>
                </div>
            </div>

            <!-- Cash on Delivery -->
            <div class="p-3 bg-amber-50/70 border border-amber-200/80 rounded-2xl flex items-center justify-between">
                <div>
                    <div class="text-[11px] font-bold text-amber-900 flex items-center gap-1">
                        <span class="w-2 h-2 rounded-full bg-amber-600"></span>
                        <span>เงินสดปลายทาง (COD)</span>
                    </div>
                    <div class="text-[10px] text-amber-700 font-medium">${report.summary.paymentBreakdown.cod.count} ออเดอร์</div>
                </div>
                <div class="text-right">
                    <div class="font-extrabold text-amber-950 text-sm">฿${report.summary.paymentBreakdown.cod.amount.toLocaleString()}</div>
                    <span class="text-[9px] bg-amber-100 text-amber-800 font-bold px-1.5 py-0.2 rounded">ไรเดอร์ถืออยู่</span>
                </div>
            </div>
        </div>

        ${report.summary.totalRefundCash > 0 ? `
        <div class="p-2.5 bg-rose-50 border border-rose-200 rounded-xl flex items-center justify-between text-[11px] text-rose-800">
            <div class="flex items-center gap-1.5">
                <span class="material-symbols-outlined text-rose-600 text-base">price_check</span>
                <span><strong>เงินทอนคืนลูกค้ากรณีสินค้าขาด (Cash Refund):</strong> หักคืนเงินสดใส่ถุงให้ลูกค้า</span>
            </div>
            <div class="font-black text-rose-700">฿${report.summary.totalRefundCash.toLocaleString()}</div>
        </div>` : ''}
    </div>

    <!-- Section 2: Rider Settlement Summary Table -->
    <div class="bg-white rounded-3xl p-4 border border-slate-200 shadow-sm space-y-3">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
            <div>
                <h4 class="font-bold text-slate-800 text-xs sm:text-sm flex items-center gap-1.5">
                    <span class="material-symbols-outlined text-sky-600 text-base">sports_motorsports</span>
                    <span>2. เคลียร์เงินไรเดอร์ (Rider Compensation & COD Clearance)</span>
                </h4>
                <p class="text-[10px] text-slate-500">ค่ารอบ ฿40/เที่ยว | หักเงินสด COD และเงินทอน | ยอดสุทธิส่งมอบฮับ</p>
            </div>
            <div class="text-right">
                <div class="text-[10px] text-slate-500">ยอดสุทธิรวมที่ฮับต้องรับมอบ:</div>
                <div class="font-extrabold text-sky-700 text-sm">฿${report.riderSettlement.netCashToHub.toLocaleString()}</div>
            </div>
        </div>

        ${report.riderSettlement.riders.length === 0 ? `
        <div class="p-6 text-center text-slate-400 bg-slate-50 rounded-2xl">
            <span class="material-symbols-outlined text-3xl mb-1 text-slate-300">moped</span>
            <div>ยังไม่มีรอบการจัดส่งของไรเดอร์ในวันที่เลือก</div>
        </div>` : `
        <div class="overflow-x-auto">
            <table class="w-full text-left text-[11px]">
                <thead>
                    <tr class="bg-slate-100 text-slate-700 font-bold border-b border-slate-200">
                        <th class="p-2.5 rounded-l-xl">ไรเดอร์</th>
                        <th class="p-2.5 text-center">เที่ยวส่ง</th>
                        <th class="p-2.5 text-right">ค่ารอบสะสม</th>
                        <th class="p-2.5 text-right">เงินสด COD เก็บมา</th>
                        <th class="p-2.5 text-right">เงินทอนคืนลูกค้า</th>
                        <th class="p-2.5 text-right">ยอดสุทธิส่งฮับ</th>
                        <th class="p-2.5 text-center">สถานะ</th>
                        <th class="p-2.5 text-center">จัดการ</th>
                        <th class="p-2.5 text-center rounded-r-xl">พิมพ์ (80mm)</th>
                    </tr>
                </thead>
                <tbody class="divide-y divide-slate-100">
                    ${report.riderSettlement.riders.map(r => `
                    <tr class="hover:bg-slate-50/70 transition-colors">
                        <td class="p-2.5">
                            <div class="font-extrabold text-slate-800 text-xs">${escapeHtml(r.riderName)}</div>
                            <div class="text-[10px] text-slate-400 font-mono">${escapeHtml(r.riderPhone)}</div>
                        </td>
                        <td class="p-2.5 text-center font-bold text-slate-700">${r.tripsCount} เที่ยว</td>
                        <td class="p-2.5 text-right font-bold text-sky-700">฿${r.riderFeeEarned.toLocaleString()}</td>
                        <td class="p-2.5 text-right font-bold text-amber-700">
                            <div>฿${r.codCollected.toLocaleString()}</div>
                            ${r.codCollected >= 3000 ? `
                            <span class="inline-flex items-center gap-0.5 text-[9px] bg-rose-100 text-rose-700 font-extrabold px-1.5 py-0.2 rounded-md animate-pulse">
                                <span class="material-symbols-outlined text-[10px]">warning</span>
                                <span>เกิน ฿3,000</span>
                            </span>` : ''}
                        </td>
                        <td class="p-2.5 text-right font-bold text-rose-600">${r.refundHanded > 0 ? `-฿${r.refundHanded.toLocaleString()}` : '฿0'}</td>
                        <td class="p-2.5 text-right">
                            <span class="font-black text-xs ${r.netCashToHub >= 0 ? 'text-emerald-700' : 'text-rose-700'}">
                                ${r.netCashToHub >= 0 ? `฿${r.netCashToHub.toLocaleString()}` : `-฿${Math.abs(r.netCashToHub).toLocaleString()}`}
                            </span>
                            <div class="text-[9px] text-slate-400 font-medium">
                                ${r.netCashToHub >= 0 ? '(ไรเดอร์ส่งฮับ)' : '(ฮับจ่ายเพิ่ม)'}
                            </div>
                            ${(r.netCashToHub >= 3000 && !r.isSettled) ? `
                            <div class="text-[9px] text-rose-600 font-black animate-pulse flex items-center justify-end gap-0.5 mt-0.5">
                                <span class="material-symbols-outlined text-[11px]">priority_high</span>
                                <span>ต้องส่งมอบฮับทันที</span>
                            </div>` : ''}
                        </td>
                        <td class="p-2.5 text-center">
                            ${r.isSettled ? `
                            <span class="bg-emerald-100 text-emerald-800 font-bold px-2 py-0.5 rounded-full text-[10px] inline-flex items-center gap-0.5">
                                <span class="material-symbols-outlined text-xs">check</span>
                                <span>เคลียร์แล้ว</span>
                            </span>` : `
                            <span class="bg-amber-100 text-amber-800 font-bold px-2 py-0.5 rounded-full text-[10px] inline-flex items-center gap-0.5">
                                <span class="material-symbols-outlined text-xs">pending</span>
                                <span>รอเคลียร์</span>
                            </span>`}
                        </td>
                        <td class="p-2.5 text-center">
                            <button onclick="goToFleetClearance()" class="px-2.5 py-1 bg-sky-50 hover:bg-sky-100 text-sky-800 border border-sky-200 font-bold rounded-lg text-[10px] active:scale-95 transition-all shadow-2xs flex items-center gap-1 mx-auto cursor-pointer" title="ไปเคลียร์เงินที่หน้าไรเดอร์">
                                <span class="material-symbols-outlined text-xs">open_in_new</span>
                                <span>ไปหน้าไรเดอร์</span>
                            </button>
                        </td>
                        <td class="p-2.5 text-center">
                            <button onclick="printThermalRiderSlip(${jsArg(r.riderName)}, ${jsArg(targetDateKey)})" class="px-2.5 py-1 bg-sky-50 hover:bg-sky-100 text-sky-800 border border-sky-200 font-bold rounded-xl text-[10px] active:scale-95 transition-all shadow-2xs flex items-center gap-1 mx-auto cursor-pointer" title="พิมพ์สลิปเครื่องพิมพ์ความร้อน 80x80">
                                <span class="material-symbols-outlined text-xs">receipt</span>
                                <span>พิมพ์สลิป</span>
                            </button>
                        </td>
                    </tr>`).join("")}
                </tbody>
            </table>
        </div>`}
        <!-- ปุ่มพิมพ์สรุปกระดาษ A4 ตรงกลางด้านล่างหมวด 2 -->
        <div class="pt-3 border-t border-slate-100 flex justify-center">
            <button onclick="printA4RidersSummary(${jsArg(targetDateKey)})" class="px-4 py-2 bg-gradient-to-r from-sky-600 to-blue-700 hover:from-sky-700 hover:to-blue-800 text-white font-extrabold rounded-xl text-xs shadow-sm active:scale-95 transition-all flex items-center gap-2 cursor-pointer">
                <span class="material-symbols-outlined text-sm">print</span>
                <span>📄 พิมพ์สรุปเคลียร์เงินไรเดอร์ทั้งหมด (กระดาษ A4)</span>
            </button>
        </div>
    </div>

    <!-- Section 3: Vendor / Stall Settlement Summary Table -->
    <div class="bg-white rounded-3xl p-4 border border-slate-200 shadow-sm space-y-3">
        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 pb-2 border-b border-slate-100">
            <div>
                <h4 class="font-bold text-slate-800 text-xs sm:text-sm flex items-center gap-1.5">
                    <span class="material-symbols-outlined text-amber-600 text-base">store</span>
                    <span>3. เคลียร์เงินร้านค้า/แผงค้า (Vendor Settlements)</span>
                </h4>
                <p class="text-[10px] text-slate-500">ยอดรวมสินค้าที่หยิบจริง | โอนตรงด้วยระบบ PromptPay QR รายแผง</p>
            </div>
            <div class="flex items-center gap-2">
                <div class="text-right hidden sm:block">
                    <span class="text-[10px] text-slate-500">รอโอนเคลียร์:</span>
                    <span class="font-black text-rose-600 text-sm ml-1">฿${report.vendorSettlement.totalPendingAmount.toLocaleString()}</span>
                </div>
                ${report.vendorSettlement.pendingCount > 0 ? `
                <button onclick="settleAllVendors(${jsArg(targetDateKey)})" class="px-3 py-1.5 bg-gradient-to-r from-emerald-600 to-teal-700 hover:from-emerald-700 text-white font-extrabold rounded-xl text-[10px] shadow-2xs active:scale-95 transition-all flex items-center gap-1">
                    <span class="material-symbols-outlined text-xs">done_all</span>
                    <span>โอนเคลียร์ทุกแผงที่เหลือ</span>
                </button>` : ''}
            </div>
        </div>

        ${report.vendorSettlement.stalls.length === 0 ? `
        <div class="p-6 text-center text-slate-400 bg-slate-50 rounded-2xl">
            <span class="material-symbols-outlined text-3xl mb-1 text-slate-300">storefront</span>
            <div>ยังไม่มีรายการสินค้าจากแผงค้าในวันที่เลือก</div>
        </div>` : `
        <div class="overflow-x-auto">
            <table class="w-full text-left text-[11px]">
                <thead>
                    <tr class="bg-slate-100 text-slate-700 font-bold border-b border-slate-200">
                        <th class="p-2.5 rounded-l-xl">แผงค้า / ร้านค้า</th>
                        <th class="p-2.5">เจ้าของ / เบอร์พร้อมเพย์</th>
                        <th class="p-2.5 text-center">จำนวนที่ขาย</th>
                        <th class="p-2.5 text-right">ยอดขายรวม</th>
                        <th class="p-2.5 text-right">หัก GP (${report.vendorSettlement.gpRate || 10}%)</th>
                        <th class="p-2.5 text-right">ยอดโอนสุทธิ</th>
                        <th class="p-2.5 text-center">สถานะ</th>
                        <th class="p-2.5 text-center">โอนเคลียร์</th>
                        <th class="p-2.5 text-center rounded-r-xl">พิมพ์ (80mm)</th>
                    </tr>
                </thead>
                <tbody class="divide-y divide-slate-100">
                    ${report.vendorSettlement.stalls.map(s => `
                    <tr class="hover:bg-slate-50/70 transition-colors">
                        <td class="p-2.5">
                            <div class="font-extrabold text-slate-800 text-xs">${escapeHtml(s.stallName)}</div>
                            <span class="text-[9px] bg-slate-100 text-slate-600 font-bold px-1.5 py-0.2 rounded">${escapeHtml(s.stallNumber)} (โซน ${escapeHtml(s.zone)})</span>
                        </td>
                        <td class="p-2.5">
                            <div class="font-bold text-slate-700">${escapeHtml(s.ownerName)}</div>
                            <div class="text-[10px] text-emerald-700 font-mono font-bold flex items-center gap-1">
                                <span>📱 ${escapeHtml(s.phone)}</span>
                            </div>
                        </td>
                        <td class="p-2.5 text-center">
                            <div class="font-bold text-slate-700">${s.itemsCount} ชิ้น</div>
                            <div class="text-[9px] text-slate-400 font-medium">(${s.orderCount} ออเดอร์)</div>
                        </td>
                        <td class="p-2.5 text-right font-medium text-slate-600">
                            ฿${s.totalAmount.toLocaleString()}
                        </td>
                        <td class="p-2.5 text-right font-bold text-orange-600">
                            -฿${(s.gpAmount || 0).toLocaleString()}
                        </td>
                        <td class="p-2.5 text-right">
                            <div class="font-black text-sm text-emerald-800">฿${(s.payoutAmount !== undefined ? s.payoutAmount : s.totalAmount).toLocaleString()}</div>
                        </td>
                        <td class="p-2.5 text-center">
                            ${s.isSettled ? `
                            <span class="bg-emerald-100 text-emerald-800 font-bold px-2 py-0.5 rounded-full text-[10px] inline-flex items-center gap-0.5">
                                <span class="material-symbols-outlined text-xs">check_circle</span>
                                <span>โอนแล้ว</span>
                            </span>` : `
                            <span class="bg-rose-100 text-rose-800 font-bold px-2 py-0.5 rounded-full text-[10px] inline-flex items-center gap-0.5">
                                <span class="material-symbols-outlined text-xs">schedule</span>
                                <span>รอโอน</span>
                            </span>`}
                        </td>
                        <td class="p-2.5 text-center">
                            <button onclick="openVendorPayoutModal(${jsArg(s.stallId)}, ${jsArg(s.stallName)}, ${(s.payoutAmount !== undefined ? s.payoutAmount : s.totalAmount)}, ${jsArg(s.phone)}, ${jsArg(s.ownerName)}, ${jsArg(s.stallNumber)}, ${s.totalAmount}, ${s.gpAmount || 0}, ${s.gpRate || 10})" class="px-2.5 py-1.5 ${s.isSettled ? 'bg-slate-100 text-slate-600 hover:bg-slate-200' : 'bg-emerald-600 hover:bg-emerald-700 text-white shadow-xs'} font-bold rounded-xl text-[10px] active:scale-95 transition-all flex items-center gap-1 mx-auto">
                                <span class="material-symbols-outlined text-xs">qr_code_2</span>
                                <span>${s.isSettled ? 'ดู QR / โอนซ้ำ' : '💳 โอนพร้อมเพย์'}</span>
                            </button>
                        </td>
                        <td class="p-2.5 text-center">
                            <button onclick="printThermalVendorSlip(${jsArg(s.stallId)}, ${jsArg(targetDateKey)})" class="px-2.5 py-1.5 bg-amber-50 hover:bg-amber-100 text-amber-900 border border-amber-200 font-bold rounded-xl text-[10px] active:scale-95 transition-all shadow-2xs flex items-center gap-1 mx-auto cursor-pointer" title="พิมพ์สลิปเครื่องพิมพ์ความร้อน 80x80">
                                <span class="material-symbols-outlined text-xs">receipt</span>
                                <span>พิมพ์สลิป</span>
                            </button>
                        </td>
                    </tr>`).join("")}
                </tbody>
            </table>
        </div>`}
        <!-- ปุ่มพิมพ์สรุปกระดาษ A4 ตรงกลางด้านล่างหมวด 3 -->
        <div class="pt-3 border-t border-slate-100 flex justify-center">
            <button onclick="printA4VendorsSummary(${jsArg(targetDateKey)})" class="px-4 py-2 bg-gradient-to-r from-amber-600 to-orange-700 hover:from-amber-700 hover:to-orange-800 text-white font-extrabold rounded-xl text-xs shadow-sm active:scale-95 transition-all flex items-center gap-2 cursor-pointer">
                <span class="material-symbols-outlined text-sm">print</span>
                <span>📄 พิมพ์สรุปยอดเคลียร์เงินแผงค้าทั้งหมด (กระดาษ A4)</span>
            </button>
        </div>
    </div>

    <!-- Section 4: Daily Orders Audit Ledger -->
    <div class="bg-white rounded-3xl p-4 border border-slate-200 shadow-sm space-y-3">
        <div class="flex items-center justify-between pb-2 border-b border-slate-100">
            <div>
                <h4 class="font-bold text-slate-800 text-xs sm:text-sm flex items-center gap-1.5">
                    <span class="material-symbols-outlined text-slate-600 text-base">receipt_long</span>
                    <span>4. บัญชีแยกประเภทออเดอร์ประจำวัน (Daily Orders Audit Ledger)</span>
                </h4>
                <p class="text-[10px] text-slate-500">บันทึกประวัติออเดอร์ทั้งหมดในระบบของวันที่ ${thaiDateText}</p>
            </div>
            <span class="text-[10px] bg-slate-100 text-slate-700 font-bold px-2.5 py-1 rounded-full">
                ทั้งหมด ${report.ordersList.length} ใบ
            </span>
        </div>

        ${pendingVerifyOrders.length > 0 ? `
        <div class="bg-gradient-to-r from-amber-500 via-orange-500 to-amber-600 rounded-2xl p-3.5 text-white shadow-sm flex flex-col sm:flex-row sm:items-center justify-between gap-3 animate-fade-in border border-amber-300">
            <div class="flex items-center gap-2.5">
                <span class="w-9 h-9 rounded-xl bg-white/20 backdrop-blur-xs flex items-center justify-center font-black text-base shrink-0">
                    ⏳
                </span>
                <div>
                    <div class="flex items-center gap-2">
                        <span class="font-black text-xs sm:text-sm">มี ${pendingVerifyOrders.length} ออเดอร์ที่รอยืนยันยอดโอนเข้าบัญชี</span>
                        <span class="bg-white text-orange-800 text-[10px] font-black px-2 py-0.5 rounded-full">ตรวจสลิปก่อนปล่อยงาน</span>
                    </div>
                    <div class="text-[10.5px] text-amber-50 leading-snug mt-0.5">
                        ตรวจสอบสลิปและเปรียบเทียบยอดมีเศษสตางค์ในแอปธนาคาร เพื่อให้มั่นใจ 100% ว่าได้รับเงินจริง
                    </div>
                </div>
            </div>
            <div class="flex items-center gap-1.5 flex-wrap shrink-0">
                ${pendingVerifyOrders.slice(0, 3).map(p => `
                    <button onclick="openOrderSlipVerificationModal(${jsArg(p.orderId)})" class="px-3 py-1.5 bg-white hover:bg-orange-50 text-orange-950 font-black rounded-xl text-[11px] shadow-xs active:scale-95 transition-all flex items-center gap-1 cursor-pointer">
                        <span class="material-symbols-outlined text-xs text-orange-600">receipt_long</span>
                        <span>ตรวจ ${escapeHtml(p.orderId)} (฿${p.payAmountExact !== undefined && p.payAmountExact !== null ? Number(p.payAmountExact).toFixed(2) : (p.grandTotal || p.total || 0).toLocaleString()})</span>
                    </button>
                `).join("")}
            </div>
        </div>
        ` : ''}

        ${report.ordersList.length === 0 ? `
        <div class="p-6 text-center text-slate-400 bg-slate-50 rounded-2xl">
            <span class="material-symbols-outlined text-3xl mb-1 text-slate-300">inbox</span>
            <div>ไม่มีประวัติคำสั่งซื้อในวันที่นี้</div>
        </div>` : `
        <div class="overflow-x-auto">
            <table class="w-full text-left text-[11px]">
                <thead>
                    <tr class="bg-slate-100 text-slate-700 font-bold border-b border-slate-200">
                        <th class="p-2.5 rounded-l-xl">เลขที่ออเดอร์ / เวลา</th>
                        <th class="p-2.5">ลูกค้า</th>
                        <th class="p-2.5">ช่องทางชำระเงิน</th>
                        <th class="p-2.5 text-right">ยอดรวม</th>
                        <th class="p-2.5">ไรเดอร์นำส่ง</th>
                        <th class="p-2.5 text-center">สถานะ</th>
                        <th class="p-2.5 text-center rounded-r-xl">จัดการ / พิมพ์สลิป</th>
                    </tr>
                </thead>
                <tbody class="divide-y divide-slate-100">
                    ${report.ordersList.map(o => {
                        const timeStr = o.savedAt ? new Date(o.savedAt).toLocaleTimeString("th-TH", { hour: '2-digit', minute: '2-digit' }) : (o.orderTime || "--:--");
                        const cfg = ORDER_STATUS_CONFIG[o.status] || ORDER_STATUS_CONFIG.picking;
                        const isPaymentVerified = o.paymentVerified === true || o.paymentType === "cod";
                        const exactAmtDisplay = (o.payAmountExact !== undefined && o.payAmountExact !== null)
                            ? Number(o.payAmountExact).toFixed(2)
                            : (o.grandTotal || o.total || 0).toLocaleString();
                        const payChannelLabel = o.paymentType === 'cod' ? '💵 เงินสด COD' : (o.paymentType === 'bank_transfer' ? '🏦 โอน SCB' : '📱 พร้อมเพย์');

                        return `
                        <tr class="hover:bg-slate-50/70 transition-colors">
                            <td class="p-2.5">
                                <div class="font-mono font-black text-slate-900 text-xs">${escapeHtml(o.orderId)}</div>
                                <div class="text-[10px] text-slate-400">${timeStr} น.</div>
                            </td>
                            <td class="p-2.5">
                                <div class="font-bold text-slate-800">${escapeHtml(o.customerName) || "ลูกค้าทั่วไป"}</div>
                                <div class="text-[10px] text-slate-500 font-mono">${escapeHtml(o.customerPhone) || "-"}</div>
                            </td>
                            <td class="p-2.5">
                                <div class="font-bold text-slate-700">${payChannelLabel}</div>
                                <div class="mt-0.5">
                                    ${o.paymentType === 'cod' ? `
                                        <span class="text-[9.5px] text-slate-500 font-medium">รอเก็บเงินสด</span>
                                    ` : isPaymentVerified ? `
                                        <span class="inline-flex items-center gap-0.5 text-[9.5px] bg-emerald-100 text-emerald-800 font-extrabold px-1.5 py-0.2 rounded-full">
                                            <span class="material-symbols-outlined text-[10px]">verified</span>
                                            <span>เงินเข้าแล้ว</span>
                                        </span>
                                    ` : `
                                        <button onclick="openOrderSlipVerificationModal(${jsArg(o.orderId)})" class="inline-flex items-center gap-0.5 text-[9.5px] bg-amber-100 hover:bg-amber-200 text-amber-900 font-extrabold px-1.5 py-0.2 rounded-full border border-amber-300 animate-pulse cursor-pointer">
                                            <span class="material-symbols-outlined text-[10px]">hourglass_top</span>
                                            <span>รอยืนยันเงิน</span>
                                        </button>
                                    `}
                                </div>
                            </td>
                            <td class="p-2.5 text-right">
                                <div class="font-black text-xs ${o.payAmountExact ? 'text-amber-800' : 'text-emerald-700'}">฿${exactAmtDisplay}</div>
                                ${o.payAmountExact ? '<div class="text-[8.5px] font-bold text-amber-600">(เศษสตางค์)</div>' : `<div class="text-[9px] text-slate-400">(ค่าส่ง ฿${o.deliveryFee || 20})</div>`}
                            </td>
                            <td class="p-2.5">
                                <div class="font-bold text-sky-700">${escapeHtml(o.riderName) || "ยังไม่ได้ assign"}</div>
                            </td>
                            <td class="p-2.5 text-center">
                                <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${cfg.color}">
                                    ${cfg.icon} ${escapeHtml(cfg.label)}
                                </span>
                            </td>
                            <td class="p-2.5 text-center">
                                <div class="flex items-center justify-center gap-1.5 flex-wrap">
                                    ${o.paymentType !== 'cod' ? `
                                        <button onclick="openOrderSlipVerificationModal(${jsArg(o.orderId)})" class="px-2 py-1.5 ${isPaymentVerified ? 'bg-emerald-50 hover:bg-emerald-100 text-emerald-800 border border-emerald-300' : 'bg-gradient-to-r from-amber-500 to-orange-500 text-white font-black animate-pulse'} font-bold rounded-xl text-[10px] active:scale-95 transition-all shadow-2xs flex items-center gap-1 cursor-pointer" title="ตรวจสอบสลิปและยืนยันยอดเงิน">
                                            <span class="material-symbols-outlined text-xs">${isPaymentVerified ? 'check_circle' : 'receipt_long'}</span>
                                            <span>${isPaymentVerified ? 'ดูสลิป' : 'ตรวจสลิป'}</span>
                                        </button>
                                    ` : ''}
                                    <button onclick="printThermalOrderSlip(${jsArg(o.orderId)}, ${jsArg(targetDateKey)})" class="px-2 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-800 border border-slate-300 font-bold rounded-xl text-[10px] active:scale-95 transition-all shadow-2xs flex items-center gap-1 cursor-pointer" title="พิมพ์ใบเสร็จ/ใบส่งของเครื่องพิมพ์ความร้อน 80x80">
                                        <span class="material-symbols-outlined text-xs">print</span>
                                        <span>สลิป</span>
                                    </button>
                                    <button onclick="openOrderLineNoticeModal(${jsArg(o.orderId)})" class="px-2 py-1.5 bg-[#06C755]/15 hover:bg-[#06C755]/25 text-[#04883b] border border-[#06C755]/40 font-bold rounded-xl text-[10px] active:scale-95 transition-all shadow-2xs flex items-center gap-1 cursor-pointer" title="ส่งข้อมูลสรุปออเดอร์ให้ลูกค้าทาง LINE">
                                        <span class="text-xs">💬</span>
                                        <span>LINE</span>
                                    </button>
                                    <button onclick="deleteSingleOrder(${jsArg(o.orderId)}, ${jsArg(targetDateKey)})" class="px-2 py-1.5 bg-rose-50 hover:bg-rose-100 text-rose-700 border border-rose-200 font-bold rounded-xl text-[10px] active:scale-95 transition-all shadow-2xs flex items-center gap-1 cursor-pointer" title="ลบออเดอร์นี้ออกจากระบบ (ต้องใช้รหัสผ่าน Admin)">
                                        <span class="material-symbols-outlined text-xs">delete</span>
                                        <span>ลบ</span>
                                    </button>
                                </div>
                            </td>
                        </tr>`;
                    }).join("")}
                </tbody>
            </table>
        </div>`}
        <!-- ปุ่มพิมพ์สมุดบัญชีออเดอร์กระดาษ A4 ตรงกลางด้านล่างหมวด 4 -->
        <div class="pt-3 border-t border-slate-100 flex justify-center">
            <button onclick="printA4OrdersAuditLedger(${jsArg(targetDateKey)})" class="px-4 py-2 bg-gradient-to-r from-slate-700 to-slate-900 hover:from-slate-800 hover:to-black text-white font-extrabold rounded-xl text-xs shadow-sm active:scale-95 transition-all flex items-center gap-2 cursor-pointer">
                <span class="material-symbols-outlined text-sm">print</span>
                <span>📄 พิมพ์สมุดบัญชีออเดอร์ประจำวันทั้งหมด (กระดาษ A4)</span>
            </button>
        </div>
    </div>
    `;

    container.innerHTML = html;
}

// ── Standard EMVCo PromptPay Payload Generator (Bank of Thailand Specification)
function generatePromptPayPayload(target, amount) {
    const cleanTarget = String(target || "").replace(/[^0-9]/g, "");
    let targetSubtag = "";
    
    if (cleanTarget.length >= 9 && cleanTarget.length <= 10) {
        let phoneFormatted = cleanTarget;
        if (phoneFormatted.startsWith("0")) {
            phoneFormatted = "0066" + phoneFormatted.substring(1);
        } else if (!phoneFormatted.startsWith("0066")) {
            phoneFormatted = "0066" + phoneFormatted;
        }
        targetSubtag = "0113" + phoneFormatted;
    } else if (cleanTarget.length === 13) {
        targetSubtag = "0213" + cleanTarget;
    } else {
        targetSubtag = "01130066" + cleanTarget.padStart(9, "0");
    }

    const aid = "0016A000000677010111";
    const tag29Value = aid + targetSubtag;
    const tag29Length = String(tag29Value.length).padStart(2, "0");
    const tag29 = "29" + tag29Length + tag29Value;

    const tag00 = "000201";
    const isDynamic = amount && Number(amount) > 0;
    const tag01 = isDynamic ? "010212" : "010211";
    const tag53 = "5303764"; // Currency: THB (764)
    const tag58 = "5802TH";   // Country: TH

    let tag54 = "";
    if (isDynamic) {
        const amtStr = Number(amount).toFixed(2);
        tag54 = "54" + String(amtStr.length).padStart(2, "0") + amtStr;
    }

    // CRC-16/CCITT-FALSE (Polynomial 0x1021, Init 0xFFFF)
    // Standard Tag Order: 00 -> 01 -> 29 -> 53 -> 54 -> 58 -> 63
    const raw = tag00 + tag01 + tag29 + tag53 + tag54 + tag58 + "6304";
    let crc = 0xFFFF;
    for (let i = 0; i < raw.length; i++) {
        crc ^= (raw.charCodeAt(i) << 8);
        for (let j = 0; j < 8; j++) {
            if ((crc & 0x8000) !== 0) {
                crc = ((crc << 1) ^ 0x1021) & 0xFFFF;
            } else {
                crc = (crc << 1) & 0xFFFF;
            }
        }
    }
    const crcHex = crc.toString(16).toUpperCase().padStart(4, "0");
    return raw + crcHex;
}
window.generatePromptPayPayload = generatePromptPayPayload;

// ── Vendor Payout Slip State & Controllers
let _currentPayoutSlipBase64 = null;
let _currentPayoutSlipNote = "";
let _activeSlipViewerData = null;

function handleVendorPayoutSlipSelected(event) {
    const file = event.target.files && event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = function(e) {
        const rawBase64 = e.target.result;
        const img = new Image();
        img.onload = function() {
            try {
                const canvas = document.createElement("canvas");
                const maxW = 800;
                let w = img.width;
                let h = img.height;
                if (w > maxW) {
                    h = Math.round((h * maxW) / w);
                    w = maxW;
                }
                canvas.width = w;
                canvas.height = h;
                const ctx = canvas.getContext("2d");
                ctx.drawImage(img, 0, 0, w, h);
                _currentPayoutSlipBase64 = canvas.toDataURL("image/jpeg", 0.80);
            } catch(err) {
                _currentPayoutSlipBase64 = rawBase64;
            }

            const slipPlaceholder = document.getElementById("payout-slip-upload-placeholder");
            const slipPreviewBox = document.getElementById("payout-slip-preview-box");
            const slipPreviewImg = document.getElementById("payout-slip-preview-img");
            const slipInfoText = document.getElementById("payout-slip-info-text");

            if (slipPreviewImg) slipPreviewImg.src = _currentPayoutSlipBase64;
            if (slipInfoText) slipInfoText.textContent = `${file.name} (${Math.round(file.size / 1024)} KB)`;
            if (slipPreviewBox) slipPreviewBox.classList.remove("hidden");
            if (slipPlaceholder) slipPlaceholder.classList.add("hidden");

            showToast("✅ แนบรูปสลิปเรียบร้อยแล้ว");
        };
        img.onerror = function() {
            _currentPayoutSlipBase64 = rawBase64;
            const slipPlaceholder = document.getElementById("payout-slip-upload-placeholder");
            const slipPreviewBox = document.getElementById("payout-slip-preview-box");
            const slipPreviewImg = document.getElementById("payout-slip-preview-img");
            if (slipPreviewImg) slipPreviewImg.src = _currentPayoutSlipBase64;
            if (slipPreviewBox) slipPreviewBox.classList.remove("hidden");
            if (slipPlaceholder) slipPlaceholder.classList.add("hidden");
            showToast("✅ แนบรูปสลิปเรียบร้อยแล้ว");
        };
        img.src = rawBase64;
    };
    reader.readAsDataURL(file);
}
window.handleVendorPayoutSlipSelected = handleVendorPayoutSlipSelected;

function removeVendorPayoutSlip() {
    _currentPayoutSlipBase64 = null;
    const slipFileInput = document.getElementById("payout-slip-file-input");
    const slipPlaceholder = document.getElementById("payout-slip-upload-placeholder");
    const slipPreviewBox = document.getElementById("payout-slip-preview-box");
    const slipPreviewImg = document.getElementById("payout-slip-preview-img");

    if (slipFileInput) slipFileInput.value = "";
    if (slipPreviewImg) slipPreviewImg.src = "";
    if (slipPreviewBox) slipPreviewBox.classList.add("hidden");
    if (slipPlaceholder) slipPlaceholder.classList.remove("hidden");
    showToast("🗑️ ลบรูปสลิปออกแล้ว");
}
window.removeVendorPayoutSlip = removeVendorPayoutSlip;

