function setRiderStatus(riderId, newStatus) {
    const riders = loadCommunityRiders();
    const r = riders.find(x => x.id === riderId);
    if (!r) return;
    r.status = newStatus;
    
    // Simulate slight movement if status becomes on_delivery
    if (newStatus === "on_delivery") {
        r.lat = Number((r.lat + (Math.random() - 0.5) * 0.003).toFixed(4));
        r.lng = Number((r.lng + (Math.random() - 0.5) * 0.003).toFixed(4));
    }

    saveCommunityRiders(riders);
    const statusLabels = { available: "🟢 พร้อมรับงาน", on_delivery: "🟡 กำลังส่งของ", offline: "🔴 พักรอบ" };
    showToast(`🛵 เปลี่ยนสถานะ ${r.name} เป็น ${statusLabels[newStatus] || newStatus} สำเร็จ`);
    renderAdminRiders();
    setTimeout(() => initAdminRiderRadarMap(), 150);
}

function toggleRainSurcharge() {
    const s = loadRiderFleetSettings();
    s.rainSurcharge = !s.rainSurcharge;
    saveRiderFleetSettings(s);
    if (s.rainSurcharge) {
        showToast(`🌧️ เปิดโหมดสภาพอากาศแย่ (+฿${s.rainSurchargeAmount} / เที่ยว) แล้ว!`);
    } else {
        showToast(`☀️ ปิดโหมดสภาพอากาศแย่ กลับสู่ค่ารอบปกติ`);
    }
    renderAdminRiders();
}

function saveFleetSettingsFromUI(e) {
    if (e && e.preventDefault) e.preventDefault();
    const s = loadRiderFleetSettings();
    s.baseFee = Number(document.getElementById("fleet-cfg-base-fee")?.value || 40);
    s.rainSurchargeAmount = Number(document.getElementById("fleet-cfg-rain-bonus")?.value || 15);
    s.dailyBonusTrips = Number(document.getElementById("fleet-cfg-target-trips")?.value || 10);
    s.dailyBonusAmount = Number(document.getElementById("fleet-cfg-bonus-amount")?.value || 100);
    s.maxCodLimit = Number(document.getElementById("fleet-cfg-max-cod")?.value || 2500);
    saveRiderFleetSettings(s);
    showToast("💾 บันทึกการตั้งค่าค่ารอบและเกณฑ์ COD สำเร็จ!");
    renderAdminRiders();
}

function settleRiderCod(riderId) {
    const riders = loadCommunityRiders();
    const r = riders.find(x => x.id === riderId);
    if (!r) return;

    const targetDateKey = _activeReportDateKey || getReportDateKey(Date.now());
    const report = aggregateDailyOperations(targetDateKey);
    const reportRiders = (report && report.riderSettlement && report.riderSettlement.riders) || [];
    const rep = reportRiders.find(x => x.riderName === r.name || x.riderPhone === r.phone);
    const codCollected = rep ? (rep.codCollected || 0) : 0;
    const inHandCod = Math.max(0, codCollected - (Number(r.codSettledToday) || 0));

    if (inHandCod <= 0) {
        showToast(`ℹ️ ${r.name} ไม่มียอดเงินสด COD ค้างส่งในขณะนี้`);
        return;
    }

    if (confirm(`ยืนยันการรับมอบเงินสด COD จำนวน ฿${inHandCod.toLocaleString()} จาก ${r.name} เข้าสู่ฮับกลาง?`)) {
        // 1. Update rider fleet state
        r.codSettledToday = (Number(r.codSettledToday) || 0) + inHandCod;
        saveCommunityRiders(riders);

        // 2. Sync settlement status back to Daily Report state (single source of truth)
        const settledRiders = _loadRiderSettlementState(targetDateKey);
        settledRiders[r.name] = {
            isSettled: true,
            settledAt: Date.now(),
            amount: inHandCod,
            riderId: r.id
        };
        _saveRiderSettlementState(targetDateKey, settledRiders);

        showToast(`✅ เคลียร์ยอดเงินสด COD ฿${inHandCod.toLocaleString()} ของ ${r.name} เรียบร้อยแล้ว!`);
        renderAdminRiders();
    }
}

function printThermalRiderSlipFromFleet(riderId) {
    const riders = loadCommunityRiders();
    const r = riders.find(x => x.id === riderId);
    if (!r) return;

    const targetDateKey = _activeReportDateKey || getReportDateKey(Date.now());
    const report = aggregateDailyOperations(targetDateKey);
    const rep = (report && report.riderSettlement && report.riderSettlement.riders)
        ? report.riderSettlement.riders.find(x => x.riderName === r.name || x.riderPhone === r.phone)
        : null;

    if (rep) {
        printThermalRiderSlip(r.name, targetDateKey);
    } else {
        // Fallback slip even if 0 orders
        const thaiDate = formatThaiDateDisplay(targetDateKey);
        const printTime = new Date().toLocaleTimeString("th-TH", { hour: "2-digit", minute: "2-digit" });
        const content = `
            <div class="slip-brand">
                <div class="market-name">🏪 ตลาดสดฮับวิศิษฐ์ชัย</div>
                <div class="market-sub">WISIT CHAI FRESH HUB MARKET</div>
                <div class="doc-badge">[ ใบสรุปสถานะไรเดอร์ ]</div>
            </div>
            <div class="divider-dashed"></div>
            <div class="slip-row"><span class="slip-label">วันที่:</span><span class="slip-value">${thaiDate}</span></div>
            <div class="slip-row"><span class="slip-label">เวลาพิมพ์:</span><span class="slip-value">${printTime} น.</span></div>
            <div class="slip-row"><span class="slip-label">ไรเดอร์:</span><span class="slip-value">${escapeHtml(r.name)}</span></div>
            <div class="slip-row"><span class="slip-label">เบอร์โทร:</span><span class="slip-value">${escapeHtml(r.phone)}</span></div>
            <div class="slip-row"><span class="slip-label">ทะเบียน:</span><span class="slip-value">${escapeHtml(r.plate) || '-'}</span></div>
            <div class="slip-row"><span class="slip-label">สถานะ:</span><span class="slip-value">${r.status === 'available' ? '🟢 พร้อมรับงาน' : r.status === 'on_delivery' ? '🟡 กำลังส่งของ' : '🔴 พักรอบ'}</span></div>
            <div class="divider-dashed"></div>
            <div class="slip-row"><span class="slip-label">จำนวนเที่ยวส่งวันนี้:</span><span class="slip-value">0 เที่ยว</span></div>
            <div class="slip-row"><span class="slip-label">ค่ารอบสะสม:</span><span class="slip-value">฿0</span></div>
            <div class="slip-row"><span class="slip-label">เงินสด COD ในมือ:</span><span class="slip-value">฿0</span></div>
            <div class="divider-dashed"></div>
            <div class="slip-footer">
                <div>ตลาดสดฮับวิศิษฐ์ชัย • เอกสารสรุปสถานะประจำวัน</div>
            </div>
        `;
        executePrintHtml(`สลิปไรเดอร์_${r.name}_${targetDateKey}`, content, true);
    }
}

// ── Rider CRUD Modal Functions
function openAddRiderModal() {
    const modal = document.getElementById("rider-form-modal");
    if (!modal) return;
    document.getElementById("rider-form-modal-title").textContent = "เพิ่มไรเดอร์ใหม่เข้าสู่ระบบ";
    document.getElementById("rider-form-id").value = "";
    document.getElementById("rider-form-name").value = "";
    document.getElementById("rider-form-phone").value = "";
    document.getElementById("rider-form-plate").value = "";
    const modelEl = document.getElementById("rider-form-model");
    if (modelEl) modelEl.value = "";
    document.getElementById("rider-form-zone").value = "ตำบลบ้านหนองชาก / อำเภอบ้านบึง";
    const ppEl = document.getElementById("rider-form-promptpay");
    if (ppEl) ppEl.value = "";
    const bankEl = document.getElementById("rider-form-bank");
    if (bankEl) bankEl.value = "กสิกรไทย";
    document.getElementById("rider-form-status").value = "available";
    document.getElementById("rider-form-basefee").value = "40";
    modal.style.zIndex = "9999";
    modal.classList.remove("hidden");
}

function openEditRiderModal(riderId) {
    const riders = loadCommunityRiders();
    const r = riders.find(x => x.id === riderId);
    if (!r) return;

    const modal = document.getElementById("rider-form-modal");
    if (!modal) return;
    document.getElementById("rider-form-modal-title").textContent = `แก้ไขข้อมูล: ${r.name}`;
    document.getElementById("rider-form-id").value = r.id;
    document.getElementById("rider-form-name").value = r.name || "";
    document.getElementById("rider-form-phone").value = r.phone || "";
    document.getElementById("rider-form-plate").value = r.plate || "";
    const modelEl = document.getElementById("rider-form-model");
    if (modelEl) modelEl.value = r.motorcycleModel || "";
    document.getElementById("rider-form-zone").value = r.zone || "";
    const ppEl = document.getElementById("rider-form-promptpay");
    if (ppEl) ppEl.value = r.promptPay || "";
    const bankEl = document.getElementById("rider-form-bank");
    if (bankEl) bankEl.value = r.bank || "กสิกรไทย";
    document.getElementById("rider-form-status").value = r.status || "available";
    document.getElementById("rider-form-basefee").value = r.baseFee || 40;
    modal.style.zIndex = "9999";
    modal.classList.remove("hidden");
}

function closeRiderFormModal() {
    const modal = document.getElementById("rider-form-modal");
    if (modal) modal.classList.add("hidden");
}

function handleRiderFormSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const id = document.getElementById("rider-form-id")?.value;
    const name = document.getElementById("rider-form-name")?.value.trim();
    const phone = document.getElementById("rider-form-phone")?.value.trim();
    const plate = document.getElementById("rider-form-plate")?.value.trim();
    const motorcycleModel = document.getElementById("rider-form-model")?.value.trim() || "";
    const zone = document.getElementById("rider-form-zone")?.value.trim();
    const promptPay = document.getElementById("rider-form-promptpay")?.value.trim() || "";
    const bank = document.getElementById("rider-form-bank")?.value || "กสิกรไทย";
    const status = document.getElementById("rider-form-status")?.value || "available";
    const baseFee = Number(document.getElementById("rider-form-basefee")?.value || 40);

    if (!name || !phone || !plate) {
        showToast("⚠️ กรุณากรอกข้อมูลชื่อ เบอร์โทร และทะเบียนรถให้ครบถ้วน");
        return;
    }

    const riders = loadCommunityRiders();
    if (id) {
        // Edit
        const r = riders.find(x => x.id === id);
        if (r) {
            const oldPhone = r.phone;
            const oldName = r.name;
            r.name = name;
            r.phone = phone;
            r.plate = plate;
            r.motorcycleModel = motorcycleModel;
            r.zone = zone;
            r.promptPay = promptPay;
            r.bank = bank;
            r.status = status;
            r.baseFee = baseFee;

            // Sync with application if exists
            const apps = loadRiderApplications();
            const matchedApp = apps.find(a => a.phone === oldPhone || a.phone === phone || (a.fullName && (oldName.includes(a.fullName) || name.includes(a.fullName))));
            if (matchedApp) {
                matchedApp.fullName = name;
                matchedApp.phone = phone;
                matchedApp.plate = plate;
                matchedApp.motorcycleModel = motorcycleModel;
                matchedApp.promptPayNumber = promptPay;
                matchedApp.promptPayBank = bank;
                matchedApp.zone = zone;
                saveRiderApplications(apps);
            }
        }
        showToast(`💾 บันทึกการแก้ไขข้อมูล ${name} เรียบร้อยแล้ว`);
    } else {
        // New
        const newRider = {
            id: `RIDER-${Date.now().toString().slice(-4)}`,
            name,
            phone,
            plate,
            motorcycleModel,
            zone,
            promptPay,
            bank,
            status,
            baseFee,
            lat: Number((MARKET_ORIGIN.lat + (Math.random() - 0.5) * 0.01).toFixed(4)),
            lng: Number((MARKET_ORIGIN.lng + (Math.random() - 0.5) * 0.01).toFixed(4)),
            avatar: "🛵",
            rating: 5.0,
            tripsCountToday: 0,
            codSettledToday: 0
        };
        riders.push(newRider);
        showToast(`🎉 เพิ่มไรเดอร์ใหม่ ${name} เข้าสู่ระบบแล้ว!`);
    }

    saveCommunityRiders(riders);
    closeRiderFormModal();
    renderAdminRiders();
    setTimeout(() => initAdminRiderRadarMap(), 150);
}

function deleteCommunityRider(riderId) {
    const riders = loadCommunityRiders();
    const r = riders.find(x => x.id === riderId);
    if (!r) return;

    if (confirm(`คุณต้องการลบไรเดอร์ "${r.name}" ออกจากระบบใช่หรือไม่?`)) {
        const updated = riders.filter(x => x.id !== riderId);
        saveCommunityRiders(updated);
        removeRiderDocuments(riderId);

        // Also clean up or remove matching application if any
        try {
            const cleanPhone = (r.phone || "").replace(/[-\s]/g, "");
            const apps = loadRiderApplications();
            const updatedApps = apps.filter(a => {
                const aPhone = (a.phone || "").replace(/[-\s]/g, "");
                const matchPhone = cleanPhone && aPhone === cleanPhone;
                const matchName = a.fullName && r.name && (r.name.includes(a.fullName) || a.fullName.includes(r.name));
                const matchId = (a.id === riderId) || (a.accessCode && r.accessCode && a.accessCode === r.accessCode);
                return !matchPhone && !matchName && !matchId;
            });
            if (updatedApps.length !== apps.length) {
                saveRiderApplications(updatedApps);
            }
        } catch (e) {
            console.warn("Sync delete application failed:", e);
        }

        // Clean up logged in session if matching
        try {
            if (state.activeRider && (state.activeRider.id === riderId || state.activeRider.riderId === riderId || (state.activeRider.phone && r.phone && state.activeRider.phone.replace(/[-\s]/g, '') === r.phone.replace(/[-\s]/g, '')))) {
                logoutRider();
            }
            const saved = localStorage.getItem("talathub_logged_in_rider");
            if (saved) {
                const parsed = JSON.parse(saved);
                if (parsed && (parsed.id === riderId || parsed.riderId === riderId || (parsed.phone && r.phone && parsed.phone.replace(/[-\s]/g, '') === r.phone.replace(/[-\s]/g, '')))) {
                    localStorage.removeItem("talathub_logged_in_rider");
                }
            }
        } catch (e) {}

        showToast(`🗑️ ลบไรเดอร์ ${r.name} ออกจากระบบเรียบร้อย`);
        updateAdminRiderBadges();
        renderAdminRiders();
        renderAuthHeaderButtons();
        updateRiderRoleButtonUI();
        setTimeout(() => initAdminRiderRadarMap(), 150);
    }
}

// ── Live Radar GPS Leaflet Map
function initAdminRiderRadarMap() {
    const mapContainer = document.getElementById("admin-rider-radar-map");
    if (!mapContainer || typeof L === "undefined") return;

    try {
        if (_adminRiderRadarMap) {
            _adminRiderRadarMap.remove();
            _adminRiderRadarMap = null;
        }

        const centerLat = MARKET_ORIGIN.lat || 13.2982;
        const centerLng = MARKET_ORIGIN.lng || 101.1712;

        _adminRiderRadarMap = L.map("admin-rider-radar-map", {
            zoomControl: true,
            attributionControl: false
        }).setView([centerLat, centerLng], 14);

        L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png", {
            maxZoom: 19
        }).addTo(_adminRiderRadarMap);

        // 1. Hub Center Marker
        const hubIcon = L.divIcon({
            className: "custom-hub-marker",
            html: `
                <div style="background: #581c87; color: #fff; width: 34px; height: 34px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 16px; border: 3px solid #fff; box-shadow: 0 4px 10px rgba(0,0,0,0.35);">
                    🏛️
                </div>
            `,
            iconSize: [34, 34],
            iconAnchor: [17, 17],
            popupAnchor: [0, -18]
        });

        L.marker([centerLat, centerLng], { icon: hubIcon })
            .addTo(_adminRiderRadarMap)
            .bindPopup(`
                <div style="font-family: 'Prompt', sans-serif; font-size: 12px; line-height: 1.4;">
                    <div style="font-weight: 800; color: #581c87;">🏛️ ศูนย์กลางตลาดสดวิศิษฐ์ชัย (Hub)</div>
                    <div style="color: #64748b; font-size: 11px;">จุดรับของ & กระจายสินค้าหลัก</div>
                </div>
            `);

        // 2. Rider Markers
        const riders = loadCommunityRiders();
        const targetDateKey = _activeReportDateKey || getReportDateKey(Date.now());
        const report = aggregateDailyOperations(targetDateKey);
        const reportRiders = (report && report.riderSettlement && report.riderSettlement.riders) || [];

        riders.forEach(r => {
            const rep = reportRiders.find(x => x.riderName === r.name || x.riderPhone === r.phone);
            const inHandCod = rep ? Math.max(0, (rep.codCollected || 0) - (Number(r.codSettledToday) || 0)) : 0;
            const rLat = r.lat || centerLat;
            const rLng = r.lng || centerLng;

            let bgColor = "#10b981"; // available (green)
            let statusText = "🟢 พร้อมรับงาน";
            if (r.status === "on_delivery") {
                bgColor = "#f59e0b"; // on delivery (amber)
                statusText = "🟡 กำลังส่งของ";
            } else if (r.status === "offline") {
                bgColor = "#64748b"; // offline (grey)
                statusText = "🔴 พักรอบ";
            }

            const riderIcon = L.divIcon({
                className: "custom-rider-marker",
                html: `
                    <div style="background: ${bgColor}; color: #fff; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 15px; border: 2.5px solid #fff; box-shadow: 0 3px 8px rgba(0,0,0,0.3); position: relative;">
                        ${escapeHtml(r.avatar) || '🛵'}
                        ${r.status === 'on_delivery' ? '<span style="position: absolute; top:-2px; right:-2px; width: 9px; height: 9px; background: #ef4444; border-radius: 50%; border: 1.5px solid #fff;"></span>' : ''}
                    </div>
                `,
                iconSize: [32, 32],
                iconAnchor: [16, 16],
                popupAnchor: [0, -16]
            });

            const marker = L.marker([rLat, rLng], { icon: riderIcon }).addTo(_adminRiderRadarMap);
            marker.bindPopup(`
                <div style="font-family: 'Prompt', sans-serif; font-size: 11px; line-height: 1.5; min-width: 160px;">
                    <div style="font-weight: 800; font-size: 12px; color: #0f172a;">${escapeHtml(r.avatar) || '🛵'} ${escapeHtml(r.name)}</div>
                    <div style="color: #64748b; font-family: monospace;">ทะเบียน: ${escapeHtml(r.plate) || '-'} ${r.motorcycleModel ? `• ${r.motorcycleModel}` : ''}</div>
                    <div style="font-weight: bold; margin-top: 2px;">สถานะ: ${statusText}</div>
                    <div style="color: #b45309; font-weight: bold;">เงินสด COD: ฿${inHandCod.toLocaleString()}</div>
                    <div style="margin-top: 6px;">
                        <a href="tel:${escapeHtml(r.phone)}" style="background: #059669; color: white; padding: 3px 8px; border-radius: 6px; font-weight: bold; text-decoration: none; display: inline-block; font-size: 10px;">
                            📞 โทร ${escapeHtml(r.phone)}
                        </a>
                    </div>
                </div>
            `);

            // If delivering, draw polyline from Hub -> Rider -> Destination
            if (r.status === "on_delivery") {
                const destLat = Number((rLat + 0.003).toFixed(4));
                const destLng = Number((rLng + 0.003).toFixed(4));
                
                L.polyline([[centerLat, centerLng], [rLat, rLng], [destLat, destLng]], {
                    color: '#f59e0b',
                    weight: 3,
                    dashArray: '5, 8',
                    opacity: 0.85
                }).addTo(_adminRiderRadarMap);

                const destIcon = L.divIcon({
                    className: "custom-dest-marker",
                    html: `
                        <div style="background: #ef4444; color: #fff; width: 26px; height: 26px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 13px; border: 2px solid #fff; box-shadow: 0 2px 6px rgba(0,0,0,0.35);">
                            🏠
                        </div>
                    `,
                    iconSize: [26, 26],
                    iconAnchor: [13, 13],
                    popupAnchor: [0, -13]
                });

                L.marker([destLat, destLng], { icon: destIcon })
                    .addTo(_adminRiderRadarMap)
                    .bindPopup(`
                        <div style="font-family: 'Prompt', sans-serif; font-size: 11px;">
                            <b style="color: #b91c1c;">🏠 ปลายทางส่งของสด</b><br>
                            ไรเดอร์: ${escapeHtml(r.name)}<br>
                            <span style="color: #64748b;">กำลังเดินทางจัดส่ง</span>
                        </div>
                    `);
            }
        });

        setTimeout(() => {
            if (_adminRiderRadarMap) _adminRiderRadarMap.invalidateSize();
        }, 200);
    } catch (e) {
        console.error("Error initializing rider radar map:", e);
    }
}

// ── Application Detail Modal Functions
function viewRiderAppDetail(appId) {
    const apps = loadRiderApplications();
    const cleanId = String(appId || "").trim();
    let app = null;
    if (cleanId) {
        app = apps.find(x => x.id === cleanId) || 
              apps.find(x => (x.phone || "").replace(/[-\s]/g, "") === cleanId.replace(/[-\s]/g, "")) ||
              apps.find(x => x.fullName && x.fullName.includes(cleanId));
    }
    if (!app && _lastSubmittedRiderApp) {
        app = apps.find(x => x.id === _lastSubmittedRiderApp.id) || _lastSubmittedRiderApp;
    }
    if (!app && apps.length > 0) {
        app = apps[0];
    }
    if (!app) {
        showToast("⚠️ ไม่พบข้อมูลใบสมัคร (" + (appId || "ไม่มีรหัส") + ")");
        return;
    }

    // ใบสมัครที่เพิ่งเข้ามา: ดึงข้อมูลส่วนตัวของคนนี้จากที่เก็บลับ แล้ววาดหน้ารายละเอียดใหม่ถ้าได้ข้อมูล
    ensureRiderPrivate(app.id).then(found => {
        if (found) viewRiderAppDetail(app.id);
    });

    const modal = document.getElementById("rider-app-detail-modal");
    if (!modal) {
        console.error("rider-app-detail-modal not found in DOM");
        showToast("⚠️ ไม่พบหน้าต่างแสดงรายละเอียดใบสมัคร");
        return;
    }

    const subEl = document.getElementById("app-detail-sub");
    if (subEl) subEl.textContent = `${app.id} • ยื่นเมื่อ ${formatRiderAppDate(app.appliedAt)}`;
    
    const body = document.getElementById("app-detail-body");
    const footer = document.getElementById("app-detail-footer");

    let statusBadge = `<span class="bg-amber-100 text-amber-900 border border-amber-300 font-extrabold px-2.5 py-0.5 rounded-full text-xs">⏳ รอการตรวจสอบ & อนุมัติ</span>`;
    if (app.status === "approved") {
        statusBadge = `<span class="bg-emerald-100 text-emerald-900 border border-emerald-300 font-extrabold px-2.5 py-0.5 rounded-full text-xs">✓ อนุมัติแล้ว</span>`;
    } else if (app.status === "rejected") {
        statusBadge = `<span class="bg-rose-100 text-rose-900 border border-rose-300 font-extrabold px-2.5 py-0.5 rounded-full text-xs">✕ ปฏิเสธการรับเข้า</span>`;
    }

    if (body) {
        body.innerHTML = `
            <div class="flex items-center justify-between bg-slate-50 p-3 rounded-2xl border border-slate-100">
                <div class="flex items-center gap-3">
                    <div class="w-12 h-12 rounded-2xl bg-gradient-to-br from-purple-500 to-indigo-600 text-white flex items-center justify-center font-bold text-2xl shadow-xs">
                        🛵
                    </div>
                    <div>
                        <h4 class="font-black text-base text-slate-900">${escapeHtml(app.fullName)} ${app.nickname ? `(${escapeHtml(app.nickname)})` : ''}</h4>
                        <div class="text-slate-500 font-mono text-[11px]">${escapeHtml(app.phone)} • LINE: ${escapeHtml(app.lineId || '-')}</div>
                    </div>
                </div>
                <div>${statusBadge}</div>
            </div>

            ${app.status === 'approved' ? `
            <div class="bg-gradient-to-r from-emerald-50 via-teal-50 to-emerald-50 border-2 border-emerald-300 p-3.5 rounded-2xl space-y-2 shadow-xs">
                <div class="flex items-center justify-between">
                    <div class="flex items-center gap-2.5">
                        <span class="w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center font-bold text-base shadow-xs">🔑</span>
                        <div>
                            <div class="text-[10px] font-black text-emerald-800 uppercase tracking-wider">เลขไรเดอร์ (ใช้คู่กับรหัสผ่านเข้าระบบ)</div>
                            <div class="text-xl font-black text-emerald-950 font-mono tracking-widest">${escapeHtml(app.accessCode) || '-'}</div>
                            <div class="text-[10px] text-emerald-800 pt-0.5">${app.loginHash ? '🔒 ตั้งรหัสผ่านแล้ว (ระบบเก็บเฉพาะค่าเข้ารหัส ดูรหัสเดิมไม่ได้)' : '⚠️ ยังไม่มีรหัสผ่านเข้าระบบ — กดสร้างรหัสใหม่'}</div>
                        </div>
                    </div>
                    <span class="text-[10px] bg-emerald-100 text-emerald-800 font-bold px-2 py-0.5 rounded-md">พร้อมใช้งาน</span>
                </div>
                <div class="grid grid-cols-2 sm:grid-cols-4 gap-1.5 pt-1 border-t border-emerald-200/60">
                    <button type="button" onclick="resetRiderLoginSecret(${jsArg(app.id)})" class="col-span-2 py-2 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-xl text-xs flex items-center justify-center gap-1 shadow-xs active:scale-95 transition-all cursor-pointer" title="สร้างรหัสผ่านเข้าระบบใหม่ แล้วส่งต่อทาง SMS / LINE จากกล่องที่ขึ้นมา">
                        <span class="material-symbols-outlined text-sm">key</span>
                        <span>สร้างรหัสผ่านใหม่ & ส่งให้ไรเดอร์</span>
                    </button>
                    <a href="tel:${escapeHtml(app.phone)}" class="py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl text-xs flex items-center justify-center gap-1 active:scale-95 transition-all cursor-pointer" title="โทรหาผู้สมัคร">
                        <span class="material-symbols-outlined text-sm">call</span>
                        <span>โทรหา</span>
                    </a>
                </div>
            </div>
            ` : ''}

            <div class="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                <div class="bg-slate-50 p-3 rounded-xl border border-slate-100 space-y-1">
                    <div class="text-[10px] font-bold text-slate-400">ข้อมูลส่วนตัว & ใบอนุญาต</div>
                    <div class="font-bold text-slate-800">เลข ปชช: <span class="font-mono text-slate-700">${escapeHtml(app.idCard || '-')}</span></div>
                    <div class="font-bold text-slate-800">ใบขับขี่: <span class="font-mono text-purple-700">${escapeHtml(app.drivingLicense || '-')}</span></div>
                    <div class="text-[11px] text-slate-600 mt-1">ที่อยู่: ${escapeHtml(app.address || '-')}</div>
                </div>

                <div class="bg-slate-50 p-3 rounded-xl border border-slate-100 space-y-1">
                    <div class="text-[10px] font-bold text-slate-400">ยานพาหนะ & โซนวิ่ง</div>
                    <div class="font-bold text-slate-800">รถ: ${escapeHtml(app.motorcycleModel || '-')} ${app.motorcycleColor ? `(${escapeHtml(app.motorcycleColor)})` : ''}</div>
                    <div class="font-bold text-slate-800 font-mono">ทะเบียน: ${escapeHtml(app.plate || '-')}</div>
                    <div class="text-[11px] text-slate-600 mt-1">โซนวิ่ง: ${escapeHtml(app.zone || 'รอบตลาดวิศิษฐ์ชัย')}</div>
                </div>
            </div>

            <div class="bg-slate-50 p-3 rounded-xl border border-slate-100 space-y-2">
                <div class="text-[10px] font-bold text-slate-400">ช่วงเวลาที่สะดวก & อุปกรณ์</div>
                <div class="flex flex-wrap gap-1.5">
                    ${(app.shifts || []).map(s => `<span class="px-2 py-0.5 bg-sky-100 text-sky-800 rounded-lg font-bold text-[11px]">⏰ ${escapeHtml(s)}</span>`).join('')}
                </div>
                <div class="flex flex-wrap gap-1.5 pt-1">
                    ${(app.equipments || []).map(eq => `<span class="px-2 py-0.5 bg-emerald-100 text-emerald-800 rounded-lg font-bold text-[11px]">✓ ${escapeHtml(eq)}</span>`).join('')}
                </div>
            </div>

            <div class="bg-emerald-50/70 border border-emerald-200 p-3 rounded-xl flex items-center justify-between">
                <div>
                    <div class="text-[10px] font-bold text-emerald-800">พร้อมเพย์ที่ใช้โอนค่ารอบ</div>
                    <div class="font-black text-sm text-emerald-950 font-mono">${escapeHtml(app.promptPayNumber || app.phone)}</div>
                    <div class="text-[10px] text-emerald-700">ธนาคาร: ${escapeHtml(app.promptPayBank || 'พร้อมเพย์')}</div>
                </div>
                <span class="material-symbols-outlined text-2xl text-emerald-600">account_balance</span>
            </div>

            ${renderRiderAppExtrasHtml(app)}
        `;
        hydrateRiderAppDocs(app);
    }

    if (footer) {
        footer.innerHTML = `
            <div class="flex items-center gap-1.5 flex-wrap">
                <button type="button" onclick="openEditRiderAppModal(${jsArg(app.id)}); closeRiderAppDetailModal();" class="px-3 py-2 bg-purple-50 hover:bg-purple-100 text-purple-700 border border-purple-200 font-bold rounded-xl text-xs flex items-center gap-1 active:scale-95 transition-all cursor-pointer" title="แก้ไขข้อมูลใบสมัครนี้">
                    <span class="material-symbols-outlined text-sm">edit</span>
                    <span>แก้ไขข้อมูล</span>
                </button>
                ${app.status === 'rejected' ? `
                    <button type="button" onclick="reconsiderRiderApplication(${jsArg(app.id)})" class="px-2.5 py-1.5 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-xl text-xs active:scale-95 transition-all flex items-center gap-1 cursor-pointer">
                        <span class="material-symbols-outlined text-sm">replay</span>
                        <span>พิจารณาใหม่</span>
                    </button>
                ` : app.status === 'approved' ? `
                    <button type="button" onclick="reconsiderRiderApplication(${jsArg(app.id)})" class="px-2.5 py-1.5 bg-amber-50 hover:bg-amber-100 text-amber-800 border border-amber-300 font-bold rounded-xl text-xs active:scale-95 transition-all flex items-center gap-1 cursor-pointer">
                        <span class="material-symbols-outlined text-sm">replay</span>
                        <span>ย้อนกลับไปรอพิจารณา</span>
                    </button>
                ` : ''}
                <button type="button" onclick="deleteRiderApplication(${jsArg(app.id)})" class="p-2 text-rose-500 hover:bg-rose-50 rounded-xl transition-all cursor-pointer" title="ลบใบสมัครนี้">
                    <span class="material-symbols-outlined text-base">delete</span>
                </button>
            </div>

            <div class="flex items-center gap-1.5 flex-wrap">
                ${app.status === 'pending' ? `
                    <button type="button" onclick="rejectRiderApplication(${jsArg(app.id)})" class="px-3 py-2 bg-slate-100 hover:bg-rose-50 text-slate-700 hover:text-rose-700 font-bold rounded-xl text-xs active:scale-95 transition-all cursor-pointer">
                        ปฏิเสธ
                    </button>
                    <button type="button" onclick="approveRiderApplication(${jsArg(app.id)})" class="px-3.5 py-2 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-700 hover:to-teal-700 text-white font-black rounded-xl text-xs shadow-md active:scale-95 transition-all flex items-center gap-1 cursor-pointer" title="อนุมัติเป็นไรเดอร์ในระบบและสร้างรหัสผ่าน 6 หลัก">
                        <span class="material-symbols-outlined text-sm font-bold">check_circle</span>
                        <span>อนุมัติเป็นไรเดอร์</span>
                    </button>
                    <button type="button" onclick="approveAndLoginRider(${jsArg(app.id)})" class="px-3.5 py-2 bg-gradient-to-r from-sky-500 via-blue-600 to-indigo-600 hover:from-sky-600 hover:to-indigo-700 text-white font-black rounded-xl text-xs shadow-md active:scale-95 transition-all flex items-center gap-1 cursor-pointer" title="อนุมัติและสลับเข้าสู่ระบบรับงานทันที">
                        <span class="material-symbols-outlined text-sm font-bold">sports_motorsports</span>
                        <span>อนุมัติ & รับงานทันที 🚀</span>
                    </button>
                ` : `
                    <button type="button" onclick="approveAndLoginRider(${jsArg(app.id)})" class="px-3.5 py-2 bg-gradient-to-r from-sky-500 via-blue-600 to-indigo-600 hover:from-sky-600 hover:to-indigo-700 text-white font-black rounded-xl text-xs shadow-md active:scale-95 transition-all flex items-center gap-1 cursor-pointer" title="สลับเข้าระบบรับงานเป็นไรเดอร์คนนี้ทันที">
                        <span class="material-symbols-outlined text-sm font-bold">sports_motorsports</span>
                        <span>เข้าสู่ระบบรับงานทันที 🚀</span>
                    </button>
                    <button type="button" onclick="resetRiderLoginSecret(${jsArg(app.id)})" class="px-3.5 py-2 bg-emerald-50 hover:bg-emerald-100 text-emerald-800 border border-emerald-300 font-bold rounded-xl text-xs active:scale-95 transition-all flex items-center gap-1 cursor-pointer" title="สร้างรหัสผ่านเข้าระบบใหม่ให้ไรเดอร์คนนี้">
                        <span class="material-symbols-outlined text-sm">key</span>
                        <span>สร้างรหัสเข้าระบบใหม่</span>
                    </button>
                    <button type="button" onclick="closeRiderAppDetailModal()" class="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl text-xs active:scale-95 transition-all cursor-pointer">
                        ปิดหน้าต่าง
                    </button>
                `}
            </div>
        `;
    }

    modal.style.zIndex = "9999";
    modal.classList.remove("hidden");
}
function closeRiderAppDetailModal() {
    const modal = document.getElementById("rider-app-detail-modal");
    if (modal) modal.classList.add("hidden");
}

// ── Rider Application Edit Modal Handlers
function openEditRiderAppModal(appId) {
    const apps = loadRiderApplications();
    const app = apps.find(x => x.id === appId);
    if (!app) {
        showToast("⚠️ ไม่พบข้อมูลใบสมัคร (" + (appId || "") + ")");
        return;
    }

    const modal = document.getElementById("rider-app-edit-modal");
    if (!modal) return;

    document.getElementById("app-edit-id").value = app.id || "";
    document.getElementById("app-edit-modal-sub").textContent = app.id || "";
    document.getElementById("app-edit-modal-title").textContent = `แก้ไขใบสมัคร: ${app.fullName || ''}`;
    document.getElementById("app-edit-fullname").value = app.fullName || "";
    document.getElementById("app-edit-nickname").value = app.nickname || "";
    document.getElementById("app-edit-phone").value = app.phone || "";
    document.getElementById("app-edit-lineid").value = app.lineId || "";
    document.getElementById("app-edit-idcard").value = app.idCard || "";
    document.getElementById("app-edit-drivinglicense").value = app.drivingLicense || "";
    document.getElementById("app-edit-model").value = app.motorcycleModel || "";
    document.getElementById("app-edit-color").value = app.motorcycleColor || "";
    document.getElementById("app-edit-plate").value = app.plate || "";
    document.getElementById("app-edit-promptpay").value = app.promptPayNumber || "";
    document.getElementById("app-edit-bank").value = app.promptPayBank || "กสิกรไทย";
    document.getElementById("app-edit-zone").value = app.zone || "";
    document.getElementById("app-edit-address").value = app.address || "";
    document.getElementById("app-edit-status").value = app.status || "pending";
    document.getElementById("app-edit-notes").value = app.notes || "";

    modal.style.zIndex = "9999";
    modal.classList.remove("hidden");
}

function closeRiderAppEditModal() {
    const modal = document.getElementById("rider-app-edit-modal");
    if (modal) modal.classList.add("hidden");
}

function handleRiderAppEditSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();

    const id = document.getElementById("app-edit-id")?.value;
    const fullName = document.getElementById("app-edit-fullname")?.value.trim();
    const nickname = document.getElementById("app-edit-nickname")?.value.trim();
    const phone = document.getElementById("app-edit-phone")?.value.trim();
    const lineId = document.getElementById("app-edit-lineid")?.value.trim() || "";
    const idCard = document.getElementById("app-edit-idcard")?.value.trim() || "";
    const drivingLicense = document.getElementById("app-edit-drivinglicense")?.value.trim() || "";
    const motorcycleModel = document.getElementById("app-edit-model")?.value.trim() || "";
    const motorcycleColor = document.getElementById("app-edit-color")?.value.trim() || "";
    const plate = document.getElementById("app-edit-plate")?.value.trim();
    const promptPayNumber = document.getElementById("app-edit-promptpay")?.value.trim() || "";
    const promptPayBank = document.getElementById("app-edit-bank")?.value || "กสิกรไทย";
    const zone = document.getElementById("app-edit-zone")?.value.trim() || "";
    const address = document.getElementById("app-edit-address")?.value.trim() || "";
    const status = document.getElementById("app-edit-status")?.value || "pending";
    const notes = document.getElementById("app-edit-notes")?.value.trim() || "";

    if (!fullName || !phone || !plate) {
        showToast("⚠️ กรุณากรอกชื่อ-นามสกุล เบอร์โทรศัพท์ และทะเบียนรถให้ครบถ้วน");
        return;
    }

    const apps = loadRiderApplications();
    const app = apps.find(x => x.id === id);
    if (!app) {
        showToast("⚠️ ไม่พบใบสมัครที่ต้องการแก้ไข");
        return;
    }

    const oldPhone = app.phone;
    const oldName = app.fullName;

    app.fullName = fullName;
    app.nickname = nickname;
    app.phone = phone;
    app.lineId = lineId;
    app.idCard = idCard;
    app.drivingLicense = drivingLicense;
    app.motorcycleModel = motorcycleModel;
    app.motorcycleColor = motorcycleColor;
    app.plate = plate;
    app.promptPayNumber = promptPayNumber;
    app.promptPayBank = promptPayBank;
    app.zone = zone;
    app.address = address;
    app.status = status;
    app.notes = notes;
    app.updatedAt = new Date().toISOString();

    saveRiderApplications(apps);

    // Also synchronize community riders according to status
    const riders = loadCommunityRiders();
    const cleanOldPhone = (oldPhone || "").replace(/[-\s]/g, "");
    const cleanNewPhone = (phone || "").replace(/[-\s]/g, "");
    const matchedRiderIndex = riders.findIndex(r => {
        const rPhone = (r.phone || "").replace(/[-\s]/g, "");
        return (cleanOldPhone && rPhone === cleanOldPhone) || (cleanNewPhone && rPhone === cleanNewPhone) || (r.name && (r.name.includes(oldName) || r.name.includes(fullName)));
    });

    const displayName = `${fullName} ${nickname ? `(${nickname})` : ''}`.trim();

    if (status === "approved") {
        if (matchedRiderIndex >= 0) {
            riders[matchedRiderIndex].name = displayName;
            riders[matchedRiderIndex].phone = phone;
            riders[matchedRiderIndex].plate = plate;
            riders[matchedRiderIndex].motorcycleModel = motorcycleModel;
            riders[matchedRiderIndex].promptPay = promptPayNumber || phone;
            riders[matchedRiderIndex].bank = promptPayBank;
            riders[matchedRiderIndex].zone = zone;
            saveCommunityRiders(riders);
        } else {
            const newRider = {
                id: `RIDER-${Date.now().toString().slice(-4)}`,
                name: displayName,
                phone: phone,
                plate: plate,
                zone: zone || "รอบตลาดวิศิษฐ์ชัย",
                status: "available",
                baseFee: 40,
                lat: Number((MARKET_ORIGIN.lat + (Math.random() - 0.5) * 0.01).toFixed(4)),
                lng: Number((MARKET_ORIGIN.lng + (Math.random() - 0.5) * 0.01).toFixed(4)),
                avatar: "🛵",
                motorcycleModel: motorcycleModel,
                promptPay: promptPayNumber || phone,
                bank: promptPayBank,
                rating: 5.0,
                tripsCountToday: 0,
                codSettledToday: 0
            };
            riders.unshift(newRider);
            saveCommunityRiders(riders);
        }
    } else {
        // If status is pending or rejected, remove from active fleet riders so it does NOT appear in active roster!
        if (matchedRiderIndex >= 0) {
            riders.splice(matchedRiderIndex, 1);
            saveCommunityRiders(riders);
        }
    }

    closeRiderAppEditModal();
    showToast(`💾 บันทึกการแก้ไขข้อมูลใบสมัคร ${fullName} เรียบร้อยแล้ว!`);
    updateAdminRiderBadges();
    renderAdminRiders();
    setTimeout(() => initAdminRiderRadarMap(), 150);
}

function deleteRiderApplication(appId) {
    if (!requireOwnerAction()) return;
    if (confirm("⚠️ คุณแน่ใจหรือไม่ว่าต้องการลบประวัติใบสมัครนี้ออกจากระบบ?")) {
        const apps = loadRiderApplications();
        const appToDelete = apps.find(x => x.id === appId);
        const updated = apps.filter(x => x.id !== appId);
        saveRiderApplications(updated);
        removeRiderDocuments(appId);

        // Also remove from active community riders if matching
        if (appToDelete) {
            const cleanPhone = (appToDelete.phone || "").replace(/[-\s]/g, "");
            const riders = loadCommunityRiders();
            const updatedRiders = riders.filter(r => {
                const rPhone = (r.phone || "").replace(/[-\s]/g, "");
                const matchPhone = cleanPhone && rPhone === cleanPhone;
                const matchName = appToDelete.fullName && r.name && (r.name.includes(appToDelete.fullName) || appToDelete.fullName.includes(r.name));
                return !matchPhone && !matchName;
            });
            if (updatedRiders.length !== riders.length) {
                saveCommunityRiders(updatedRiders);
            }

            // Also clean up logged in rider if it was this applicant
            try {
                const saved = localStorage.getItem("talathub_logged_in_rider");
                if (saved) {
                    const parsed = JSON.parse(saved);
                    if (parsed && (parsed.phone && cleanPhone && parsed.phone.replace(/[-\s]/g, '') === cleanPhone)) {
                        localStorage.removeItem("talathub_logged_in_rider");
                    }
                }
            } catch (e) {}
        }

        closeRiderAppDetailModal();
        closeRiderAppEditModal();
        showToast("🗑️ ลบใบสมัครและข้อมูลไรเดอร์เรียบร้อยแล้ว");
        updateAdminRiderBadges();
        renderAdminRiders();
        setTimeout(() => initAdminRiderRadarMap(), 150);
    }
}

function reconsiderRiderApplication(appId) {
    if (!requireOwnerAction()) return;
    const apps = loadRiderApplications();
    const app = apps.find(x => x.id === appId);
    if (!app) return;
    const wasApproved = app.status === "approved";
    if (wasApproved && !confirm(`"${app.fullName}" เป็นไรเดอร์ที่อนุมัติแล้ว\nถ้าย้อนกลับไปรอพิจารณา จะถูกถอนสิทธิ์และรับงานไม่ได้จนกว่าจะอนุมัติใหม่\n\nยืนยันใช่หรือไม่?`)) return;
    app.status = "pending";
    saveRiderApplications(apps);
    if (wasApproved) revokeRiderAccessForApplication(app);
    closeRiderAppDetailModal();
    showToast(`🔄 นำใบสมัครของ ${app.fullName} กลับมาพิจารณาใหม่แล้ว`);
    renderAdminRiders();
}

function filterAdminRiderApps(filter) {
    _adminRiderAppFilter = filter;
    renderAdminRiders();
}

