// Out-of-Stock Toggle Handler (ขั้นตอนที่ 2: ฮับกดแจ้งของหมด)
function toggleHubItemOutOfStock(stallIndex, itemIndex) {
    if (!state.activeOrder || !state.activeOrder.stalls[stallIndex]) return;
    const stall = state.activeOrder.stalls[stallIndex];
    const item = stall.items[itemIndex];
    if (!item) return;

    item.outOfStock = !item.outOfStock;
    const price = item.actualPrice !== undefined ? item.actualPrice : item.price;

    if (item.outOfStock) {
        item.picked = false;
        showToast(`⚠️ ปรับ "${item.name}" เป็นสินค้าหมด (คำนวณเงินสดทอน ฿${price} ใส่ซองแนบถุง)`);
    } else {
        showToast(`✓ กู้คืนรายการ "${item.name}" กลับเข้ารายการจัดเตรียมแล้ว`);
    }

    // Recalculate stall picked count based on non-out-of-stock items
    stall.pickedCount = stall.items.filter(i => i.picked && !i.outOfStock).length;

    // Recalculate order refund totals
    let refundCashTotal = 0;
    state.activeOrder.stalls.forEach(s => {
        (s.items || []).forEach(it => {
            if (it.outOfStock) {
                const pr = it.actualPrice !== undefined ? it.actualPrice : it.price;
                refundCashTotal += pr;
            }
        });
    });
    state.activeOrder.refundCashTotal = refundCashTotal;
    state.activeOrder.finalPaidTotal = Math.max(0, (state.activeOrder.grandTotal || state.activeOrder.total || 0) - refundCashTotal);

    saveActiveOrderToStorage(state.activeOrder);
    renderHubPickingList();
    renderTrackingScreen();
    renderHubSettlement();
}

function contactExpressStall(stallId, orderId) {
    const info = (typeof findStallInfo === "function") ? findStallInfo(stallId) : null;
    const phone = (info && info.phone) ? info.phone : "081-444-5555";
    const name = (info && info.stallName) ? info.stallName : "แผงค้าในตลาด";
    showToast(`📞 เตรียมติดต่อ ${name} (${phone}) สำหรับออเดอร์ด่วน ${orderId}`);
    if (confirm(`โทรหาหน้าร้าน "${name}" (${phone}) เพื่อแจ้งเตือนให้เตรียมของด่วนหรือไม่?`)) {
        window.location.href = `tel:${phone}`;
    }
}
window.contactExpressStall = contactExpressStall;

// Send Out-of-Stock Notice via LINE
function sendOutOfStockLineNotice() {
    const order = state.activeOrder;
    if (!order) return;
    const oosList = [];
    if (order.stalls) {
        order.stalls.forEach(s => {
            (s.items || []).forEach(i => {
                if (i.outOfStock) oosList.push(`${i.name} (฿${i.actualPrice !== undefined ? i.actualPrice : i.price})`);
            });
        });
    }
    const refund = order.refundCashTotal || 0;
    const cleanOrderId = (order.orderId || "").replace(/#/g, '');
    const trackUrl = `https://pisaen666.github.io/hsong/?track=${encodeURIComponent(cleanOrderId)}`;
    const msg = `🔔【เฮียส่ง】แจ้งเตือนเรื่องสินค้าออเดอร์ ${order.orderId}:\nขออภัยครับ มีสินค้าที่แผงค้าหมด ได้แก่:\n${oosList.map(n => `• ${n}`).join('\n')}\n━━━━━━━━━━━━━━━━━━\n✉️ คืนเงินสดใส่ซอง: ฿${refund}\nทีมงานตัดรายการออก และไรเดอร์ได้นำเงินสดทอนจำนวน ฿${refund} ใส่ซองใสแนบไปกับถุงของสดเรียบร้อยแล้วครับ 🛵💨\n━━━━━━━━━━━━━━━━━━\n👉 แตะลิงก์นี้เพื่อดูสถานะจัดส่ง & ซองเงินทอนของคุณ:\n${trackUrl}`;

    if (isMobileDevice()) {
        window.location.href = `https://line.me/R/msg/text/?${encodeURIComponent(msg)}`;
    } else {
        showLinePcModal(`แจ้งเงินทอนสินค้าหมด (ออเดอร์ ${order.orderId})`, msg);
    }
}

function toggleHubPickedItem(stallIndex, itemIndex) {
    if (!state.activeOrder || !state.activeOrder.stalls[stallIndex]) return;
    const stall = state.activeOrder.stalls[stallIndex];
    const item = stall.items[itemIndex];
    if (item) {
        item.picked = !item.picked;
        stall.pickedCount = stall.items.filter(i => i.picked).length;
        saveActiveOrderToStorage(state.activeOrder);
        renderHubPickingList();
        renderTrackingScreen();
    }
}

function updateHubItemWeight(stallIndex, itemIndex) {
    if (!state.activeOrder || !state.activeOrder.stalls[stallIndex]) return;
    const input = document.getElementById(`actual-weight-${stallIndex}-${itemIndex}`);
    if (input) {
        const val = parseFloat(input.value) || 0;
        state.activeOrder.stalls[stallIndex].items[itemIndex].actualPrice = val;
        showToast(`✓ บันทึกราคาน้ำหนักจริง ฿${val} เรียบร้อยแล้ว`);
        renderHubPickingList();
        renderHubSettlement();
    }
}

function completePickingAndDispatchOrder(orderId) {
    if (!state.activeOrder) return;

    // 🛡️ Safeguard: ล็อคการปล่อยงานหากยังไม่ได้ตรวจสอบยอดเงินโอน
    if (state.activeOrder.paymentVerified === false && state.activeOrder.paymentType !== "cod") {
        showToast("⚠️ ไม่สามารถปล่อยงานได้: กรุณาตรวจและกดยืนยันยอดเงินโอนเข้าบัญชีก่อน");
        openOrderSlipVerificationModal(orderId);
        return;
    }

    state.activeOrder.status = "delivering";
    if (state.activeOrder.stalls) {
        state.activeOrder.stalls.forEach(s => {
            s.pickedCount = s.itemsCount;
            if (s.items) s.items.forEach(i => i.picked = true);
        });
    }

    // Auto populate rider job
    if (!state.activeRider || !state.activeRider.isLoggedIn) {
        const availRiders = loadCommunityRiders();
        if (availRiders && availRiders.length > 0) {
            state.activeRider = {
                isLoggedIn: true,
                riderId: availRiders[0].id,
                name: availRiders[0].name,
                phone: availRiders[0].phone,
                license: availRiders[0].plate
            };
            saveRiderToStorage(state.activeRider);
        }
    }

    // ✅ ซิงค์สถานะใหม่ไปยัง Firebase & localStorage
    saveActiveOrderToStorage(state.activeOrder);

    // Open Success Next Step Modal
    const modal = document.getElementById("dispatch-success-modal");
    if (modal) {
        const order = state.activeOrder;
        const setVal = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
        if (order) {
            setVal("dispatch-modal-order-id", order.orderId || "#TH-XXXX");
            setVal("dispatch-modal-customer", `${order.customerName || 'ลูกค้าทั่วไป'} (${order.customerPhone || '-'})`);
            setVal("dispatch-modal-rider", order.riderName || (state.activeRider ? state.activeRider.name : "ไรเดอร์ประจำตลาด"));
        }
        modal.classList.remove("hidden");
    }

    showToast("🛵 รวมถุงเรียบร้อย! ปล่อยไรเดอร์ออกเดินทางส่งของสดแล้ว");
    renderHubPickingList();
    renderTrackingScreen();
    renderRiderScreen();
}

function closeDispatchSuccessModal() {
    const modal = document.getElementById("dispatch-success-modal");
    if (modal) modal.classList.add("hidden");

    // ✅ หลังปิด modal → สลับไป Tab "ติดตามออเดอร์" ทันที
    // เพื่อให้ฮับเห็นสถานะออเดอร์ที่เพิ่ง dispatch และ monitor ไรเดอร์ได้
    switchHubTab("monitor");
    showToast("📊 ตรวจสอบสถานะออเดอร์ได้ที่แท็บ 'ติดตามออเดอร์'");
}

// ── ปุ่ม 1: ไปหน้าจอไรเดอร์รับงาน ───────────────────────────────────────────
function goToRiderTrackingScreen() {
    closeDispatchSuccessModal();

    // 1) Auto-login rider ถ้ามีไรเดอร์ในระบบ
    if (!state.activeRider || !state.activeRider.isLoggedIn) {
        const availRiders = loadCommunityRiders();
        if (availRiders && availRiders.length > 0) {
            state.activeRider = {
                isLoggedIn: true,
                riderId: availRiders[0].id,
                name: availRiders[0].name,
                phone: availRiders[0].phone,
                license: availRiders[0].plate
            };
            saveRiderToStorage(state.activeRider);
        }
    }

    // 2) อัปเดต order status → "dispatched" (ฮับส่งมอบให้ไรเดอร์แล้ว)
    if (state.activeOrder) {
        state.activeOrder.status = "dispatched";
        state.activeOrder.dispatchedAt = Date.now();
        if (state.activeRider && state.activeRider.isLoggedIn) {
            state.activeOrder.riderName  = state.activeRider.name;
            state.activeOrder.riderPhone = state.activeRider.phone;
        }

        // คำนวณเงินทอนที่ไรเดอร์ต้องคืนลูกค้า (กรณีสินค้าขาด)
        let refundTotal = 0;
        if (state.activeOrder.stalls) {
            state.activeOrder.stalls.forEach(s => {
                (s.items || []).forEach(it => {
                    if (it.outOfStock) {
                        refundTotal += (it.actualPrice !== undefined ? it.actualPrice : it.price);
                    }
                });
            });
        }
        state.activeOrder.refundCashTotal = refundTotal;

        if (!state.activeOrder.paymentDesc) {
            state.activeOrder.paymentDesc = state.activeOrder.paymentType === "cash" ? "เงินสด" : "ชำระแล้ว";
        }

        saveActiveOrderToStorage(state.activeOrder);
    }

    // 3) สลับมุมมองเป็น Rider และ render หน้างาน
    setActiveRoleView("rider");
    renderRiderScreen();
    renderAuthHeaderButtons();

    showToast("🛵 สลับมาหน้าจอไรเดอร์แล้ว! ออเดอร์พร้อมรับงานนำส่ง");
}

// ── ปุ่ม 2: ไปหน้าจอติดตามส่งของลูกค้า ─────────────────────────────────────
function goToCustomerLiveTracking() {
    closeDispatchSuccessModal();

    if (state.activeOrder) {
        state.activeOrder.status = "on_the_way";

        if (state.activeRider && state.activeRider.isLoggedIn) {
            state.activeOrder.riderName  = state.activeRider.name;
            state.activeOrder.riderPhone = state.activeRider.phone;
        } else {
            const availRiders = loadCommunityRiders();
            if (availRiders && availRiders.length > 0) {
                state.activeOrder.riderName  = availRiders[0].name;
                state.activeOrder.riderPhone = availRiders[0].phone;
            } else {
                state.activeOrder.riderName  = "ไรเดอร์จัดส่ง";
                state.activeOrder.riderPhone = "-";
            }
        }

        saveActiveOrderToStorage(state.activeOrder);
    }

    // สลับมุมมองเป็น Customer และเปิดหน้า Tracking
    setActiveRoleView("customer");
    goToTrackingScreen();
    if (typeof renderTrackingScreen === "function") renderTrackingScreen();

    showToast("📱 สลับมาหน้าจอลูกค้าแล้ว! ไรเดอร์กำลังนำส่งของสดมาให้คุณ");
}

function createSampleCustomerOrder() {
    showToast("ℹ️ ระบบปิดการสร้างออเดอร์ตัวอย่างแล้ว กรุณาสั่งซื้อผ่านหน้าตลาดสดจริง");
}

function renderHubSettlement() {
    const container = document.getElementById("hub-content-settlement");
    if (!container) return;

    let order = state.activeOrder;
    if (order && isMockOrder(order)) {
        state.activeOrder = null;
        try {
            localStorage.removeItem("talathub_active_order");
            localStorage.removeItem("hsong_active_order");
        } catch(e) {}
        order = null;
    }

    let expressOrders = (state.merchantExpressOrders || []).filter(o => o && o.orderId && !isMockOrder(o));
    if (expressOrders.length === 0) {
        try {
            const rawExp = JSON.parse(localStorage.getItem("hsong_merchant_express_orders") || "[]");
            if (Array.isArray(rawExp)) {
                expressOrders = rawExp.filter(o => o && o.orderId && !isMockOrder(o));
            }
        } catch(e) {}
    }

    const hasGrocery = !!(order && !isMockOrder(order) && order.stalls && order.stalls.length > 0);
    const hasExpress = expressOrders.length > 0;

    if (!hasGrocery && !hasExpress) {
        container.innerHTML = `
            <div class="bg-white rounded-3xl p-8 text-center border border-slate-200 shadow-sm space-y-2">
                <div class="text-3xl">💰</div>
                <h4 class="font-bold text-sm text-slate-700">ยังไม่มีรายการยอดเคลียร์เงิน</h4>
                <p class="text-[11px] text-slate-500">ยอดเงินเคลียร์แผงค้าและค่ารอบไรเดอร์จะคำนวณอัตโนมัติตามสินค้าและงานที่เกิดขึ้นจริง</p>
            </div>
        `;
        return;
    }

    let html = "";

    // 1. สรุปยอดจ่ายแผงค้า (Grocery Orders)
    if (hasGrocery) {
        const hubSettings = (typeof loadSavedHubSettings === "function") ? loadSavedHubSettings() : {};
        const gpRate = (hubSettings && typeof hubSettings.merchantGP === "number" && hubSettings.merchantGP > 0) ? hubSettings.merchantGP : 10;
        let vendorListHtml = "";
        let vendorTotal = 0;
        let vendorPayoutTotal = 0;
        let totalStallGP = 0;

        order.stalls.forEach(stall => {
            const meta = (typeof findStallInfo === "function") ? findStallInfo(stall.stallId, stall.name) : {};
            const activeItems = (stall.items || []).filter(item => !item.outOfStock);
            const oosItems = (stall.items || []).filter(item => item.outOfStock);
            const stallItemsTotal = activeItems.reduce((sum, item) => sum + (item.actualPrice !== undefined ? item.actualPrice : item.price), 0);
            const stallGP = Math.round(stallItemsTotal * (gpRate / 100));
            const stallPayout = Math.max(0, stallItemsTotal - stallGP);
            const stallPhone = meta.phone || "089-123-4567";
            const stallOwner = meta.ownerName || "แม่ค้าประจำแผง";
            const stallNum = meta.stallNumber || "แผงตลาด";
            const stallId = stall.stallId || meta.stallId || stall.name;

            vendorTotal += stallItemsTotal;
            totalStallGP += stallGP;
            vendorPayoutTotal += stallPayout;

            vendorListHtml += `
                <div class="flex justify-between items-center p-3 bg-slate-50 rounded-2xl border border-slate-200/80">
                    <div>
                        <div class="font-bold text-slate-800 text-xs">${escapeHtml(stall.name)}</div>
                        <div class="text-[10px] text-slate-500">
                            ยอดขาย ฿${stallItemsTotal} <span class="text-amber-700 font-bold">(หัก GP ${gpRate}% -฿${stallGP})</span>
                            ${oosItems.length > 0 ? `<span class="text-rose-600 font-bold">(หมด ${oosItems.length})</span>` : ''}
                        </div>
                    </div>
                    <div class="text-right">
                        <div class="font-black text-emerald-700 text-xs">โอนสุทธิ ฿${stallPayout}</div>
                        <button type="button" onclick="openVendorPayoutModal(${jsArg(stallId)}, ${jsArg(stall.name)}, ${stallPayout}, ${jsArg(stallPhone)}, ${jsArg(stallOwner)}, ${jsArg(stallNum)}, ${stallItemsTotal}, ${stallGP}, ${gpRate})" class="text-[10px] bg-emerald-600 hover:bg-emerald-700 active:scale-95 text-white px-2.5 py-1 rounded-lg font-bold mt-1 shadow-xs transition-all cursor-pointer">
                            โอนเคลียร์เงิน (PromptPay)
                        </button>
                    </div>
                </div>
            `;
        });

        const orderGrandTotal = Number(order.grandTotal || order.total || vendorTotal);

        html += `
            <div class="bg-white rounded-3xl p-4 shadow-card border border-slate-200 space-y-3 mb-4 text-left">
                <div class="flex items-center justify-between pb-2 border-b border-slate-100">
                    <h3 class="font-bold text-sm text-slate-800 flex items-center gap-1">
                        <span class="material-symbols-outlined text-emerald-700 text-base">account_balance_wallet</span>
                        <span>สรุปยอดจ่ายแผงค้า (${escapeHtml(order.orderId)})</span>
                    </h3>
                    <div class="text-right">
                        <div class="text-[10px] text-slate-500 font-medium">ยอดขายรวม ฿${vendorTotal}</div>
                        <div class="text-xs text-emerald-700 font-black">โอนสุทธิ ฿${vendorPayoutTotal} (GP รวม ฿${totalStallGP})</div>
                    </div>
                </div>
                <div class="space-y-2">
                    ${vendorListHtml}
                </div>
            </div>

            <div class="bg-gradient-to-r from-emerald-800 to-slate-900 text-white rounded-3xl p-4 shadow-card space-y-2 mb-4 text-left">
                <div class="text-xs text-emerald-300 font-bold">รายรับรวมระบบจัดส่ง (ค่าสินค้า + ค่าบริการรวมบิล + ค่าส่ง)</div>
                <div class="text-2xl font-black">฿${orderGrandTotal} <span class="text-xs font-normal text-slate-300">บาท</span></div>
                <div class="text-[11px] text-slate-300 flex justify-between pt-2 border-t border-slate-700">
                    <span>ยอดโอนร้านค้าสุทธิ: ฿${vendorPayoutTotal}</span>
                    <span>รายรับคงเหลือฮับ (GP+ค่าส่ง): ฿${Math.max(0, orderGrandTotal - vendorPayoutTotal)}</span>
                </div>
            </div>
        `;
    }

    // 2. สรุปยอดเคลียร์งานด่วนแผงค้า (Express Orders Settlement)
    if (hasExpress) {
        let expressRows = "";
        let expressFeeTotal = 0;
        expressOrders.forEach((exp) => {
            const fee = Number(exp.deliveryFee || 20);
            expressFeeTotal += fee;
            const rider = exp.assignedRider || { name: "กำลังจัดสรร", phone: "-" };
            expressRows += `
                <div class="flex justify-between items-center p-3 bg-orange-50/60 rounded-2xl border border-orange-200">
                    <div class="space-y-0.5">
                        <div class="font-extrabold text-slate-900 text-xs flex items-center gap-1.5">
                            <span>⚡ ${escapeHtml(exp.orderId)}</span>
                            <span class="text-[10px] text-orange-800 font-bold bg-orange-100 px-2 py-0.2 rounded-full">${escapeHtml(exp.originStall?.stallName) || 'แผงค้า'}</span>
                        </div>
                        <div class="text-[10px] text-slate-600">
                            🛵 ไรเดอร์: <strong>${escapeHtml(rider.name)}</strong> • ผู้รับ: คุณ${escapeHtml(exp.customerName) || 'ลูกค้า'}
                        </div>
                    </div>
                    <div class="text-right shrink-0">
                        <div class="font-black text-emerald-700 text-xs">฿${fee}</div>
                        <button type="button" onclick="clearHubSettlementVendor('ไรเดอร์: ${rider.name.replace(/'/g, "\\'")} (งาน ${escapeHtml(exp.orderId)})', this)" class="text-[10px] bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-700 hover:to-teal-700 active:scale-95 text-white px-2.5 py-1 rounded-lg font-bold mt-1 shadow-xs transition-all cursor-pointer">
                            โอนให้ไรเดอร์
                        </button>
                    </div>
                </div>
            `;
        });

        html += `
            <div class="bg-white rounded-3xl p-4 shadow-card border border-orange-200 space-y-3 mb-4 text-left">
                <div class="flex items-center justify-between pb-2 border-b border-orange-100">
                    <h3 class="font-bold text-sm text-orange-950 flex items-center gap-1">
                        <span class="material-symbols-outlined text-orange-600 text-base">two_wheeler</span>
                        <span>สรุปยอดเคลียร์ค่ารอบงานด่วน (Express Fleet Settlement)</span>
                    </h3>
                    <span class="text-[11px] text-orange-700 font-bold">รวมค่าส่ง ฿${expressFeeTotal}</span>
                </div>
                <div class="space-y-2">
                    ${expressRows}
                </div>
            </div>
        `;
    }

    // 3. สรุปยอดเงินสด COD ไรเดอร์ค้างส่งมอบฮับ (Rider COD In-Hand Ledger)
    const todayDateKey = getReportDateKey(Date.now());
    const dailyReport = (typeof aggregateDailyOperations === "function") ? aggregateDailyOperations(todayDateKey) : null;
    const activeRidersReport = (dailyReport && dailyReport.riderSettlement && dailyReport.riderSettlement.riders) || [];
    const pendingCodRiders = activeRidersReport.filter(r => r.netCashToHub > 0 && !r.isSettled);

    if (pendingCodRiders.length > 0) {
        let riderCodRows = "";
        let totalPendingCod = 0;
        pendingCodRiders.forEach(r => {
            totalPendingCod += r.netCashToHub;
            const isExceeded = r.netCashToHub >= 3000;
            riderCodRows += `
                <div class="flex justify-between items-center p-3 ${isExceeded ? 'bg-rose-50 border-rose-300' : 'bg-slate-50 border-slate-200'} rounded-2xl border">
                    <div>
                        <div class="font-extrabold text-slate-800 text-xs flex items-center gap-1.5">
                            <span>🛵 ${escapeHtml(r.riderName)}</span>
                            ${isExceeded ? `<span class="bg-rose-600 text-white text-[9px] font-black px-1.5 py-0.2 rounded-md animate-pulse">⚠️ เกินเพดาน ฿3,000</span>` : ''}
                        </div>
                        <div class="text-[10px] text-slate-500 font-mono">
                            เก็บ COD ฿${r.codCollected.toLocaleString()} • ค่ารอบ -฿${r.riderFeeEarned.toLocaleString()}
                        </div>
                    </div>
                    <div class="text-right">
                        <div class="font-black ${isExceeded ? 'text-rose-700' : 'text-emerald-700'} text-xs">฿${r.netCashToHub.toLocaleString()}</div>
                        <button type="button" onclick="settleRiderBalance(${jsArg(r.riderName)}, ${jsArg(todayDateKey)}); renderHubSettlement();" class="text-[10px] bg-emerald-600 hover:bg-emerald-700 active:scale-95 text-white px-2.5 py-1 rounded-lg font-bold mt-1 shadow-xs transition-all cursor-pointer">
                            💵 รับเงินสด
                        </button>
                    </div>
                </div>
            `;
        });

        html += `
            <div class="bg-white rounded-3xl p-4 shadow-card border border-slate-200 space-y-3 text-left">
                <div class="flex items-center justify-between pb-2 border-b border-slate-100">
                    <h3 class="font-bold text-sm text-slate-800 flex items-center gap-1">
                        <span class="material-symbols-outlined text-amber-600 text-base">payments</span>
                        <span>เงินสด COD ไรเดอร์ค้างส่งมอบฮับ</span>
                    </h3>
                    <span class="text-[11px] text-rose-700 font-black">ค้างส่ง ฿${totalPendingCod.toLocaleString()}</span>
                </div>
                <div class="space-y-2">
                    ${riderCodRows}
                </div>
            </div>
        `;
    }

    container.innerHTML = html;
}

function clearHubSettlementVendor(vendorName, btn = null) {
    if (btn) {
        btn.disabled = true;
        btn.className = "text-[10px] bg-slate-200 text-slate-500 px-2.5 py-1 rounded-lg font-bold mt-1 cursor-default";
        btn.textContent = "✓ โอนแล้ว";
    }
    showToast(`✓ โอนเงินผ่าน PromptPay เคลียร์ยอดให้ "${vendorName}" สำเร็จแล้ว!`);
}

// ==========================================
// RIDER GUEST & REGISTRATION PORTAL HANDLERS
// ==========================================

function goToRiderRegisterScreen() {
    setActiveRoleView("rider");
    renderRiderScreen();
    switchRiderGuestTab("register");
    window.scrollTo({ top: 0, behavior: "smooth" });
    showToast("📝 ยินดีต้อนรับสู่หน้าลงทะเบียนสมัครไรเดอร์ตลาดวิศิษฐ์ชัย");
}
window.goToRiderRegisterScreen = goToRiderRegisterScreen;

function switchRiderGuestTab(tabKey) {
    const tabRegister = document.getElementById("rider-guest-tab-register");
    const tabLogin = document.getElementById("rider-guest-tab-login");
    const btnRegister = document.getElementById("rider-guest-tab-btn-register");
    const btnLogin = document.getElementById("rider-guest-tab-btn-login");

    if (tabKey === "register") {
        if (tabRegister) tabRegister.classList.remove("hidden");
        if (tabLogin) tabLogin.classList.add("hidden");
        if (btnRegister) {
            btnRegister.className = "flex-1 sm:flex-none px-4 py-2 rounded-xl font-black text-xs bg-emerald-700 text-white shadow-sm flex items-center justify-center gap-1.5 transition-all cursor-pointer";
        }
        if (btnLogin) {
            btnLogin.className = "flex-1 sm:flex-none px-4 py-2 rounded-xl font-bold text-xs text-slate-600 hover:bg-slate-100 flex items-center justify-center gap-1.5 transition-all cursor-pointer";
        }
    } else {
        if (tabRegister) tabRegister.classList.add("hidden");
        if (tabLogin) tabLogin.classList.remove("hidden");
        if (btnLogin) {
            btnLogin.className = "flex-1 sm:flex-none px-4 py-2 rounded-xl font-black text-xs bg-emerald-700 text-white shadow-sm flex items-center justify-center gap-1.5 transition-all cursor-pointer";
        }
        if (btnRegister) {
            btnRegister.className = "flex-1 sm:flex-none px-4 py-2 rounded-xl font-bold text-xs text-slate-600 hover:bg-slate-100 flex items-center justify-center gap-1.5 transition-all cursor-pointer";
        }
        renderOnPageRidersList();
    }
}
window.switchRiderGuestTab = switchRiderGuestTab;

function renderRiderGuestPortal() {
    const curRiders = loadCommunityRiders();
    const emptyAlert = document.getElementById("rider-guest-empty-alert");
    if (!curRiders || curRiders.length === 0) {
        if (emptyAlert) emptyAlert.classList.remove("hidden");
    } else {
        if (emptyAlert) emptyAlert.classList.add("hidden");
    }
    renderOnPageRidersList();
}
window.renderRiderGuestPortal = renderRiderGuestPortal;

// ── กล่องแจ้งสถานะใบสมัครที่ผู้สมัครเพิ่งส่ง (ค้างบนหน้าล็อกอินจนกว่าจะกดปิด ไม่หายเหมือนข้อความ toast)
const _RIDER_APP_NOTICE_KEY = "talathub_rider_app_notice";

function _escHtml(v) {
    return String(v == null ? "" : v).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

function rememberRiderApplicationNotice(code, name) {
    try { sessionStorage.setItem(_RIDER_APP_NOTICE_KEY, JSON.stringify({ code: String(code), name: name || "" })); } catch (e) { }
}

function dismissRiderApplicationNotice() {
    try { sessionStorage.removeItem(_RIDER_APP_NOTICE_KEY); } catch (e) { }
    renderRiderApplicationNotice();
}
window.dismissRiderApplicationNotice = dismissRiderApplicationNotice;

function renderRiderApplicationNotice() {
    const box = document.getElementById("rider-application-notice");
    if (!box) return;
    let n = null;
    try { n = JSON.parse(sessionStorage.getItem(_RIDER_APP_NOTICE_KEY) || "null"); } catch (e) { }
    if (!n || !n.code) { box.innerHTML = ""; return; }
    const app = loadRiderApplications().find(a => a.id === n.code);
    const status = app ? app.status : "pending";
    const palette = status === "approved"
        ? { bg: "bg-emerald-50", border: "border-emerald-400", text: "text-emerald-900", head: "✅ ใบสมัครได้รับอนุมัติแล้ว", hint: "เข้าสู่ระบบรับงานด้วยเลขนี้ และรหัสผ่านที่เจ้าของส่งให้ (พิมพ์ในช่องด้านล่าง) ถ้ายังไม่ได้รับรหัสผ่าน ให้ติดต่อเจ้าของ" }
        : status === "rejected"
            ? { bg: "bg-rose-50", border: "border-rose-400", text: "text-rose-900", head: "❌ ใบสมัครไม่ผ่านการอนุมัติ", hint: "กรุณาติดต่อเจ้าของตลาดเพื่อสอบถามเหตุผล" }
            : { bg: "bg-amber-50", border: "border-amber-400", text: "text-amber-900", head: "⏳ ส่งใบสมัครแล้ว รอเจ้าของอนุมัติ", hint: "ยังเข้าสู่ระบบรับงานไม่ได้จนกว่าเจ้าของจะอนุมัติ ให้จดเลขนี้ไว้ เมื่ออนุมัติแล้วเจ้าของจะส่ง \"รหัสผ่านเข้าระบบ\" ให้คุณ ใช้คู่กับเลขนี้" };
    box.innerHTML = `
        <div class="p-4 ${palette.bg} border-2 ${palette.border} rounded-2xl space-y-2 text-left ${palette.text}">
            <div class="font-black text-sm">${palette.head}</div>
            ${n.name ? `<div class="text-xs">ผู้สมัคร: <strong>${_escHtml(n.name)}</strong></div>` : ""}
            <div class="text-xs">เลขไรเดอร์ / เลขใบสมัครของคุณ:</div>
            <div class="text-2xl font-black font-mono tracking-widest bg-white/80 rounded-xl px-3 py-2 text-center select-all">${_escHtml(n.code)}</div>
            <p class="text-xs leading-relaxed">${palette.hint}</p>
            <button type="button" onclick="dismissRiderApplicationNotice()" class="text-[11px] font-bold underline cursor-pointer">ปิดข้อความนี้</button>
        </div>`;
}
window.renderRiderApplicationNotice = renderRiderApplicationNotice;

function renderOnPageRidersList() {
    renderRiderApplicationNotice();
    const container = document.getElementById("onpage-registered-riders-list");
    if (!container) return;
    const curRiders = loadCommunityRiders();
    if (!isOwnerSignedIn()) {
        // ผู้ใช้ทั่วไป: ไม่แสดงรายชื่อไรเดอร์และไม่มีปุ่มเข้าสู่ระบบข้างชื่อ (เข้าได้ด้วยเลขไรเดอร์ + รหัสผ่านเท่านั้น)
        container.innerHTML = `
            <div class="p-4 bg-slate-50 rounded-2xl border border-dashed border-slate-300 text-center space-y-2">
                <div class="font-extrabold text-xs text-slate-800">เข้าสู่ระบบด้วยเลขไรเดอร์และรหัสผ่าน</div>
                <p class="text-[11px] text-slate-500 max-w-xs mx-auto">เจ้าของจะส่งรหัสผ่านให้เมื่ออนุมัติใบสมัครของคุณ ถ้ายังไม่เคยสมัคร กดปุ่มด้านล่าง</p>
                <button type="button" onclick="switchRiderGuestTab('register')" class="px-3.5 py-2 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-xl text-xs shadow-xs active:scale-95 transition-all cursor-pointer">
                    📝 ไปหน้าลงทะเบียนสมัครไรเดอร์
                </button>
            </div>
        `;
        return;
    }
    if (!curRiders || curRiders.length === 0) {
        container.innerHTML = `
            <div class="p-4 bg-slate-50 rounded-2xl border border-dashed border-slate-300 text-center space-y-2.5">
                <div class="w-10 h-10 rounded-2xl bg-amber-100 text-amber-800 flex items-center justify-center mx-auto text-xl">⚠️</div>
                <div class="font-extrabold text-xs text-slate-800">ยังไม่มีไรเดอร์ในระบบตลาดวิศิษฐ์ชัย</div>
                <p class="text-[11px] text-slate-500 max-w-xs mx-auto">เนื่องจากยังไม่มีผู้สมัคร หรือเพิ่งล้างข้อมูลระบบ กรุณากดปุ่มด้านล่างเพื่อลงทะเบียนเป็นไรเดอร์คนแรก</p>
                <div class="flex flex-col sm:flex-row items-center justify-center gap-2 pt-1">
                    <button type="button" onclick="switchRiderGuestTab('register')" class="w-full sm:w-auto px-3.5 py-2 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-xl text-xs shadow-xs active:scale-95 transition-all cursor-pointer">
                        📝 ไปหน้าลงทะเบียนสมัครไรเดอร์
                    </button>
                    <button type="button" onclick="quickRegisterAndLoginRider()" class="w-full sm:w-auto px-3.5 py-2 bg-gradient-to-r from-sky-500 to-blue-600 hover:from-sky-600 hover:to-blue-700 text-white font-bold rounded-xl text-xs shadow-xs active:scale-95 transition-all cursor-pointer">
                        🚀 สมัคร & ล็อกอินทันที (1-Click)
                    </button>
                </div>
            </div>
        `;
        return;
    }

    let html = "";
    curRiders.forEach(r => {
        const code = r.accessCode || r.pin || (r.id ? r.id.slice(-6).toUpperCase() : "-");
        html += `
            <div class="p-3 bg-white rounded-2xl border border-slate-200 shadow-xs flex items-center justify-between gap-2 hover:border-emerald-400 hover:shadow-sm transition-all">
                <div class="flex items-center gap-2.5 min-w-0">
                    <div class="w-9 h-9 rounded-xl bg-emerald-100 text-emerald-800 flex items-center justify-center font-bold text-base shrink-0">
                        🛵
                    </div>
                    <div class="min-w-0 text-left">
                        <div class="font-extrabold text-xs text-slate-900 truncate">${escapeHtml(r.name)}</div>
                        <div class="text-[10px] text-slate-500 font-mono">รหัส: <strong class="text-emerald-700 font-bold">${code}</strong> • โทร: ${escapeHtml(r.phone) || '-'} • ทะเบียน: ${escapeHtml(r.plate) || '-'}</div>
                    </div>
                </div>
                <button type="button" onclick="loginRiderById(${jsArg(r.id)})"
                    class="px-3.5 py-1.5 bg-gradient-to-r from-emerald-600 to-teal-700 hover:from-emerald-700 hover:to-teal-800 text-white font-bold text-xs rounded-xl shadow-xs active:scale-95 transition-all shrink-0 cursor-pointer flex items-center gap-1">
                    <span class="material-symbols-outlined text-xs font-bold">login</span>
                    <span>เข้าสู่ระบบ</span>
                </button>
            </div>
        `;
    });
    container.innerHTML = html;
}
window.renderOnPageRidersList = renderOnPageRidersList;

function fillOnPageRiderSampleData() {
    const randomNum = Math.floor(1000 + Math.random() * 9000);
    const randomPhone = "08" + Math.floor(10000000 + Math.random() * 90000000);

    const elName = document.getElementById("onpage-rider-fullname");
    const elNick = document.getElementById("onpage-rider-nickname");
    const elPhone = document.getElementById("onpage-rider-phone");
    const elLine = document.getElementById("onpage-rider-line");
    const elModel = document.getElementById("onpage-rider-model");
    const elPlate = document.getElementById("onpage-rider-plate");
    const elLicense = document.getElementById("onpage-rider-license");

    if (elName) elName.value = "นายสมชาย ว่องไว";
    if (elNick) elNick.value = "สมชาย";
    if (elPhone) elPhone.value = randomPhone;
    if (elLine) elLine.value = "rider.somchai" + randomNum;
    if (elModel) elModel.value = "Honda Wave 110i (สีน้ำเงิน-ดำ)";
    if (elPlate) elPlate.value = `1กข-${randomNum} ชลบุรี`;
    if (elLicense) elLicense.value = String(Math.floor(1000000000000 + Math.random() * 9000000000000));
    fillRiderRegExtrasSample("onpage");

    showToast("⚡ เติมข้อมูลตัวอย่างลงในฟอร์มเรียบร้อยแล้ว! กดปุ่ม 'ยืนยันการลงทะเบียน' ได้เลย");
}
window.fillOnPageRiderSampleData = fillOnPageRiderSampleData;

function quickRegisterAndLoginRider() {
    // ปุ่มทดสอบสร้างไรเดอร์ปลอมพร้อมอนุมัติเอง — ใช้ได้เฉพาะตอนเจ้าของล็อกอิน (กันข้อมูลทดสอบหลุดขึ้นระบบจริง)
    if (!isOwnerSignedIn()) {
        showToast("🔒 ปุ่มทดสอบนี้ใช้ได้เฉพาะเมื่อเจ้าของล็อกอินอยู่ ผู้สมัครจริงกรุณากรอกฟอร์มสมัครแล้วรอเจ้าของอนุมัติ");
        return;
    }
    const code = generate6DigitAccessCode("RD");
    const randomDigits = Math.floor(10000000 + Math.random() * 90000000);
    const phone = "08" + randomDigits;
    const fullName = "สมชาย ว่องไว (ไรเดอร์ทดสอบ)";
    const plate = "1กข-8888 ชลบุรี";
    const zone = "ตลาดวิศิษฐ์ชัย และอำเภอบ้านบึง (ระยะ 5 กม.)";

    const newRider = {
        id: code,
        riderId: code,
        name: fullName,
        phone: phone,
        plate: plate,
        license: plate,
        zone: zone,
        status: "available",
        baseFee: 40,
        avatar: "🛵",
        motorcycleModel: "Honda Wave 110i",
        promptPay: phone,
        accessCode: code,
        codSettledToday: 0
    };

    const curRiders = loadCommunityRiders();
    curRiders.unshift(newRider);
    saveCommunityRiders(curRiders);

    const apps = loadRiderApplications();
    apps.unshift({
        id: code,
        accessCode: code,
        fullName: fullName,
        nickname: "ทดสอบ",
        phone: phone,
        lineId: "rider.test",
        plate: plate,
        zone: zone,
        status: "approved",
        appliedAt: new Date().toISOString(),
        approvedAt: new Date().toISOString(),
        notes: "อนุมัติอัตโนมัติ (1-Click Test)"
    });
    saveRiderApplications(apps);

    closeRiderRegisterModal();
    closeRiderLoginModal();
    loginRiderWithProfile(newRider);
    showToast(`🚀 สมัครและเข้าสู่ระบบสำเร็จ! ยินดีต้อนรับ ${fullName} (รหัส: ${code})`);
}
window.quickRegisterAndLoginRider = quickRegisterAndLoginRider;

async function handleOnPageRiderRegister(e) {
    if (e && e.preventDefault) e.preventDefault();

    const fullName = document.getElementById("onpage-rider-fullname")?.value.trim();
    const nickname = document.getElementById("onpage-rider-nickname")?.value.trim();
    const phone = document.getElementById("onpage-rider-phone")?.value.trim().replace(/[-\s]/g, "");
    const lineId = document.getElementById("onpage-rider-line")?.value.trim();
    const model = document.getElementById("onpage-rider-model")?.value.trim();
    const plate = document.getElementById("onpage-rider-plate")?.value.trim();
    const license = document.getElementById("onpage-rider-license")?.value.trim() || plate || "-";
    const zone = document.getElementById("onpage-rider-zone")?.value || "ตลาดวิศิษฐ์ชัย และอำเภอบ้านบึง (ระยะ 5 กม.)";

    if (!fullName) {
        showToast("⚠️ กรุณากรอกชื่อ - นามสกุลจริงของผู้สมัคร");
        document.getElementById("onpage-rider-fullname")?.focus();
        return;
    }
    if (!nickname) {
        showToast("⚠️ กรุณากรอกชื่อเล่น");
        document.getElementById("onpage-rider-nickname")?.focus();
        return;
    }
    if (!phone || phone.length < 9) {
        showToast("⚠️ กรุณากรอกเบอร์โทรศัพท์มือถือให้ถูกต้อง");
        document.getElementById("onpage-rider-phone")?.focus();
        return;
    }
    if (!lineId) {
        showToast("⚠️ กรุณากรอก LINE ID สำหรับประสานงานด่วน");
        document.getElementById("onpage-rider-line")?.focus();
        return;
    }
    if (!model) {
        showToast("⚠️ กรุณาระบุยี่ห้อ / รุ่นรถมอเตอร์ไซค์");
        document.getElementById("onpage-rider-model")?.focus();
        return;
    }
    if (!plate) {
        showToast("⚠️ กรุณาระบุหมายเลขทะเบียนรถและจังหวัด");
        document.getElementById("onpage-rider-plate")?.focus();
        return;
    }

    // ส่วนเสริม: ยืนยันตัวตน • ผู้ติดต่อฉุกเฉิน • รูปเอกสาร • บัญชีรับเงินหลายบัญชี • การยินยอม
    const extras = collectRiderRegExtras("onpage", { identity: true });
    if (!extras.ok) {
        showToast(extras.message);
        const bad = document.getElementById(extras.focusId);
        if (bad) {
            bad.scrollIntoView({ behavior: "smooth", block: "center" });
            if (bad.focus) bad.focus();
        }
        return;
    }
    // ระบบจ่ายเงินเดิมใช้ PromptPay ID: ถ้าไม่มีบัญชีพร้อมเพย์ ใช้เบอร์มือถือเหมือนเดิม
    const promptPay = extras.promptPayNumber || phone;

    const code = generate6DigitAccessCode("RD");
    const displayName = nickname ? `${fullName} (${nickname})` : fullName;

    // ผู้สมัครทั่วไปส่งใบสมัครซ้ำด้วยเบอร์เดิมไม่ได้ (กันทับใบสมัครที่อนุมัติแล้ว และกันใบสมัครซ้ำ)
    if (!isOwnerSignedIn()) {
        const dup = loadRiderApplications().find(a => (a.phone || "").replace(/[-\s]/g, "") === phone);
        if (dup) {
            showToast(dup.status === "approved"
                ? "⚠️ เบอร์นี้ได้รับอนุมัติเป็นไรเดอร์แล้ว กรุณาเข้าสู่ระบบด้วยรหัสเดิม หรือติดต่อแอดมิน"
                : "⚠️ เบอร์นี้ส่งใบสมัครไว้แล้ว กรุณารอเจ้าของอนุมัติ หรือติดต่อแอดมิน");
            return;
        }
    }

    // รูปเอกสารเก็บแยกจากใบสมัคร (ต้องบันทึกสำเร็จอย่างน้อยหนึ่งที่ก่อนสร้างไรเดอร์)
    const docResult = await saveRiderDocumentsGuarded("onpage", code, extras.docs, {
        idCard: extras.identity.idCard, address: extras.identity.address, drivingLicense: license, license,
        emergencyContact: extras.emergencyContact, bankAccounts: extras.bankAccounts
    });
    if (!docResult) return;
    if (docResult.privateFailed) {
        showToast("⚠️ ส่งข้อมูลส่วนตัวไม่สำเร็จ (อาจเคยสมัครด้วยเบอร์นี้แล้ว หรืออินเทอร์เน็ตมีปัญหา) กรุณาลองใหม่ หรือติดต่อแอดมิน");
        return;
    }
    if (!docResult.cloudOk && !docResult.localOk) {
        showToast("⚠️ บันทึกรูปเอกสารไม่สำเร็จ กรุณาลองอีกครั้ง");
        return;
    }
    if (!docResult.cloudOk) {
        showToast("⚠️ รูปเอกสารถูกเก็บไว้ในเครื่องนี้เท่านั้น (ยังส่งขึ้นระบบกลางไม่ได้) กรุณาตรวจอินเทอร์เน็ต");
    }

    const newRider = {
        id: code,
        riderId: code,
        name: displayName,
        phone: phone,
        plate: plate,
        license: license,
        zone: zone,
        status: "available",
        baseFee: 40,
        avatar: "🛵",
        motorcycleModel: model,
        promptPay: promptPay,
        bankAccounts: extras.bankAccounts,
        accessCode: code,
        codSettledToday: 0
    };

    // สร้างไรเดอร์เข้าระบบทันทีเฉพาะตอนเจ้าของล็อกอินอยู่ — ผู้สมัครทั่วไปรอเจ้าของอนุมัติ
    if (isOwnerSignedIn()) {
        const curRiders = loadCommunityRiders();
        const existingIdx = curRiders.findIndex(r => (r.phone || "").replace(/[-\s]/g, "") === phone);
        if (existingIdx >= 0) curRiders[existingIdx] = newRider;
        else curRiders.unshift(newRider);
        saveCommunityRiders(curRiders);
    }

    const apps = loadRiderApplications();
    apps.unshift({
        id: code,
        accessCode: code,
        fullName: fullName,
        nickname: nickname,
        phone: phone,
        lineId: lineId,
        idCard: extras.identity.idCard,
        address: extras.identity.address,
        motorcycleModel: model,
        motorcycleColor: extras.identity.motorcycleColor,
        plate: plate,
        vehiclePlate: plate,
        drivingLicense: license,
        zone: zone,
        shifts: extras.identity.shifts,
        promptPayNumber: promptPay,
        promptPayBank: extras.promptPayBank,
        bankAccounts: extras.bankAccounts,
        emergencyContact: extras.emergencyContact,
        docFlags: extras.docFlags,
        consentAt: extras.consentAt,
        appliedAt: new Date().toISOString(),
        ..._newRiderAppStatusFields()
    });
    saveRiderApplications(apps);

    document.getElementById("onpage-rider-reg-form")?.reset();
    resetRiderRegExtras("onpage");
    closeRiderRegisterModal();
    closeRiderLoginModal();
    if (!isOwnerSignedIn()) {
        rememberRiderApplicationNotice(code, displayName);
        showToast(`✅ ส่งใบสมัครแล้ว! เลขไรเดอร์ของคุณ: ${code} (จดไว้) — รอเจ้าของอนุมัติ แล้วเจ้าของจะส่งรหัสผ่านเข้าระบบให้`);
        if (typeof switchRiderGuestTab === "function") switchRiderGuestTab("login");
        return;
    }
    loginRiderWithProfile(newRider);
    showToast(`🎉 ลงทะเบียนสำเร็จ! ยินดีต้อนรับ ${displayName} เข้าสู่ระบบรับงานทันที (รหัส PIN: ${code})`);
}
window.handleOnPageRiderRegister = handleOnPageRiderRegister;

function handleOnPageRiderLoginSubmit() {
    return submitRiderSecretLogin("onpage-rider-number-input", "onpage-rider-secret-input");
}
window.handleOnPageRiderLoginSubmit = handleOnPageRiderLoginSubmit;

function renderRiderScreen() {
    const isRiderLoggedIn = !!(state.activeRider && state.activeRider.isLoggedIn);
    const guestView = document.getElementById("rider-guest-view");
    const loggedInView = document.getElementById("rider-logged-in-view");

    if (!isRiderLoggedIn) {
        if (guestView) guestView.classList.remove("hidden");
        if (loggedInView) loggedInView.classList.add("hidden");
        renderRiderGuestPortal();
        return;
    }

    if (guestView) guestView.classList.add("hidden");
    if (loggedInView) loggedInView.classList.remove("hidden");

    let order = state.activeOrder;
    if (order && isMockOrder(order)) {
        state.activeOrder = null;
        try {
            localStorage.removeItem("talathub_active_order");
            localStorage.removeItem("hsong_active_order");
        } catch(e) {}
        order = null;
    }
    const badge = document.getElementById("rider-order-id-badge");
    const totalBadge = document.getElementById("rider-order-total-badge");
    const destName = document.getElementById("rider-dest-name");
    const destDetail = document.getElementById("rider-dest-detail");
    const noteText = document.getElementById("rider-note-text");
    const mapsLink = document.getElementById("rider-maps-link");
    const statusBadge = document.getElementById("rider-current-status-badge");
    const refundAlert = document.getElementById("rider-refund-alert");
    const refundAmount = document.getElementById("rider-refund-alert-amount");
    const btnStart = document.getElementById("btn-rider-start-delivery");
    const btnStartText = document.getElementById("rider-btn-start-text");
    const btnStartIcon = document.getElementById("rider-btn-start-icon");
    const btnComplete = document.getElementById("btn-rider-complete-delivery");
    const btnCompleteText = document.getElementById("rider-btn-complete-text");
    const btnCompleteIcon = document.getElementById("rider-btn-complete-icon");
    const completedBanner = document.getElementById("rider-completed-banner");

    if (!order) {
        if (badge) badge.textContent = "ไม่มีงานค้าง";
        if (totalBadge) totalBadge.textContent = "฿0";
        if (destName) destName.textContent = "รอรับออเดอร์ใหม่จากฮับ";
        if (destDetail) {
            destDetail.innerHTML = `<div class="text-slate-400">ขณะนี้ไม่มีคิวจัดส่งที่มอบหมายให้คุณ • สแตนด์บายรอรับงานจากตลาดสด</div>`;
        }
        if (noteText) noteText.textContent = "-";
        const destHouse = document.getElementById("rider-dest-house");
        const destSubdistrict = document.getElementById("rider-dest-subdistrict");
        const phoneBadge = document.getElementById("rider-phone-badge");
        const gpsCoords = document.getElementById("rider-gps-coords");
        if (destHouse) destHouse.textContent = "รอระบุที่อยู่จัดส่ง";
        if (destSubdistrict) destSubdistrict.textContent = "อำเภอบ้านบึง จังหวัดชลบุรี";
        if (phoneBadge) phoneBadge.textContent = "-";
        if (gpsCoords) gpsCoords.textContent = "-";
        if (statusBadge) {
            statusBadge.className = "text-[10px] font-bold px-2 py-0.5 rounded-full bg-slate-100 text-slate-600";
            statusBadge.textContent = "พร้อมรับงาน";
        }
        if (refundAlert) refundAlert.classList.add("hidden");
        if (completedBanner) completedBanner.classList.add("hidden");
        return;
    }

    const destHouse = document.getElementById("rider-dest-house");
    const destSubdistrict = document.getElementById("rider-dest-subdistrict");
    const phoneBadge = document.getElementById("rider-phone-badge");
    const gpsCoords = document.getElementById("rider-gps-coords");
    const callBtnText = document.getElementById("rider-call-btn-text");

    const orderLat = order.lat || (state.deliveryLocation && state.deliveryLocation.lat) || MARKET_ORIGIN.lat;
    const orderLng = order.lng || (state.deliveryLocation && state.deliveryLocation.lng) || MARKET_ORIGIN.lng;
    const orderPhone = order.customerPhone || (state.customer && state.customer.phone) || "-";

    const callMerchantBtn = document.getElementById("rider-call-merchant-btn");
    const callMerchantText = document.getElementById("rider-call-merchant-text");

    if (order.orderType === "MERCHANT_EXPRESS") {
        const origin = order.originStall || {};
        if (badge) badge.textContent = `⚡ งานด่วน ${order.orderId}`;
        if (totalBadge) totalBadge.textContent = `฿${order.deliveryFee || 20} (ค่าจัดส่ง)`;
        if (destName) destName.textContent = `${order.customerName || 'ลูกค้า'} (จาก: ${origin.stallName || 'แผงค้า'})`;
        if (phoneBadge) phoneBadge.textContent = orderPhone;
        if (callBtnText) callBtnText.textContent = `โทรหาลูกค้า (${orderPhone})`;
        if (destDetail) destDetail.textContent = `🏪 รับของที่: ${origin.stallName || 'แผงค้า'} (${origin.stallNumber || 'แผงค้า'}) โทร ${origin.ownerPhone || '-'} | 📍 ส่ง: ${order.address}`;
        if (noteText) noteText.textContent = `พัสดุ: ร้านค้าแพ็คเรียบร้อยแล้ว • ค่าจัดส่ง ฿${order.deliveryFee || 20} (ไม่มีบริการ COD)`;

        if (callMerchantBtn) {
            callMerchantBtn.classList.remove("hidden");
            if (callMerchantText) callMerchantText.textContent = `โทรหาแผงค้า (${origin.ownerPhone || '-'})`;
        }
    } else {
        if (badge) badge.textContent = `ออเดอร์ ${order.orderId}`;
        if (totalBadge) totalBadge.textContent = `฿${order.grandTotal || order.total || 0} (${order.paymentDesc || 'ชำระแล้ว'})`;
        if (destName) destName.textContent = order.customerName || "ลูกค้าประจำ";
        if (phoneBadge) phoneBadge.textContent = orderPhone;
        if (callBtnText) callBtnText.textContent = `โทรหาลูกค้า (${orderPhone})`;
        if (destDetail) destDetail.textContent = `ที่อยู่: ${order.address || 'ตามพิกัดที่ลูกค้าระบุ'}`;
        if (noteText) noteText.textContent = order.landmark || order.deliveryNote || "-";
        if (callMerchantBtn) callMerchantBtn.classList.add("hidden");
    }

    if (destHouse) {
        if (order.houseNumber) {
            destHouse.textContent = `${order.houseNumber} ${order.soiRoad || ''}`.trim();
        } else {
            destHouse.textContent = order.address || "ตามพิกัดดาวเทียม";
        }
    }
    if (destSubdistrict) {
        destSubdistrict.textContent = order.subdistrict || "อำเภอบ้านบึง จังหวัดชลบุรี";
    }
    if (gpsCoords) gpsCoords.textContent = `${Number(orderLat).toFixed(6)}, ${Number(orderLng).toFixed(6)}`;

    // Direct Turn-by-Turn GPS navigation link into Google Maps
    if (mapsLink) {
        mapsLink.href = `https://www.google.com/maps/dir/?api=1&destination=${orderLat},${orderLng}`;
    }

    // Check Refund Amount (กรณีมีสินค้าขาด)
    let refundCashTotal = order.refundCashTotal || 0;
    if (refundCashTotal === 0 && order.stalls) {
        const stallList = Array.isArray(order.stalls) ? order.stalls : Object.values(order.stalls || {});
        stallList.forEach(s => {
            if (!s) return;
            const items = Array.isArray(s.items) ? s.items : Object.values(s.items || {});
            items.forEach(it => {
                if (it && it.outOfStock) {
                    refundCashTotal += (it.actualPrice !== undefined ? it.actualPrice : it.price) || 0;
                }
            });
        });
        order.refundCashTotal = refundCashTotal;
    }

    if (refundAlert) {
        if (refundCashTotal > 0 && order.status !== "delivered") {
            refundAlert.classList.remove("hidden");
            if (refundAmount) refundAmount.textContent = `฿${refundCashTotal}`;
        } else {
            refundAlert.classList.add("hidden");
        }
    }

    // Dynamic Button States based on order.status
    const status = order.status || "picking";

    if (status === "delivering") {
        if (statusBadge) {
            statusBadge.className = "text-[10px] font-bold px-2 py-0.5 rounded-full bg-blue-100 text-blue-800 animate-pulse";
            statusBadge.textContent = "🛵 กำลังออกส่ง";
        }
        if (btnStart) {
            btnStart.className = "p-3 bg-emerald-50 text-emerald-800 border border-emerald-300 font-bold rounded-xl shadow-xs flex items-center justify-center gap-1 text-xs active:scale-95 transition-all";
        }
        if (btnStartText) btnStartText.textContent = `✓ รับของแล้ว (${order.startedDeliveryAt || 'กำลังส่ง'})`;
        if (btnStartIcon) btnStartIcon.textContent = "check";

        if (btnComplete) {
            btnComplete.className = "p-3 bg-emerald-700 hover:bg-emerald-800 text-white font-extrabold rounded-xl shadow-md flex items-center justify-center gap-1 text-xs ring-2 ring-emerald-400 ring-offset-2 animate-pulse active:scale-95 transition-all";
        }
        if (btnCompleteText) {
            btnCompleteText.textContent = "2. ส่งมอบสำเร็จ (แตะเมื่อถึง)";
        }
        if (btnCompleteIcon) btnCompleteIcon.textContent = "check_circle";

        if (completedBanner) completedBanner.classList.add("hidden");

    } else if (status === "delivered") {
        if (statusBadge) {
            statusBadge.className = "text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-800";
            statusBadge.textContent = "🎉 จัดส่งสำเร็จแล้ว";
        }
        if (btnStart) {
            btnStart.className = "p-3 bg-slate-100 text-slate-400 font-medium rounded-xl flex items-center justify-center gap-1 text-xs cursor-default";
        }
        if (btnStartText) btnStartText.textContent = "✓ รับของแล้ว";
        if (btnStartIcon) btnStartIcon.textContent = "check";

        if (btnComplete) {
            btnComplete.className = "p-3 bg-emerald-50 text-emerald-800 border border-emerald-300 font-bold rounded-xl flex items-center justify-center gap-1 text-xs cursor-default";
        }
        if (btnCompleteText) btnCompleteText.textContent = `✓ ส่งมอบสำเร็จแล้ว (${order.deliveredAt || '09:05 น.'})`;
        if (btnCompleteIcon) btnCompleteIcon.textContent = "verified";

        if (completedBanner) completedBanner.classList.remove("hidden");

    } else {
        // "picking" or initial status
        if (statusBadge) {
            statusBadge.className = "text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-100 text-amber-800";
            statusBadge.textContent = (order.orderType === "MERCHANT_EXPRESS") ? "📦 รับของที่หน้าแผงค้า" : "📦 รอรับของสดจากฮับ";
        }
        if (btnStart) {
            btnStart.className = "p-3 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-xl shadow-xs flex items-center justify-center gap-1 text-xs active:scale-95 transition-all";
        }
        if (btnStartText) {
            btnStartText.textContent = (order.orderType === "MERCHANT_EXPRESS") ? "1. ถึงแผงค้าและรับของแล้ว 🛵💨" : "1. รับของแล้ว ออกส่ง";
        }
        if (btnStartIcon) btnStartIcon.textContent = "two_wheeler";

        if (btnComplete) {
            btnComplete.className = "p-3 bg-slate-100 text-slate-400 font-bold rounded-xl shadow-xs flex items-center justify-center gap-1 text-xs active:scale-95 transition-all";
        }
        if (btnCompleteText) btnCompleteText.textContent = "2. ส่งมอบสำเร็จ";
        if (btnCompleteIcon) btnCompleteIcon.textContent = "check_circle";

        if (completedBanner) completedBanner.classList.add("hidden");
    }
}

function assignSampleOrderToRider() {
    showToast("ℹ️ ระบบปิดการสร้างออเดอร์ตัวอย่างแล้ว ไรเดอร์จะรับเฉพาะออเดอร์จริงจากลูกค้า");
}
window.assignSampleOrderToRider = assignSampleOrderToRider;

// Rider Login & Logout
function renderRiderLoginModalList() {
    const container = document.getElementById("rider-quick-login-list");
    if (!container) return;
    // รายชื่อไรเดอร์แบบกดเข้าทันที (และใบสมัครที่รออนุมัติ) เป็นเครื่องมือเจ้าของเท่านั้น
    if (!isOwnerSignedIn()) { container.innerHTML = ""; return; }

    const riders = loadCommunityRiders();
    const apps = loadRiderApplications();
    const pendingApps = (apps || []).filter(a => a && a.status === "pending");

    let html = "";

    // If there are pending applications, highlight them with 1-Click Auto-Approve & Login!
    if (pendingApps.length > 0) {
        html += `
            <div class="p-2.5 bg-gradient-to-r from-amber-50 to-orange-50 border border-amber-300 rounded-2xl space-y-1.5 mb-2">
                <div class="text-[11px] font-extrabold text-amber-900 flex items-center gap-1">
                    <span class="material-symbols-outlined text-sm text-amber-600">person_search</span>
                    <span>ใบสมัครล่าสุดของคุณ (แตะเพื่ออนุมัติและเข้าสู่ระบบทันที):</span>
                </div>
        `;
        pendingApps.forEach(a => {
            const displayName = a.nickname ? `${a.fullName} (${a.nickname})` : a.fullName;
            const code = a.accessCode || a.id;
            html += `
                <div class="flex items-center justify-between p-2 bg-white rounded-xl border border-amber-200 shadow-2xs">
                    <div>
                        <div class="font-bold text-xs text-slate-900">${escapeHtml(displayName)}</div>
                        <div class="text-[10px] text-slate-500 font-mono">โทร: ${escapeHtml(a.phone)} • รหัส: <strong class="text-amber-700 font-bold">${code}</strong></div>
                    </div>
                    <button type="button" onclick="approveAndLoginRider(${jsArg(a.id)})" class="px-2.5 py-1.5 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-700 hover:to-teal-700 text-white font-extrabold rounded-xl text-xs shadow-xs active:scale-95 transition-all flex items-center gap-1 cursor-pointer">
                        <span class="material-symbols-outlined text-xs">verified</span>
                        <span>⚡ อนุมัติ & รับงาน</span>
                    </button>
                </div>
            `;
        });
        html += `</div>`;
    }

    if (!riders || riders.length === 0) {
        if (pendingApps.length === 0) {
            html += `
                <div class="p-3 bg-slate-50 rounded-2xl border border-dashed border-slate-200 text-center text-slate-400 text-xs">
                    <div>ยังไม่มีรายชื่อไรเดอร์ที่อนุมัติในระบบ</div>
                    <button type="button" onclick="closeRiderLoginModal(); openRiderRegisterModal();" class="mt-1.5 text-sky-600 font-bold underline hover:text-sky-800 cursor-pointer">
                        + สมัครเป็นไรเดอร์ใหม่ทันที
                    </button>
                </div>
            `;
        }
        container.innerHTML = html;
        return;
    }

    riders.forEach(r => {
        const code = r.accessCode || r.pin || (r.id ? r.id.slice(-6).toUpperCase() : "-");
        html += `
            <div class="flex items-center justify-between p-2.5 bg-slate-50 hover:bg-sky-50/80 rounded-2xl border border-slate-200 transition-all">
                <div class="flex items-center gap-2">
                    <div class="w-8 h-8 rounded-xl bg-sky-100 text-sky-800 flex items-center justify-center font-bold text-sm shrink-0">
                        🛵
                    </div>
                    <div class="text-left">
                        <div class="font-extrabold text-xs text-slate-900">${escapeHtml(r.name)}</div>
                        <div class="text-[10px] text-slate-500 font-mono">รหัส: <strong class="text-sky-700 font-bold">${code}</strong> • ทะเบียน: ${escapeHtml(r.plate) || '-'}</div>
                    </div>
                </div>
                <button type="button" onclick="loginRiderById(${jsArg(r.id)})" class="px-3.5 py-1.5 bg-gradient-to-r from-sky-600 to-blue-600 hover:from-sky-700 hover:to-blue-700 text-white font-extrabold rounded-xl text-xs shadow-sm active:scale-95 transition-all cursor-pointer flex items-center gap-1">
                    <span class="material-symbols-outlined text-xs">login</span>
                    <span>เข้าสู่ระบบ</span>
                </button>
            </div>
        `;
    });
    container.innerHTML = html;
}
window.renderRiderLoginModalList = renderRiderLoginModalList;

function openRiderLoginModal() {
    const modal = document.getElementById("rider-login-modal");
    if (!modal) return;
    modal.classList.remove("hidden");
    modal.style.display = "flex";
    modal.style.zIndex = "999999";

    renderRiderLoginModalList();

    const secretInput = document.getElementById("rider-login-secret-input");
    if (secretInput) secretInput.value = "";
    const phoneInput = document.getElementById("rider-login-number-input");
    if (phoneInput) {
        phoneInput.value = "";
        setTimeout(() => phoneInput.focus(), 100);
    }
}
window.openRiderLoginModal = openRiderLoginModal;

function closeRiderLoginModal() {
    const modal = document.getElementById("rider-login-modal");
    if (modal) {
        modal.classList.add("hidden");
        modal.style.display = "none";
    }
}
window.closeRiderLoginModal = closeRiderLoginModal;

function quickLoginRider(name) {
    if (!requireOwnerAction()) return;   // ล็อกอินเป็นไรเดอร์คนแรกโดยไม่ใช้รหัส = เครื่องมือเจ้าของ
    const riders = loadCommunityRiders();
    if (riders && riders.length > 0) {
        loginRiderWithProfile(riders[0]);
        return;
    }
    showToast("⚠️ ยังไม่มีรายชื่อไรเดอร์ในระบบ กรุณาสมัครเป็นไรเดอร์ใหม่");
    closeRiderLoginModal();
    openRiderRegisterModal();
}
window.quickLoginRider = quickLoginRider;

function handleRiderLoginSubmit() {
    if (!requireOwnerAction()) return;   // เลือกไรเดอร์จากรายการแล้วเข้าเลย = เครื่องมือเจ้าของ
    const riderSelect = document.getElementById("rider-select-input");
    const val = riderSelect ? riderSelect.value : "";
    if (!val) {
        showToast("⚠️ กรุณาเลือกไรเดอร์ หรือกรอกรหัส PIN ด้านล่าง");
        return;
    }

    const riders = loadCommunityRiders();
    const r = riders.find(x => x.id === val);
    if (!r) {
        showToast("⚠️ ไม่พบข้อมูลไรเดอร์ที่เลือก");
        return;
    }

    loginRiderWithProfile(r);
}
window.handleRiderLoginSubmit = handleRiderLoginSubmit;

function handleRiderPhoneLoginSubmit() {
    // ชื่อฟังก์ชันคงเดิมเพราะหน้าเว็บเรียกอยู่ แต่ตอนนี้ล็อกอินด้วย "เลขไรเดอร์ + รหัสผ่านลับ" ไม่ใช่เบอร์โทร
    return submitRiderSecretLogin("rider-login-number-input", "rider-login-secret-input");
}
window.handleRiderPhoneLoginSubmit = handleRiderPhoneLoginSubmit;

function loginRiderWithProfile(r) {
    if (!r) {
        showToast("⚠️ ไม่พบข้อมูลไรเดอร์");
        return;
    }
    state.activeRider = {
        isLoggedIn: true,
        riderId: r.id || r.riderId || (typeof generate6DigitAccessCode === "function" ? generate6DigitAccessCode("RD") : "RD" + Math.floor(1000 + Math.random() * 9000)),
        id: r.id || r.riderId || (typeof generate6DigitAccessCode === "function" ? generate6DigitAccessCode("RD") : "RD" + Math.floor(1000 + Math.random() * 9000)),
        name: r.name || "ไรเดอร์ประจำตลาด",
        phone: r.phone || "",
        license: r.plate || r.license || "-",
        plate: r.plate || r.license || "-",
        promptPay: r.promptPay || r.phone || "",
        avatar: r.avatar || "🛵",
        zone: r.zone || "ตลาดวิศิษฐ์ชัย และอำเภอบ้านบึง (ระยะ 5 กม.)"
    };
    saveRiderToStorage(state.activeRider);

    // Keep admin & merchant sessions preserved so multi-role operators can switch back freely

    const profName = document.getElementById("rider-profile-name");
    if (profName) profName.textContent = state.activeRider.name;

    closeRiderLoginModal();
    closeRiderRegisterModal();
    setActiveRoleView("rider");
    renderAuthHeaderButtons();
    if (typeof switchRiderMainTab === "function") {
        switchRiderMainTab("active");
    }
    try {
        renderRiderScreen();
    } catch (err) {
        console.warn("renderRiderScreen error:", err);
    }
    try {
        if (typeof renderRiderWallet === "function") {
            renderRiderWallet();
        }
    } catch (err) {
        console.warn("renderRiderWallet error:", err);
    }
    updateRiderRoleButtonUI();
    if (typeof updateRoleSelectorVisibility === "function") {
        updateRoleSelectorVisibility();
    }
    showToast(`🎉 เข้าสู่ระบบไรเดอร์สำเร็จ! ยินดีต้อนรับ ${state.activeRider.name}`);
}
window.loginRiderWithProfile = loginRiderWithProfile;

function logoutRider() {
    state.activeRider = null;
    saveRiderToStorage(null);
    setActiveRoleView("customer");
    renderAuthHeaderButtons();
    updateRiderRoleButtonUI();
    if (typeof updateRoleSelectorVisibility === "function") {
        updateRoleSelectorVisibility();
    }
    showToast("🚪 ออกจากระบบไรเดอร์เรียบร้อยแล้ว");
}
window.logoutRider = logoutRider;

function updateRiderRoleButtonUI() {
    const btn = document.getElementById("role-btn-rider");
    if (!btn) return;
    const isRiderLoggedIn = !!(state.activeRider && state.activeRider.isLoggedIn);
    if (isRiderLoggedIn) {
        btn.classList.add("logged-in");
    } else {
        btn.classList.remove("logged-in");
    }
}
window.updateRiderRoleButtonUI = updateRiderRoleButtonUI;

// ── ไรเดอร์กด Step 1: รับของแล้ว ออกเดินทางส่งของสด ──────────────────────────────
function handleRiderStartDelivery() {
    if (!state.activeOrder) {
        state.activeOrder = loadSavedActiveOrder();
    }
    if (!state.activeOrder) {
        showToast("⚠️ ไม่มีออเดอร์ในระบบสำหรับเริ่มจัดส่ง");
        return;
    }

    const order = state.activeOrder;
    const now = new Date();
    const timeStr = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')} น.`;
    order.status = "delivering";
    order.startedDeliveryAt = timeStr;

    // ซิงค์ชื่อและเบอร์ไรเดอร์
    if (state.activeRider && state.activeRider.isLoggedIn) {
        order.riderName = state.activeRider.name;
        order.riderPhone = state.activeRider.phone;
        order.riderPlate = state.activeRider.license;
    }

    // อัปเดตสถานะไรเดอร์ในทำเนียบกองยานเป็น on_delivery
    try {
        const riders = loadCommunityRiders();
        const curRider = riders.find(r => 
            (state.activeRider && (r.id === state.activeRider.riderId || r.phone === state.activeRider.phone)) ||
            r.name === order.riderName
        );
        if (curRider) {
            curRider.status = "on_delivery";
            saveCommunityRiders(riders);
        }
    } catch(e) {}

    if (order.stalls) {
        order.stalls.forEach(s => {
            s.pickedCount = s.itemsCount || (s.items ? s.items.length : 0);
            if (s.items) s.items.forEach(i => i.picked = true);
        });
    }

    saveActiveOrderToStorage(order);
    updateOrderStatusInFirebase(order.orderId, "delivering");

    // Render ทุกมุมมองที่เกี่ยวข้อง
    renderRiderScreen();
    if (typeof renderTrackingScreen === "function") renderTrackingScreen();
    if (typeof updateHomeActiveOrderBanner === "function") updateHomeActiveOrderBanner();
    if (typeof renderMerchantActiveDeliveries === "function") renderMerchantActiveDeliveries();
    if (typeof renderHubPickingList === "function") renderHubPickingList();
    if (typeof initAdminRiderRadarMap === "function") initAdminRiderRadarMap();
    if (typeof playOrderAlertSound === "function") playOrderAlertSound();

    const startMsg = (order.orderType === "MERCHANT_EXPRESS")
        ? `🛵 ไรเดอร์รับของจาก "${order.originStall?.stallName || 'แผงค้า'}" แล้ว ออกเดินทางนำส่งลูกค้า!`
        : "🛵 ไรเดอร์รับของแล้ว ออกเดินทางส่งของสด! ลูกค้าสามารถติดตาม GPS ได้แบบเรียลไทม์";
    showToast(startMsg);
}
window.handleRiderStartDelivery = handleRiderStartDelivery;

// ── ไรเดอร์กด Step 2: ส่งมอบสำเร็จ (ถึงหน้าบ้านลูกค้า) ──────────────────────────
function handleRiderCompleteDelivery() {
    if (!state.activeOrder) {
        state.activeOrder = loadSavedActiveOrder();
    }
    if (!state.activeOrder) {
        showToast("⚠️ ไม่มีออเดอร์ที่กำลังนำส่ง");
        return;
    }

    const order = state.activeOrder;
    const now = new Date();
    const timeStr = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')} น.`;
    order.status = "delivered";
    order.deliveredAt = timeStr;
    if (!order.startedDeliveryAt) {
        order.startedDeliveryAt = timeStr;
    }
    if (!order.savedAt) {
        order.savedAt = Date.now();
    }

    // คืนสถานะไรเดอร์กลับมาเป็น available
    let riderName = order.riderName || (state.activeRider ? state.activeRider.name : "ไรเดอร์");
    try {
        const riders = loadCommunityRiders();
        const curRider = riders.find(r => 
            (state.activeRider && (r.id === state.activeRider.riderId || r.phone === state.activeRider.phone)) ||
            r.name === riderName
        );
        if (curRider) {
            curRider.status = "available";
            saveCommunityRiders(riders);
        }
    } catch(e) {}

    if (order.stalls) {
        order.stalls.forEach(s => {
            s.pickedCount = s.itemsCount || (s.items ? s.items.length : 0);
            if (s.items) s.items.forEach(i => i.picked = true);
        });
    }

    // 1. บันทึก order ให้เรียบร้อย ทั้ง localStorage และ Firebase
    saveActiveOrderToStorage(order);
    updateOrderStatusInFirebase(order.orderId, "delivered");

    // 2. Aggregate รายงานประจำวันทันที เพื่อให้ Admin Tab 1 & Tab 2 อัปเดตยอด
    try {
        const dateKey = getReportDateKey(order.savedAt || Date.now());
        aggregateDailyOperations(dateKey);
    } catch(e) {
        console.warn("aggregateDailyOperations error:", e);
    }

    // 3. Render ทุกหน้าจอที่เกี่ยวข้อง
    renderRiderScreen();
    if (typeof renderTrackingScreen === "function") renderTrackingScreen();
    if (typeof updateHomeActiveOrderBanner === "function") updateHomeActiveOrderBanner();
    if (typeof renderMerchantActiveDeliveries === "function") renderMerchantActiveDeliveries();
    if (typeof renderHubPickingList === "function") renderHubPickingList();
    if (typeof renderHubSettlement === "function") renderHubSettlement();
    if (typeof renderHubDailyReport === "function") renderHubDailyReport();
    if (typeof renderAdminAnalytics === "function") renderAdminAnalytics();
    if (typeof playOrderAlertSound === "function") playOrderAlertSound();

    openRiderDeliveryCompleteModal();
    const doneMsg = (order.orderType === "MERCHANT_EXPRESS")
        ? `🎉 ส่งมอบของจากร้านค้าถึงมือลูกค้าเรียบร้อยแล้ว! (ค่าส่ง ฿${order.deliveryFee || 20})`
        : `🎉 ไรเดอร์ (${order.riderName || 'คนขับ'}) ส่งมอบของสดถึงมือลูกค้าเรียบร้อยแล้ว! (+฿40 ค่ารอบ)`;
    showToast(doneMsg);
}
window.handleRiderCompleteDelivery = handleRiderCompleteDelivery;

// ── เปิด Modal สรุปส่งของสำเร็จ ─────────────────────────────────────────────
function openRiderDeliveryCompleteModal() {
    const modal = document.getElementById("rider-delivery-complete-modal");
    if (!modal) return;

    const o = state.activeOrder;
    if (o) {
        const setVal = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
        setVal("rdc-order-id", o.orderId || "-");
        setVal("rider-complete-order-id", `ออเดอร์ ${o.orderId || '-'}`);
        setVal("rdc-customer-name", o.customerName || "ลูกค้าทั่วไป");
        setVal("rider-complete-customer-name", o.customerName || o.customerPhone || "ลูกค้าทั่วไป");
        setVal("rdc-customer-phone", o.customerPhone || "-");
        setVal("rdc-customer-address", o.address || "อำเภอบ้านบึง จังหวัดชลบุรี");

        const pType = (o.paymentType || "promptpay").toLowerCase();
        const isCod = pType === "cod" || pType === "cash";
        const payDesc = o.paymentDesc || (pType === "bank_transfer" ? "โอน SCB แล้ว" : (isCod ? "💵 เงินสดปลายทาง (COD)" : "📱 ชำระผ่านระบบแล้ว"));
        setVal("rdc-payment-desc", payDesc);
        setVal("rdc-order-amount", `฿${(o.grandTotal || o.total || 0).toLocaleString()}`);
        setVal("rider-complete-payment-info", `฿${(o.grandTotal || o.total || 0).toLocaleString()} (${payDesc})`);
        setVal("rdc-delivered-time", o.deliveredAt || (new Date().toLocaleTimeString("th-TH", { hour: "2-digit", minute: "2-digit" }) + " น."));

        const refundBox = document.getElementById("rdc-refund-box");
        const refundAmtEl = document.getElementById("rdc-refund-amount");
        const refundRow = document.getElementById("rider-complete-refund-row");
        const refundAmt = document.getElementById("rider-complete-refund-amount");
        if (o.refundCashTotal && o.refundCashTotal > 0) {
            if (refundBox) refundBox.classList.remove("hidden");
            if (refundAmtEl) refundAmtEl.textContent = `฿${o.refundCashTotal}`;
            if (refundRow) refundRow.classList.remove("hidden");
            if (refundAmt) refundAmt.textContent = `฿${o.refundCashTotal}`;
        } else {
            if (refundBox) refundBox.classList.add("hidden");
            if (refundRow) refundRow.classList.add("hidden");
        }

        // Setup Photo Proof Preview
        const proofImg = document.getElementById("rider-proof-img");
        const proofBox = document.getElementById("rider-proof-preview-box");
        const proofTag = document.getElementById("rider-proof-status-tag");
        const proofBtn = document.getElementById("rider-proof-btn-text");
        if (o.deliveryProofImage && proofImg && proofBox) {
            proofImg.src = o.deliveryProofImage;
            proofBox.classList.remove("hidden");
            if (proofTag) {
                proofTag.textContent = "✓ แนบรูปแล้ว";
                proofTag.className = "text-[9px] bg-emerald-100 text-emerald-800 font-bold px-2 py-0.5 rounded-full";
            }
            if (proofBtn) proofBtn.textContent = "📷 เปลี่ยนรูปหลักฐานการวางของ";
        } else {
            if (proofBox) proofBox.classList.add("hidden");
            if (proofImg) proofImg.src = "";
            if (proofTag) {
                proofTag.textContent = "ยังไม่แนบรูป";
                proofTag.className = "text-[9px] bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full font-bold";
            }
            if (proofBtn) proofBtn.textContent = "📷 ถ่ายรูป / แนบรูปการวางของสด";
        }
    }

    modal.classList.remove("hidden");
}
window.openRiderDeliveryCompleteModal = openRiderDeliveryCompleteModal;

// Rider Photo Proof Upload Handler
function handleRiderDeliveryProofUpload(event) {
    const file = event.target.files && event.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function (e) {
        const dataUrl = e.target.result;
        const img = document.getElementById("rider-proof-img");
        const box = document.getElementById("rider-proof-preview-box");
        const tag = document.getElementById("rider-proof-status-tag");
        const btnText = document.getElementById("rider-proof-btn-text");
        if (img) img.src = dataUrl;
        if (box) box.classList.remove("hidden");
        if (tag) {
            tag.textContent = "✓ แนบรูปแล้ว";
            tag.className = "text-[9px] bg-emerald-100 text-emerald-800 font-bold px-2 py-0.5 rounded-full";
        }
        if (btnText) btnText.textContent = "📷 เปลี่ยนรูปหลักฐานการวางของ";
        if (state.activeOrder) {
            state.activeOrder.deliveryProofImage = dataUrl;
            saveActiveOrderToStorage(state.activeOrder);
        }
        showToast("📸 แนบรูปถ่ายหลักฐานการส่งมอบของสดเรียบร้อยแล้ว!");
    };
    reader.readAsDataURL(file);
}
window.handleRiderDeliveryProofUpload = handleRiderDeliveryProofUpload;

// Rider Arrival Alert (LINE / SMS notification to customer)
function sendRiderArrivalAlert() {
    const o = state.activeOrder;
    if (!o) {
        showToast("⚠️ ไม่มีออเดอร์");
        return;
    }
    playOrderAlertSound();
    showToast("📢 ส่งแจ้งเตือน 'ไรเดอร์ถึงหน้ารั้วบ้านแล้ว' เรียบร้อย! 🔔");
}
window.sendRiderArrivalAlert = sendRiderArrivalAlert;

function closeRiderDeliveryCompleteModal() {
    const modal = document.getElementById("rider-delivery-complete-modal");
    if (modal) modal.classList.add("hidden");
}
window.closeRiderDeliveryCompleteModal = closeRiderDeliveryCompleteModal;

