function switchMerchantPortalTab(tabId) {
    document.querySelectorAll(".merchant-tab-pane").forEach(pane => pane.classList.add("hidden"));
    const activePane = document.getElementById(tabId);
    if (activePane) activePane.classList.remove("hidden");

    document.querySelectorAll(".merchant-tab-btn").forEach(btn => {
        btn.classList.remove("active", "bg-white", "text-emerald-800", "shadow-xs", "font-bold");
        btn.classList.add("bg-transparent", "text-slate-600", "font-medium");
    });

    const activeBtn = document.getElementById(`btn-${tabId}`);
    if (activeBtn) {
        activeBtn.classList.remove("bg-transparent", "text-slate-600", "font-medium");
        activeBtn.classList.add("active", "bg-white", "text-emerald-800", "shadow-xs", "font-bold");
    }
    const scrollContent = document.getElementById("merchant-portal-content");
    if (scrollContent) scrollContent.scrollTop = 0;
    validateMerchantForm();
}

function validateMerchantForm() {
    const stallName = (document.getElementById("m-stall-name")?.value || "").trim();
    const contactName = (document.getElementById("m-contact1-name")?.value || "").trim() || (document.getElementById("m-owner-name")?.value || "").trim();
    const contactPhone = (document.getElementById("m-contact1-phone")?.value || "").trim() || (document.getElementById("m-phone")?.value || "").trim();

    let hasProduct = false;
    for (let i = 0; i < 10; i++) {
        if ((document.getElementById(`m-p-name-${i}`)?.value || "").trim()) {
            hasProduct = true;
            break;
        }
    }
    if (!hasProduct) {
        const catRows = document.querySelectorAll("#merchant-catalog-container .catalog-item-name-input");
        for (let r of catRows) {
            if (r.value.trim()) {
                hasProduct = true;
                break;
            }
        }
    }
    if (!hasProduct && _isEditingMerchantStall) {
        const s = MARKET_DATA.find(x => x.stallId === activeMerchantStallId) || ALL_100_STALLS.find(x => x.stallId === activeMerchantStallId);
        if (s && ((s.products && s.products.length > 0) || (s.catalog && s.catalog.length > 0))) {
            hasProduct = true;
        }
    }

    const isValid = !!(stallName && contactPhone && hasProduct);

    const submitBtn = document.getElementById("merchant-submit-footer-btn");
    if (submitBtn) {
        if (isValid || _isEditingMerchantStall) {
            submitBtn.classList.remove("hidden");
        } else {
            submitBtn.classList.add("hidden");
        }
    }

    const previewSubmitBtn = document.getElementById("preview-submit-action-btn");
    if (previewSubmitBtn) {
        if (isValid || _isEditingMerchantStall) {
            previewSubmitBtn.classList.remove("hidden");
        } else {
            previewSubmitBtn.classList.add("hidden");
        }
    }
}

function compressImageFile(file, maxWidth = 640, maxHeight = 360, quality = 0.8) {
    return new Promise((resolve) => {
        if (!file || !file.type || !file.type.startsWith('image/')) return resolve(null);
        const reader = new FileReader();
        reader.onload = (e) => {
            const img = new Image();
            img.onload = () => {
                const targetW = maxWidth;
                const targetH = maxHeight;
                const canvas = document.createElement("canvas");
                canvas.width = targetW;
                canvas.height = targetH;
                const ctx = canvas.getContext("2d");

                // Dark neutral background
                ctx.fillStyle = "#090d16";
                ctx.fillRect(0, 0, targetW, targetH);

                // 1. Draw blurred backdrop to fill entire 16:9 frame smoothly
                const bgScale = Math.max(targetW / img.width, targetH / img.height);
                const bgW = img.width * bgScale;
                const bgH = img.height * bgScale;
                const bgX = (targetW - bgW) / 2;
                const bgY = (targetH - bgH) / 2;
                
                ctx.save();
                if (ctx.filter !== undefined) {
                    ctx.filter = "blur(14px) brightness(0.65)";
                }
                ctx.drawImage(img, bgX, bgY, bgW, bgH);
                ctx.restore();

                // 2. Draw clear image in center (fits entire face/stall without distortion or clipping)
                const scale = Math.min(targetW / img.width, targetH / img.height);
                const drawW = img.width * scale;
                const drawH = img.height * scale;
                const drawX = (targetW - drawW) / 2;
                const drawY = (targetH - drawH) / 2;
                ctx.drawImage(img, drawX, drawY, drawW, drawH);

                const compressed = canvas.toDataURL("image/jpeg", quality);
                resolve(compressed);
            };
            img.onerror = () => resolve(e.target.result);
            img.src = e.target.result;
        };
        reader.onerror = () => resolve(null);
        reader.readAsDataURL(file);
    });
}
window.compressImageFile = compressImageFile;

function compressDataUrl(dataUrl, maxWidth = 640, maxHeight = 360, quality = 0.8) {
    return new Promise((resolve) => {
        if (!dataUrl || typeof dataUrl !== 'string' || !dataUrl.startsWith('data:image')) {
            return resolve(dataUrl);
        }
        const img = new Image();
        img.onload = () => {
            const targetW = maxWidth;
            const targetH = maxHeight;
            const canvas = document.createElement("canvas");
            canvas.width = targetW;
            canvas.height = targetH;
            const ctx = canvas.getContext("2d");

            ctx.fillStyle = "#090d16";
            ctx.fillRect(0, 0, targetW, targetH);

            const bgScale = Math.max(targetW / img.width, targetH / img.height);
            const bgW = img.width * bgScale;
            const bgH = img.height * bgScale;
            const bgX = (targetW - bgW) / 2;
            const bgY = (targetH - bgH) / 2;
            
            ctx.save();
            if (ctx.filter !== undefined) {
                ctx.filter = "blur(14px) brightness(0.65)";
            }
            ctx.drawImage(img, bgX, bgY, bgW, bgH);
            ctx.restore();

            const scale = Math.min(targetW / img.width, targetH / img.height);
            const drawW = img.width * scale;
            const drawH = img.height * scale;
            const drawX = (targetW - drawW) / 2;
            const drawY = (targetH - drawH) / 2;
            ctx.drawImage(img, drawX, drawY, drawW, drawH);

            const compressed = canvas.toDataURL("image/jpeg", quality);
            resolve(compressed);
        };
        img.onerror = () => resolve(dataUrl);
        img.src = dataUrl;
    });
}
window.compressDataUrl = compressDataUrl;

async function handleMerchantFileUpload(event, targetInputId, targetPreviewImgId) {
    const file = event.target.files && event.target.files[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
        alert("กรุณาเลือกไฟล์ที่เป็นรูปภาพเท่านั้นครับ (JPEG, PNG, WEBP)");
        return;
    }

    try {
        const compressed = await compressImageFile(file, 640, 360, 0.8);
        const dataUrl = compressed || await new Promise(r => {
            const reader = new FileReader();
            reader.onload = e => r(e.target.result);
            reader.readAsDataURL(file);
        });

        const input = document.getElementById(targetInputId);
        const preview = document.getElementById(targetPreviewImgId);
        if (input) input.value = dataUrl;
        if (preview) {
            preview.src = dataUrl;
            preview.classList.remove("hidden");
        }
        updateMerchantImagePreviews();
        showToast("📸 อัปโหลดและปรับขนาดรูปภาพสำเร็จเรียบร้อยแล้ว!");
    } catch (err) {
        console.warn("Upload compression failed, falling back:", err);
    }
}

// ========================================================
// OWNER BANNER COMPOSITE & NAME BADGE SYSTEM
// ========================================================
const _ownerBannerCache = new Map();

function getOwnerBannerCacheKey(stall) {
    if (!stall) return "";
    const id = stall.stallId || "temp";
    const img1 = (stall.ownerImage || "").slice(0, 100);
    const img2 = (stall.owner2Image || "").slice(0, 100);
    const n1 = stall.owner1Nickname || stall.ownerName || "";
    const n2 = stall.owner2Nickname || "";
    return `${id}_${img1}_${img2}_${n1}_${n2}`;
}

function getOrBuildOwnerBanner(stall) {
    if (!stall) return "";
    const defaultImg = stall.ownerImage || 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&auto=format&fit=crop&q=80';
    if (!stall.ownerImage && !stall.owner2Image) {
        return defaultImg;
    }
    const cacheKey = getOwnerBannerCacheKey(stall);
    if (_ownerBannerCache.has(cacheKey)) {
        return _ownerBannerCache.get(cacheKey);
    }
    // Asynchronously generate banner and update DOM
    buildOwnerBannerCanvas(stall).then(dataUrl => {
        if (dataUrl) {
            const imgEl = document.getElementById(`stall-owner-banner-img-${stall.stallId}`);
            if (imgEl) imgEl.src = dataUrl;
            const blurEl = document.getElementById(`stall-owner-banner-blur-${stall.stallId}`);
            if (blurEl) blurEl.src = dataUrl;
        }
    }).catch(err => {
        console.warn("Async banner composite failed for stall:", stall.stallId, err);
    });
    return defaultImg;
}
window.getOrBuildOwnerBanner = getOrBuildOwnerBanner;

async function buildOwnerBannerCanvas(stall) {
    if (!stall) return null;
    const img1Url = (stall.ownerImage || "").trim();
    const img2Url = (stall.owner2Image || "").trim();

    if (!img1Url && !img2Url) {
        return null;
    }

    const cacheKey = getOwnerBannerCacheKey(stall);
    if (_ownerBannerCache.has(cacheKey)) {
        return _ownerBannerCache.get(cacheKey);
    }

    const isDual = !!(img1Url && img2Url);
    const templateSrc = isDual ? 'images/owner_template_dual.png' : 'images/owner_template_single.png';

    const loadImage = (src) => new Promise((resolve, reject) => {
        if (!src) return resolve(null);
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => resolve(img);
        img.onerror = () => {
            const fallback = new Image();
            fallback.onload = () => resolve(fallback);
            fallback.onerror = () => resolve(null);
            fallback.src = src;
        };
        img.src = src;
    });

    try {
        const [tplImg, face1, face2] = await Promise.all([
            loadImage(templateSrc),
            loadImage(img1Url || img2Url),
            isDual ? loadImage(img2Url) : Promise.resolve(null)
        ]);

        if (!tplImg) return null;

        const canvas = document.createElement("canvas");
        const w = 1024;
        const h = 580;
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext("2d");

        // 1. Draw template background
        ctx.drawImage(tplImg, 0, 0, w, h);

        // Helper to draw circular face
        const drawCircularFace = (faceImg, cx, cy, radius) => {
            if (!faceImg) return;
            ctx.save();
            ctx.beginPath();
            ctx.arc(cx, cy, radius, 0, Math.PI * 2);
            ctx.closePath();
            ctx.clip();

            const srcW = faceImg.naturalWidth || faceImg.width;
            const srcH = faceImg.naturalHeight || faceImg.height;
            const scale = Math.max((radius * 2) / srcW, (radius * 2) / srcH);
            const drawW = srcW * scale;
            const drawH = srcH * scale;
            const drawX = cx - (drawW / 2);
            const drawY = cy - (drawH * 0.45);

            ctx.drawImage(faceImg, drawX, drawY, drawW, drawH);
            ctx.restore();
        };

        // Helper to draw Emerald & Gold Capsule Name Badge (Style 1)
        // Helper to draw Emerald & Gold Capsule Name Badge (Style 1: Expanded & Prominent)
        const drawEmeraldGoldBadge = (name, cx, cy, badgeH, fontSize = 28) => {
            if (!name || !name.trim()) return;
            const displayName = `✨ ${name.trim()}`;
            ctx.save();

            ctx.font = `bold ${fontSize}px 'Prompt', -apple-system, BlinkMacSystemFont, sans-serif`;
            const textMetrics = ctx.measureText(displayName);
            const padX = 36;
            const badgeW = Math.max(textMetrics.width + (padX * 2), 220);
            const badgeX = cx - (badgeW / 2);
            const badgeY = cy - (badgeH / 2);
            const r = badgeH / 2;

            const createPillPath = () => {
                ctx.beginPath();
                ctx.moveTo(badgeX + r, badgeY);
                ctx.lineTo(badgeX + badgeW - r, badgeY);
                ctx.arc(badgeX + badgeW - r, badgeY + r, r, -Math.PI / 2, Math.PI / 2);
                ctx.lineTo(badgeX + r, badgeY + badgeH);
                ctx.arc(badgeX + r, badgeY + r, r, Math.PI / 2, -Math.PI / 2);
                ctx.closePath();
            };

            // Outer Drop shadow
            ctx.shadowColor = "rgba(0, 0, 0, 0.5)";
            ctx.shadowBlur = 16;
            ctx.shadowOffsetX = 0;
            ctx.shadowOffsetY = 6;

            // Emerald linear gradient
            const grad = ctx.createLinearGradient(badgeX, badgeY, badgeX + badgeW, badgeY + badgeH);
            grad.addColorStop(0, "#065f46");
            grad.addColorStop(0.5, "#047857");
            grad.addColorStop(1, "#064e3b");
            ctx.fillStyle = grad;
            createPillPath();
            ctx.fill();

            // Gold Border (Thick & vibrant)
            ctx.shadowColor = "transparent";
            ctx.lineWidth = 4.5;
            ctx.strokeStyle = "#fbbf24";
            createPillPath();
            ctx.stroke();

            // Inner fine highlight
            ctx.lineWidth = 1;
            ctx.strokeStyle = "rgba(255, 255, 255, 0.35)";
            createPillPath();
            ctx.stroke();

            // Text (Bold, large, readable)
            ctx.fillStyle = "#ffffff";
            ctx.textAlign = "center";
            ctx.textBaseline = "middle";
            ctx.shadowColor = "rgba(0, 0, 0, 0.5)";
            ctx.shadowBlur = 4;
            ctx.shadowOffsetY = 1;
            ctx.fillText(displayName, cx, cy);

            ctx.restore();
        };

        const name1 = (stall.owner1Nickname || stall.ownerName || "").trim();
        const name2 = (stall.owner2Nickname || "").trim();

        if (isDual) {
            // Dual circles: Expanded r=188 to fill frame completely with NO GAP
            drawCircularFace(face1, 306, 276, 188);
            drawCircularFace(face2, 718, 276, 188);
            // Badges enlarged (h=72, font 30px) for prominent display
            drawEmeraldGoldBadge(name1, 306, 506, 72, 30);
            drawEmeraldGoldBadge(name2, 718, 506, 72, 30);
        } else {
            // Single center circle: Expanded r=199 to fill frame completely with NO GAP
            drawCircularFace(face1, 514, 286, 199);
            // Badge enlarged (h=76, font 32px) for prominent display
            drawEmeraldGoldBadge(name1, 514, 512, 76, 32);
        }

        const dataUrl = canvas.toDataURL("image/png", 0.92);
        _ownerBannerCache.set(cacheKey, dataUrl);
        return dataUrl;
    } catch (err) {
        console.warn("buildOwnerBannerCanvas failed, falling back to raw image:", err);
        return null;
    }
}
window.buildOwnerBannerCanvas = buildOwnerBannerCanvas;

