// Auto-sanitize test & mock data on application launch
function autoSanitizeProductionData() {
    const mockOrderIds = [
        "#TH-6114", "#TH-8101", "#TH-8102", "#TH-8103", "#TH-5324", "#TH-9568", "#TH-4692", "#TH-7564", "#TH-9999", "#TH-8801",
        "TH-6114", "TH-8101", "TH-8102", "TH-8103", "TH-5324", "TH-9568", "TH-4692", "TH-7564", "TH-9999", "TH-8801"
    ];
    
    // 1. Active order: purge from both talathub_active_order and hsong_active_order
    try {
        const orderKeys = ["talathub_active_order", "hsong_active_order"];
        for (const k of orderKeys) {
            const savedOrder = localStorage.getItem(k);
            if (savedOrder) {
                const parsed = JSON.parse(savedOrder);
                if (!parsed || !parsed.orderId || isMockOrder(parsed) || mockOrderIds.includes(parsed.orderId) || (typeof parsed.orderId === "string" && (parsed.orderId.startsWith("#TH-810") || parsed.orderId.includes("7564") || parsed.orderId.includes("9999")))) {
                    localStorage.removeItem(k);
                }
            }
        }
    } catch (e) {}

    // 2. In-memory activeOrder in state
    if (state.activeOrder && isMockOrder(state.activeOrder)) {
        state.activeOrder = null;
    }

    // 3. Order history
    try {
        const rawHist = localStorage.getItem("talathub_order_history");
        if (rawHist) {
            let hist = JSON.parse(rawHist);
            if (Array.isArray(hist)) {
                hist = hist.filter(o => o && o.orderId && !isMockOrder(o) && !mockOrderIds.includes(o.orderId) && !o.orderId.startsWith("#TH-810") && !o.orderId.includes("7564"));
                localStorage.setItem("talathub_order_history", JSON.stringify(hist));
            }
        }
    } catch (e) {}

    // 4. Merchant Express Orders
    try {
        const expRaw = localStorage.getItem("hsong_merchant_express_orders");
        if (expRaw) {
            let expList = JSON.parse(expRaw);
            if (Array.isArray(expList)) {
                expList = expList.filter(o => o && o.orderId && !isMockOrder(o) && !mockOrderIds.includes(o.orderId));
                localStorage.setItem("hsong_merchant_express_orders", JSON.stringify(expList));
            }
        }
    } catch (e) {}

    // 5. Purge mock order nodes from Firebase Realtime Database
    if (isFirebaseReady()) {
        try {
            const firebaseMockKeys = ["TH-7564", "TH-6114", "TH-8101", "TH-8102", "TH-8103", "TH-5324", "TH-9568", "TH-4692", "TH-9999", "TH-8801"];
            firebaseMockKeys.forEach(k => {
                db.ref(`orders/${k}`).remove().catch(() => {});
            });
        } catch(e) {}
    }

    // 3. Community riders & Rider applications: Complete purge of mock & sample riders
    try {
        const rawApps = localStorage.getItem("talathub_rider_applications");
        let apps = [];
        if (rawApps) {
            apps = JSON.parse(rawApps);
            if (Array.isArray(apps)) {
                apps = apps.filter(a => a && !isMockRiderApplication(a));
                localStorage.setItem("talathub_rider_applications", JSON.stringify(stripRiderPrivateList(apps)));
            }
        }

        const rawRiders = localStorage.getItem("talathub_community_riders");
        if (rawRiders) {
            let riders = JSON.parse(rawRiders);
            if (Array.isArray(riders)) {
                riders = riders.filter(r => r && !isMockCommunityRider(r));
                localStorage.setItem("talathub_community_riders", JSON.stringify(stripRiderPrivateList(riders)));
            }
        }
    } catch (e) {}

    // 4. Logged in rider
    try {
        const savedRider = localStorage.getItem("talathub_logged_in_rider");
        if (savedRider) {
            const r = JSON.parse(savedRider);
            if (r && (r.riderId === "rider_somchai" || r.riderId === "rider_sombat" || isMockCommunityRider(r))) {
                localStorage.removeItem("talathub_logged_in_rider");
            }
        }
    } catch (e) {}

    // 5. Force Purge old mock stalls from LocalStorage once
    try {
        if (localStorage.getItem("talathub_mock_purged_final_v1") !== "true") {
            localStorage.removeItem("talathub_custom_market_stalls");
            localStorage.removeItem("talathub_favorite_stalls");
            localStorage.removeItem("talathub_stall_catalog_database");
            localStorage.removeItem("talathub_merchant_applications");
            localStorage.setItem("talathub_mock_purged_final_v1", "true");
        }
    } catch (e) {}

    // 6. Favorites: filter out old mock stalls
    try {
        const savedFavs = localStorage.getItem("talathub_favorite_stalls");
        if (savedFavs) {
            let favs = JSON.parse(savedFavs);
            if (Array.isArray(favs)) {
                favs = favs.filter(id => id && (id.startsWith("stall_new_") || id.startsWith("APP-")));
                localStorage.setItem("talathub_favorite_stalls", JSON.stringify(favs));
            }
        }
    } catch (e) {}

    // 7. Cart: 1-time user-requested clean reset & sanitize
    try {
        if (localStorage.getItem("talathub_cart_reset_v924") !== "done") {
            localStorage.removeItem("talathub_cart");
            localStorage.setItem("talathub_cart", JSON.stringify([]));
            localStorage.setItem("talathub_cart_reset_v924", "done");
        }
    } catch (e) {}
    try {
        const savedCart = localStorage.getItem("talathub_cart");
        if (savedCart) {
            let cart = JSON.parse(savedCart);
            if (Array.isArray(cart)) {
                cart = cart.filter(item => item && (item.productId || item.id || item.name));
                localStorage.setItem("talathub_cart", JSON.stringify(cart));
            }
        }
    } catch (e) {}

    // 8. Custom stalls in localStorage: filter out old mock stalls
    try {
        const rawCustom = localStorage.getItem("talathub_custom_market_stalls");
        if (rawCustom) {
            let stalls = JSON.parse(rawCustom);
            if (Array.isArray(stalls)) {
                stalls = stalls.filter(s => s && s.stallId && (s.stallId.startsWith("stall_new_") || s.stallId.startsWith("APP-")));
                localStorage.setItem("talathub_custom_market_stalls", JSON.stringify(stalls));
            }
        }
    } catch (e) {}

    // 9. Stalls Catalog Database: wipe old mock stalls
    try {
        const rawCat = localStorage.getItem("talathub_stall_catalog_database");
        if (rawCat) {
            let db = JSON.parse(rawCat);
            if (db && typeof db === "object") {
                const cleanDb = {};
                for (const key of Object.keys(db)) {
                    if (key.startsWith("stall_new_") || key.startsWith("APP-")) {
                        cleanDb[key] = db[key];
                    }
                }
                localStorage.setItem("talathub_stall_catalog_database", JSON.stringify(cleanDb));
            }
        }
    } catch (e) {}

    // 10. Remove mock caches
    try {
        localStorage.removeItem("talathub_pending_stalls");
        localStorage.removeItem("talathub_mock_orders");
        localStorage.removeItem("talathub_rating_reviews");
    } catch (e) {}

    // 11. One-time clean reset for Admin Daily Report & Analytics test data
    try {
        if (localStorage.getItem("talathub_admin_reports_clean_v10") !== "true") {
            localStorage.removeItem("talathub_order_history");
            localStorage.removeItem("talathub_active_order");
            localStorage.removeItem("hsong_active_order");
            localStorage.removeItem("hsong_merchant_express_orders");
            localStorage.removeItem("hsong_orders");

            const keysToDel = [];
            for (let i = 0; i < localStorage.length; i++) {
                const k = localStorage.key(i);
                if (k && (k.startsWith("talathub_daily_report_") || k.startsWith("talathub_settled_riders_") || k.startsWith("talathub_settled_vendors_"))) {
                    keysToDel.push(k);
                }
            }
            keysToDel.forEach(k => localStorage.removeItem(k));
            localStorage.setItem("talathub_admin_reports_clean_v10", "true");
        }
    } catch (e) {}

    // 12. Complete Purge of all test/sample data requested by user (v11)
    try {
        if (localStorage.getItem("talathub_admin_purge_test_v11") !== "true") {
            localStorage.removeItem("talathub_order_history");
            localStorage.removeItem("talathub_active_order");
            localStorage.removeItem("hsong_active_order");
            localStorage.removeItem("hsong_merchant_express_orders");
            localStorage.removeItem("hsong_orders");
            localStorage.removeItem("talathub_mock_orders");
            localStorage.removeItem("talathub_community_riders");
            localStorage.removeItem("talathub_rider_applications");
            localStorage.removeItem("talathub_logged_in_rider");
            localStorage.removeItem("talathub_cart");
            localStorage.removeItem("talathub_delivery_location");
            localStorage.removeItem("talathub_market_stall_settings");

            const keysToDel = [];
            for (let i = 0; i < localStorage.length; i++) {
                const k = localStorage.key(i);
                if (k && (k.startsWith("talathub_daily_report_") || k.startsWith("talathub_settled_riders_") || k.startsWith("talathub_settled_vendors_"))) {
                    keysToDel.push(k);
                }
            }
            keysToDel.forEach(k => localStorage.removeItem(k));

            // ห้ามลบข้อมูลบนคลาวด์ตรงนี้: บล็อกนี้รันบนทุกเบราว์เซอร์เครื่องใหม่ (ลูกค้าคนแรกที่เข้าเว็บก็ลบออเดอร์ทั้งระบบได้)
            // ล้างข้อมูลคลาวด์ทำได้เฉพาะเจ้าของผ่านปุ่มล้างข้อมูลในหน้าฮับ/แอดมิน

            if (typeof ALL_100_STALLS !== "undefined" && Array.isArray(ALL_100_STALLS)) {
                ALL_100_STALLS.forEach(s => s.isClosed = false);
            }

            state.activeOrder = null;
            state.cart = [];
            state.merchantExpressOrders = [];
            if (window._cachedFirebaseOrders) window._cachedFirebaseOrders = [];

            localStorage.setItem("talathub_admin_purge_test_v11", "true");
        }
    } catch (e) {}

    // 13. (ยกเลิก) เคยสั่ง cleanRiderDatabase(true) อัตโนมัติบนเบราว์เซอร์เครื่องใหม่ทุกเครื่อง ซึ่งลบไรเดอร์ทั้งระบบบนคลาวด์
    //     ตอนนี้ล้างได้เฉพาะเจ้าของ ผ่านปุ่ม cleanRiderDatabase() เท่านั้น

}

async function fetchOnlineStallsStartup() {
    try {
        const [resApps, resCustom] = await Promise.allSettled([
            fetch("https://hsong-1f342-default-rtdb.asia-southeast1.firebasedatabase.app/merchant_applications.json").then(r => r.ok ? r.json() : null),
            fetch("https://hsong-1f342-default-rtdb.asia-southeast1.firebasedatabase.app/custom_market_stalls.json").then(r => r.ok ? r.json() : null)
        ]);
        const remoteApps = (resApps.status === 'fulfilled' && resApps.value) || null;
        const remoteCustom = (resCustom.status === 'fulfilled' && resCustom.value) || null;

        const appList = cloudValToList(remoteApps, _keyOfMerchantApp);
        const customList = cloudValToList(remoteCustom, _keyOfStall);

        let hasChanges = false;

        if (appList.length > 0) {
            appList.forEach(app => {
                if (app && app.status === 'approved' && app.stallData) {
                    if (app.stallData.products && Array.isArray(app.stallData.products)) {
                        app.stallData.products.forEach(p => { if (p && p.image) delete p.image; });
                    }
                    const sData = { ...app.stallData, accessCode: app.accessCode || app.stallData.accessCode };
                    const mIdx = MARKET_DATA.findIndex(s => s.stallId === sData.stallId);
                    if (mIdx >= 0) {
                        MARKET_DATA[mIdx] = { ...MARKET_DATA[mIdx], ...sData };
                    } else {
                        MARKET_DATA.unshift(sData);
                    }
                    if (typeof ALL_100_STALLS !== "undefined" && Array.isArray(ALL_100_STALLS)) {
                        const aIdx = ALL_100_STALLS.findIndex(s => s.stallId === sData.stallId);
                        if (aIdx >= 0) {
                            ALL_100_STALLS[aIdx] = { ...ALL_100_STALLS[aIdx], ...sData };
                        } else {
                            ALL_100_STALLS.unshift(sData);
                        }
                    }
                    hasChanges = true;
                }
            });
            try { localStorage.setItem("talathub_merchant_applications", JSON.stringify(appList)); } catch(e) {}
        }

        if (customList.length > 0) {
            const unapprovedIds = new Set(
                appList
                    .filter(a => a && a.status && a.status !== "approved")
                    .map(a => a.stallData?.stallId || a.id)
                    .filter(Boolean)
            );

            customList.forEach(stall => {
                if (stall && stall.stallId && !unapprovedIds.has(stall.stallId)) {
                    if (stall.products && Array.isArray(stall.products)) {
                        stall.products.forEach(p => { if (p && p.image) delete p.image; });
                    }
                    const mIdx = MARKET_DATA.findIndex(s => s.stallId === stall.stallId);
                    if (mIdx >= 0) {
                        MARKET_DATA[mIdx] = { ...MARKET_DATA[mIdx], ...stall };
                    } else {
                        MARKET_DATA.unshift(stall);
                    }
                    if (typeof ALL_100_STALLS !== "undefined" && Array.isArray(ALL_100_STALLS)) {
                        const aIdx = ALL_100_STALLS.findIndex(s => s.stallId === stall.stallId);
                        if (aIdx >= 0) {
                            ALL_100_STALLS[aIdx] = { ...ALL_100_STALLS[aIdx], ...stall };
                        } else {
                            ALL_100_STALLS.unshift(stall);
                        }
                    }
                    hasChanges = true;
                }
            });
            try { localStorage.setItem("talathub_custom_market_stalls", JSON.stringify(customList)); } catch(e) {}
        }

        if (hasChanges) {
            if (typeof renderCatalog === "function") renderCatalog();
            if (typeof renderDirectoryList === "function") renderDirectoryList();
            if (typeof renderFavoriteStallsBar === "function") renderFavoriteStallsBar();
            if (typeof updateStallRotationUI === "function") updateStallRotationUI();
            if (state.currentRole === "merchant" && typeof renderMerchantView === "function") {
                renderMerchantView();
            }
        }
    } catch (e) {
        console.warn("fetchOnlineStallsStartup error:", e);
    }
}
window.fetchOnlineStallsStartup = fetchOnlineStallsStartup;

