function initTalatHubApp() {
    autoSanitizeProductionData();

    // Sync approved merchant applications into MARKET_DATA for catalog display
    try {
        const _mAppsOnInit = loadMerchantApplications();
        _mAppsOnInit.forEach(app => {
            if (app && app.status === 'approved' && app.stallData && app.stallData.stallId) {
                const stall = { ...app.stallData, accessCode: app.accessCode || app.stallData.accessCode };
                const mIdx = MARKET_DATA.findIndex(s => s.stallId === stall.stallId);
                if (mIdx >= 0) {
                    MARKET_DATA[mIdx] = { ...MARKET_DATA[mIdx], ...stall };
                } else {
                    MARKET_DATA.unshift(stall);
                }
                if (typeof ALL_100_STALLS !== "undefined" && Array.isArray(ALL_100_STALLS)) {
                    const aIdx = ALL_100_STALLS.findIndex(s => s.stallId === stall.stallId);
                    if (aIdx >= 0) {
                        ALL_100_STALLS[aIdx] = { ...ALL_100_STALLS[aIdx], ...stall };
                    } else {
                        ALL_100_STALLS.unshift(stall);
                    }
                }
            }
        });
    } catch (_e) {}

    state.customer = loadSavedCustomer();
    state.cart = loadSavedCart();
    state.activeMerchant = loadSavedMerchant();
    state.activeHub = loadSavedHub();
    state.activeRider = loadSavedRider();
    state.activeAdmin = loadSavedAdmin();
    state.favorites = loadSavedFavorites();
    state.deliveryLocation = loadSavedLocation();

    // สถานะล็อกอินเจ้าของ (แอดมิน/ฮับ) มาจาก Firebase Authentication เท่านั้น
    initOwnerAuth();

    setActiveRoleView("customer");
    updateCustomerRoleButtonUI();
    updateRiderRoleButtonUI();
    renderScreenModeButton();
    updateDeliveryLocationUI();
    renderAuthHeaderButtons();
    updateCustomerLoyaltyBanner();
    renderFavoriteStallsBar();
    initStallRotation();
    renderCatalog();
    updateCartUI();
    initHeroBannerCarousel();
    initMarketHeroCarousel();
    if (typeof setupDragScroll === 'function') {
        setupDragScroll('category-tabs');
    }
    updateAdminRiderBadges();
    updateAdminStallsBadge();
    initRiderRealtimeSync();
    initMerchantRealtimeSync();
    initCustomStallsRealtimeSync();
    initCatalogDbRealtimeSync();
    syncAdminOrdersFromCloud();
    listenToFirebaseOrdersForAdmin();
    listenToFirebaseVendorSettlementForMerchant();

    // Auto-prompt location picker modal for first-time customers who have no saved location
    checkAndPromptFirstTimeLocation();

    // Immediate startup fetch from online Firebase RTDB to guarantee freshest data on every page load
    fetchOnlineStallsStartup();

    if (!isFirebaseReady()) {
        setTimeout(() => {
            initRiderRealtimeSync();
            initMerchantRealtimeSync();
            initCustomStallsRealtimeSync();
            initCatalogDbRealtimeSync();
            syncAdminOrdersFromCloud();
            listenToFirebaseOrdersForAdmin();
            listenToFirebaseVendorSettlementForMerchant();
            fetchOnlineStallsStartup();
            updateAdminRiderBadges();
            updateAdminStallsBadge();
            updateMerchantSettlementBadge();
        }, 1500);
    }
}

