// ==========================================
// 6-DIGIT RANDOM ACCESS CODE GENERATOR & APPROVAL LIFECYCLE
// ==========================================
function generate6DigitAccessCode(prefix = "") {
    let char1, char2;
    if (prefix && prefix.length >= 2) {
        char1 = prefix.charAt(0).toUpperCase();
        char2 = prefix.charAt(1).toUpperCase();
    } else {
        const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        char1 = letters.charAt(Math.floor(Math.random() * letters.length));
        char2 = letters.charAt(Math.floor(Math.random() * letters.length));
    }

    let digits = "";
    let isValid = false;
    while (!isValid) {
        const d1 = Math.floor(Math.random() * 10);
        const d2 = Math.floor(Math.random() * 10);
        const d3 = Math.floor(Math.random() * 10);
        const d4 = Math.floor(Math.random() * 10);

        const allSame = (d1 === d2 && d2 === d3 && d3 === d4);
        const isIncreasing = (d2 === d1 + 1 && d3 === d2 + 1 && d4 === d3 + 1);
        const isDecreasing = (d2 === d1 - 1 && d3 === d2 - 1 && d4 === d3 - 1);

        if (!allSame && !isIncreasing && !isDecreasing) {
            digits = "" + d1 + d2 + d3 + d4;
            isValid = true;
        }
    }
    return char1 + char2 + digits;
}
window.generate6DigitAccessCode = generate6DigitAccessCode;

let _lastGeneratedSmsInfo = null;

function openSimulatedSmsModal(phone, codeVal, name, roleType, lineId, riderNumber) {
    _lastGeneratedSmsInfo = { phone: phone, code: codeVal, name: name, roleType: roleType, lineId: lineId, riderNumber: riderNumber || "" };
    const modal = document.getElementById("simulated-sms-modal");
    if (!modal) return;

    const phoneEl = document.getElementById("sms-modal-phone");
    const codeEl = document.getElementById("sms-modal-code");
    const msgEl = document.getElementById("sms-modal-message");
    const titleEl = document.getElementById("sms-modal-title");
    const subtitleEl = document.getElementById("sms-modal-subtitle");

    if (phoneEl) phoneEl.textContent = phone || "08x-xxx-xxxx";
    if (codeEl) codeEl.textContent = codeVal;

    const roleName = roleType === "merchant" ? "แผงค้า" : "ไรเดอร์";
    const roleNum = roleType === "merchant" ? "Role 3 (แผงค้า)" : "Role 4 (ไรเดอร์)";

    if (titleEl) titleEl.textContent = "ส่งรหัสเข้าสู่ระบบ" + roleName + "เรียบร้อย";
    if (subtitleEl) subtitleEl.textContent = roleType === "merchant"
        ? "ส่ง SMS & LINE แจ้งเตือนไปยัง " + name + " สำเร็จแล้ว"
        : "กรุณาคัดลอกข้อความนี้ส่งให้ " + name + " ทาง LINE/SMS เอง (ระบบไม่ได้ส่งให้ และจะไม่แสดงรหัสผ่านนี้อีก)";
    if (msgEl && roleType !== "merchant") {
        // ไรเดอร์: เข้าสู่ระบบด้วย "เลขไรเดอร์ + รหัสผ่านลับ" (รหัสผ่านนี้แสดงครั้งเดียว ระบบไม่เก็บรหัสจริง)
        msgEl.innerHTML = "ตลาดวิศิษฐ์ชัย (เฮียส่ง): ยินดีด้วยครับคุณ <strong>" + escapeHtml(name) + "</strong>! ใบสมัครไรเดอร์ได้รับอนุมัติแล้ว เลขไรเดอร์ของคุณคือ <strong class=\"text-amber-300 text-base font-black tracking-wider\">" + escapeHtml(riderNumber || "-") + "</strong> รหัสผ่านเข้าสู่ระบบคือ <strong class=\"text-amber-300 text-base font-black tracking-wider\">" + escapeHtml(codeVal) + "</strong> ใช้ทั้งสองอย่างเข้าสู่ระบบ " + roleNum + " และเก็บรหัสผ่านเป็นความลับ อย่าบอกใคร";
    } else if (msgEl) {
        msgEl.innerHTML = "ตลาดวิศิษฐ์ชัย (เฮียส่ง): ยินดีด้วยครับคุณ <strong>" + escapeHtml(name) + "</strong>! การลงทะเบียนเปิดร้าน/รับงานได้รับการอนุมัติแล้ว รหัสเข้าสู่ระบบ 6 หลักของคุณคือ <strong class=\"text-amber-300 text-base font-black tracking-wider\">" + escapeHtml(codeVal) + "</strong> นำรหัสนี้ไปใส่ใน " + roleNum + " เพื่อเริ่มปฏิบัติงานได้ทันทีครับ";
    }

    modal.classList.remove("hidden");
}
window.openSimulatedSmsModal = openSimulatedSmsModal;

